func describe(c *gin.Context) {
	var b strings.Builder
	b.WriteString(c.FullPath())
	for _, p := range c.Params {
		fmt.Fprintf(&b, " %s=%q", p.Key, p.Value)
	}
	c.String(http.StatusOK, b.String())
}

func newRouter() *gin.Engine {
	r := gin.New()
	r.GET("/users/:id", describe)
	r.GET("/users/new", describe)
	r.GET("/users/:id/posts/:slug", describe)
	r.GET("/files/*path", describe)
	return r
}

func send(r *gin.Engine, path string) {
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, path, nil))
	detail := w.Body.String()
	if loc := w.Header().Get("Location"); loc != "" {
		detail = "Location: " + loc
	}
	fmt.Println(path, w.Code, detail)
}

func main() {
	gin.SetMode(gin.TestMode)
	r := newRouter()
	for _, path := range []string{
		"/users/42",
		"/users/new",
		"/users/42/posts/hello-gin",
		"/files/docs/guide.pdf",
		"/files/",
		"/users/42/",
		"/users/",
		"/users/a%2Fb",
	} {
		send(r, path)
	}
	raw := newRouter()
	raw.UseRawPath = true
	send(raw, "/users/a%2Fb")
}

