package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"reflect"
	"regexp"
	"strconv"
	"strings"

	"github.com/gin-gonic/gin"
	"github.com/gin-gonic/gin/binding"
	"github.com/go-playground/validator/v10"
)

type line struct {
	SKU string `json:"sku" binding:"required,sku"`
	Qty int    `json:"qty" binding:"min=1,max=99"`
}

type order struct {
	Items   []line   `json:"items" binding:"required,min=1,max=20,dive"`
	Coupons []string `json:"coupons" binding:"max=3,dive,alphanum,len=8"`
	Pickup  bool     `json:"pickup"`
	Address string   `json:"address" binding:"max=200"`
}

var skuPattern = regexp.MustCompile(`^[A-Z]{3}-[0-9]{4}$`)

// setupValidation runs once at startup, before the engine serves requests.
func setupValidation() error {
	v, ok := binding.Validator.Engine().(*validator.Validate)
	if !ok {
		return errors.New("binding.Validator is not go-playground/validator")
	}
	v.RegisterTagNameFunc(func(f reflect.StructField) string {
		name, _, _ := strings.Cut(f.Tag.Get("json"), ",")
		if name == "-" {
			return ""
		}
		return name
	})
	if err := v.RegisterValidation("sku", func(fl validator.FieldLevel) bool {
		return skuPattern.MatchString(fl.Field().String())
	}); err != nil {
		return err
	}
	v.RegisterStructValidation(func(sl validator.StructLevel) {
		o := sl.Current().Interface().(order)
		if !o.Pickup && strings.TrimSpace(o.Address) == "" {
			sl.ReportError(o.Address, "address", "Address", "required_unless_pickup", "")
		}
	}, order{})
	return nil
}

type fieldError struct {
	Field string `json:"field"`
	Rule  string `json:"rule"`
	Param string `json:"param,omitempty"`
}

// wirePath turns "items.0.qty" from encoding/json into "items[0].qty".
func wirePath(field string) string {
	var b strings.Builder
	for i, part := range strings.Split(field, ".") {
		if _, err := strconv.Atoi(part); err == nil {
			b.WriteString("[" + part + "]")
			continue
		}
		if i > 0 {
			b.WriteByte('.')
		}
		b.WriteString(part)
	}
	return b.String()
}

func writeBindError(c *gin.Context, err error) {
	var invalid validator.ValidationErrors
	var typeErr *json.UnmarshalTypeError
	switch {
	case errors.As(err, &invalid):
		out := make([]fieldError, 0, len(invalid))
		for _, fe := range invalid {
			_, path, _ := strings.Cut(fe.Namespace(), ".")
			out = append(out, fieldError{Field: path, Rule: fe.Tag(), Param: fe.Param()})
		}
		c.JSON(http.StatusUnprocessableEntity, gin.H{"errors": out})
	case errors.As(err, &typeErr):
		c.JSON(http.StatusBadRequest, gin.H{"errors": []fieldError{{Field: wirePath(typeErr.Field), Rule: "type"}}})
	default:
		c.JSON(http.StatusBadRequest, gin.H{"error": "malformed JSON body"})
	}
}

func createOrder(c *gin.Context) {
	var in order
	if err := c.ShouldBindJSON(&in); err != nil {
		writeBindError(c, err)
		return
	}
	c.JSON(http.StatusCreated, gin.H{"lines": len(in.Items)})
}

func main() {
	gin.SetMode(gin.TestMode)
	if err := setupValidation(); err != nil {
		panic(err)
	}
	r := gin.New()
	r.POST("/orders", createOrder)

	for _, body := range []string{
		`{"items":[{"sku":"ABC-1234","qty":2}],"pickup":true}`,
		`{"items":[{"sku":"ABC-1234","qty":2},{"sku":"abc","qty":0}],"coupons":["SAVE2026","x"]}`,
		`{"items":[],"address":"1 Main St"}`,
		`{"items":[{"sku":"ABC-1234","qty":"2"}],"pickup":true}`,
		`{"items":[`,
	} {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(http.MethodPost, "/orders", strings.NewReader(body)))
		fmt.Println(w.Code, w.Body.String())
	}
}

// setupOnce makes registration safe when tests build routers in parallel.
var setupOnce = sync.OnceValue(setupValidation)

func newRouter() (*gin.Engine, error) {
	if err := setupOnce(); err != nil {
		return nil, err
	}
	r := gin.New()
	r.POST("/orders", createOrder)
	return r, nil
}

