package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

// ctxKey is unexported, so no other package can collide with these keys.
type ctxKey int

const (
	requestIDKey ctxKey = iota
	userKey
)

type user struct {
	ID   string
	Role string
}

var trace []string

func accessLog(lines *[]string) gin.HandlerFunc {
	return func(c *gin.Context) {
		trace = append(trace, "log>")
		c.Next() // everything below runs after the rest of the chain
		trace = append(trace, "<log")
		route := c.FullPath()
		if route == "" {
			route = "unmatched"
		}
		*lines = append(*lines, fmt.Sprintf("id=%s %s %s status=%d aborted=%t",
			c.GetString(requestIDKey), c.Request.Method, route, c.Writer.Status(), c.IsAborted()))
	}
}

func requestID(next func() string) gin.HandlerFunc {
	return func(c *gin.Context) {
		id := c.GetHeader("X-Request-Id")
		if id == "" || len(id) > 64 {
			id = next()
		}
		c.Set(requestIDKey, id)
		c.Header("X-Request-Id", id)
		trace = append(trace, "id")
		// No c.Next(): Gin continues the chain when this function returns.
	}
}

func requireUser(c *gin.Context) {
	tokens := map[string]user{"t-user": {ID: "u-1", Role: "member"}, "t-admin": {ID: "u-2", Role: "admin"}}
	u, ok := tokens[strings.TrimPrefix(c.GetHeader("Authorization"), "Bearer ")]
	if !ok {
		trace = append(trace, "user:abort")
		c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthenticated"})
		return // Abort stops later handlers, return stops this one
	}
	trace = append(trace, "user")
	c.Set(userKey, u)
}

func requireRole(role string) gin.HandlerFunc {
	return func(c *gin.Context) {
		if currentUser(c).Role != role {
			trace = append(trace, "role:abort")
			c.AbortWithStatusJSON(http.StatusForbidden, gin.H{"error": "forbidden"})
			return
		}
		trace = append(trace, "role")
	}
}

// currentUser is only called behind requireUser, so a missing key is a wiring bug.
func currentUser(c *gin.Context) user {
	return c.MustGet(userKey).(user)
}

func main() {
	gin.SetMode(gin.TestMode)
	var lines []string
	n := 0
	r := gin.New()
	r.Use(accessLog(&lines), requestID(func() string { n++; return fmt.Sprintf("req-%d", n) }))
	r.GET("/health", func(c *gin.Context) { trace = append(trace, "health"); c.Status(http.StatusOK) })
	r.GET("/me", requireUser, func(c *gin.Context) {
		trace = append(trace, "me")
		c.JSON(http.StatusOK, gin.H{"id": currentUser(c).ID})
	})
	r.DELETE("/users/:id", requireUser, requireRole("admin"), func(c *gin.Context) {
		trace = append(trace, "delete")
		c.Status(http.StatusNoContent)
	})

	for _, tc := range []struct{ method, path, token, reqID string }{
		{"GET", "/health", "", ""},
		{"GET", "/me", "", ""},
		{"GET", "/me", "t-user", "client-7"},
		{"DELETE", "/users/9", "t-user", ""},
		{"DELETE", "/users/9", "t-admin", ""},
		{"GET", "/missing", "", ""},
	} {
		trace = nil
		req := httptest.NewRequest(tc.method, tc.path, nil)
		if tc.token != "" {
			req.Header.Set("Authorization", "Bearer "+tc.token)
		}
		if tc.reqID != "" {
			req.Header.Set("X-Request-Id", tc.reqID)
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Println(tc.method, tc.path, w.Code, trace)
	}
	for _, line := range lines {
		fmt.Println(line)
	}
}

package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"mime/multipart"
	"net/http"
	"net/http/httptest"
	"net/textproto"

	"github.com/gin-gonic/gin"
)

const (
	maxRequestBytes = 8 << 10 // whole multipart body; tiny so the demo can exceed it
	maxFileBytes    = 4 << 10
)

// allowed maps a sniffed type to the only extension we will ever store.
var allowed = map[string]string{"image/png": ".png", "image/jpeg": ".jpg", "image/gif": ".gif", "image/webp": ".webp"}

func uploadAvatar(c *gin.Context) {
	c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, maxRequestBytes)
	fh, err := c.FormFile("avatar")
	if err != nil {
		var tooLarge *http.MaxBytesError
		switch {
		case errors.As(err, &tooLarge):
			c.JSON(http.StatusRequestEntityTooLarge, gin.H{"error": "request exceeds 8 KiB"})
		case errors.Is(err, http.ErrMissingFile):
			c.JSON(http.StatusBadRequest, gin.H{"error": "avatar file is required"})
		default:
			c.JSON(http.StatusBadRequest, gin.H{"error": "expected multipart/form-data"})
		}
		return
	}
	if fh.Size > maxFileBytes {
		c.JSON(http.StatusRequestEntityTooLarge, gin.H{"error": "avatar exceeds 4 KiB"})
		return
	}
	f, err := fh.Open()
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "cannot read upload"})
		return
	}
	defer f.Close()

	head := make([]byte, 512)
	n, _ := io.ReadFull(f, head) // a short file is fine: sniff what we got
	kind := http.DetectContentType(head[:n])
	ext, ok := allowed[kind]
	if !ok {
		c.JSON(http.StatusUnsupportedMediaType, gin.H{"error": "unsupported file type", "detected": kind})
		return
	}

	if _, err := f.Seek(0, io.SeekStart); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "cannot read upload"})
		return
	}
	sum := sha256.New()
	if _, err := io.Copy(sum, f); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "cannot read upload"})
		return
	}
	name := hex.EncodeToString(sum.Sum(nil))[:24] + ext
	// A real service now streams f to object storage under name.
	c.JSON(http.StatusCreated, gin.H{"stored_as": name, "bytes": fh.Size, "type": kind, "original": fh.Filename})
}

// multipartBody builds the request a browser would send for <input type=file>.
func multipartBody(field, filename, declaredType string, content []byte) (*bytes.Buffer, string) {
	var buf bytes.Buffer
	mw := multipart.NewWriter(&buf)
	must(mw.SetBoundary("lesson-boundary-0123456789"))
	must(mw.WriteField("caption", "profile picture"))
	if field != "" {
		h := make(textproto.MIMEHeader)
		h.Set("Content-Disposition", fmt.Sprintf(`form-data; name=%q; filename=%q`, field, filename))
		h.Set("Content-Type", declaredType) // the client's claim; the handler ignores it
		part, err := mw.CreatePart(h)
		must(err)
		_, err = part.Write(content)
		must(err)
	}
	must(mw.Close())
	return &buf, mw.FormDataContentType()
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.MaxMultipartMemory = 1 << 20 // in-memory threshold for file parts, not a size limit
	r.POST("/avatars", uploadAvatar)

	png := append([]byte("\x89PNG\r\n\x1a\n"), bytes.Repeat([]byte{0}, 56)...)
	cases := []struct {
		field, filename, declared string
		content                   []byte
	}{
		{"avatar", "../../avatar.png", "image/png", png},
		{"avatar", "avatar.png", "image/png", []byte("<?php system($_GET['c']); ?>")},
		{"avatar", "cat.gif", "image/gif", []byte("<html><script>alert(1)</script>")},
		{"avatar", "big.png", "image/png", append(png, make([]byte, 5<<10)...)},
		{"avatar", "huge.png", "image/png", append(png, make([]byte, 10<<10)...)},
		{"", "", "", nil},
	}
	for _, tc := range cases {
		body, contentType := multipartBody(tc.field, tc.filename, tc.declared, tc.content)
		req := httptest.NewRequest(http.MethodPost, "/avatars", body)
		req.Header.Set("Content-Type", contentType)
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Println(w.Code, w.Body.String())
	}

	req := httptest.NewRequest(http.MethodPost, "/avatars", bytes.NewReader([]byte(`{"avatar":"..."}`)))
	req.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println(w.Code, w.Body.String())
}

func streamAvatar(c *gin.Context) {
	c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, 20<<20)
	mr, err := c.Request.MultipartReader() // no buffering, no temp files
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "expected multipart/form-data"})
		return
	}
	for {
		part, err := mr.NextPart()
		if err == io.EOF {
			break
		}
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "malformed upload"})
			return
		}
		if part.FormName() != "avatar" {
			continue
		}
		br := bufio.NewReaderSize(part, 512)
		head, _ := br.Peek(512) // fewer bytes for a short part is fine
		if _, ok := allowed[http.DetectContentType(head)]; !ok {
			c.JSON(http.StatusUnsupportedMediaType, gin.H{"error": "unsupported file type"})
			return
		}
		// Copy br to storage through a hash writer, then commit the name.
	}
}

