	"github.com/gin-gonic/gin"
)

// site stands in for an embed.FS; the files are inline so the lesson is one main.go.
var site = fstest.MapFS{
	"templates/header.html": {Data: []byte(`{{define "header"}}<!doctype html><title>{{.Title}}</title>` +
		`<link rel="stylesheet" href="{{asset "app.css"}}">{{end}}`)},
	"templates/profile.html": {Data: []byte(`{{define "profile.html"}}{{template "header" .}}` +
		`<h1>{{.Name}}</h1><a href="/search?q={{.Name}}">search</a><script>const name = {{.Name}};</script>{{end}}`)},
	"static/app.5d41402a.css": {Data: []byte("body{margin:0}")},
	"static/logo.svg":         {Data: []byte(`<svg xmlns="http://www.w3.org/2000/svg"/>`)},
}

// manifest maps logical asset names to the fingerprinted files a build step wrote.
var manifest = map[string]string{"app.css": "app.5d41402a.css"}

var fingerprinted = regexp.MustCompile(`\.[0-9a-f]{8}\.`)

func cacheAssets(fsys fs.FS) gin.HandlerFunc {
	return func(c *gin.Context) {
		name := strings.TrimPrefix(c.Param("filepath"), "/")
		info, err := fs.Stat(fsys, name)
		switch {
		case err != nil || info.IsDir():
			// No cache header on 404s.
		case fingerprinted.MatchString(name):
			c.Header("Cache-Control", "public, max-age=31536000, immutable")
		default:
			c.Header("Cache-Control", "public, max-age=300")
		}
	}
}

// renderPage executes into a buffer so a template error becomes a clean 500.
func renderPage(c *gin.Context, t *template.Template, name string, data any) {
	var buf bytes.Buffer
	if err := t.ExecuteTemplate(&buf, name, data); err != nil {
		_ = c.Error(err)
		c.String(http.StatusInternalServerError, "page unavailable")
		return
	}
	c.Data(http.StatusOK, "text/html; charset=utf-8", buf.Bytes())
}

func main() {
	gin.SetMode(gin.TestMode)
	funcs := template.FuncMap{"asset": func(name string) string { return "/static/" + manifest[name] }}
	tmpl := template.Must(template.New("").Funcs(funcs).ParseFS(site, "templates/*.html"))

	r := gin.New()
	r.SetHTMLTemplate(tmpl)
	r.GET("/users/:id", func(c *gin.Context) {
		c.Header("Cache-Control", "no-cache")
		c.HTML(http.StatusOK, "profile.html", gin.H{"Title": "Profile", "Name": `<img src=x onerror=alert(1)>`})
	})
	r.GET("/broken", func(c *gin.Context) { c.HTML(http.StatusOK, "missing.html", nil) })
	r.GET("/broken-buffered", func(c *gin.Context) { renderPage(c, tmpl, "missing.html", nil) })

	static, err := fs.Sub(site, "static")
	if err != nil {
		panic(err)
	}
	assets := r.Group("/static", cacheAssets(static))
	assets.StaticFS("/", &gin.OnlyFilesFS{FileSystem: http.FS(static)})

	for _, path := range []string{
		"/users/7", "/broken", "/broken-buffered",
		"/static/app.5d41402a.css", "/static/logo.svg", "/static/missing.css",
	} {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, path, nil))
		fmt.Printf("%s %d type=%q cache=%q bytes=%d\n", path, w.Code,
			w.Header().Get("Content-Type"), w.Header().Get("Cache-Control"), w.Body.Len())
		if strings.HasPrefix(path, "/users/") {
			fmt.Println(w.Body.String())
		}
	}
}

//go:embed templates/*.html static
var site embed.FS

func newRouter() (*gin.Engine, error) {
	tmpl, err := template.New("").Funcs(funcs).ParseFS(site, "templates/*.html")
	if err != nil {
		return nil, err // a syntax error fails startup, not a request
	}
	static, err := fs.Sub(site, "static")
	if err != nil {
		return nil, err
	}
	r := gin.New()
	r.SetHTMLTemplate(tmpl) // before serving: it is not safe to swap later
	assets := r.Group("/static", cacheAssets(static))
	assets.StaticFS("/", &gin.OnlyFilesFS{FileSystem: http.FS(static)})
	return r, nil
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

type apiError struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// safeNext accepts only same-site absolute paths, so ?next= cannot become an open redirect.
func safeNext(raw string) string {
	if !strings.HasPrefix(raw, "/") || strings.HasPrefix(raw, "//") || strings.ContainsRune(raw, '\\') {
		return "/"
	}
	return raw
}

func newRouter() *gin.Engine {
	r := gin.New()
	r.HandleMethodNotAllowed = true
	r.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, apiError{Code: "not_found", Message: "no such resource"})
	})
	r.NoMethod(func(c *gin.Context) {
		// Gin has already set Allow from the registered routes.
		c.JSON(http.StatusMethodNotAllowed, apiError{Code: "method_not_allowed", Message: "allowed: " + c.Writer.Header().Get("Allow")})
	})

	api := r.Group("/api")
	api.GET("/items", func(c *gin.Context) { c.JSON(http.StatusOK, []string{"a", "b"}) })
	api.POST("/items", func(c *gin.Context) { c.Status(http.StatusCreated) })
	api.GET("/items/:id", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"id": c.Param("id")}) })
	api.DELETE("/items/:id", func(c *gin.Context) { c.Status(http.StatusNoContent) })
	api.Match([]string{http.MethodGet, http.MethodHead}, "/health", func(c *gin.Context) { c.Status(http.StatusOK) })

	r.GET("/old-items", func(c *gin.Context) { c.Redirect(http.StatusMovedPermanently, "/api/items") })
	r.POST("/old-items", func(c *gin.Context) { c.Redirect(http.StatusPermanentRedirect, "/api/items") })
	r.POST("/checkout", func(c *gin.Context) { c.Redirect(http.StatusSeeOther, "/orders/42") })
	r.GET("/login/done", func(c *gin.Context) { c.Redirect(http.StatusSeeOther, safeNext(c.Query("next"))) })
	return r
}

func main() {
	gin.SetMode(gin.TestMode)
	r := newRouter()
	for _, line := range []string{
		"GET /api/items",
		"PUT /api/items",
		"HEAD /api/items",
		"PATCH /api/items/7",
		"HEAD /api/health",
		"GET /api/nothing",
		"GET /api/items/",
		"GET /old-items",
		"POST /old-items",
		"POST /checkout",
		"GET /login/done?next=/api/items",
		"GET /login/done?next=//evil.example",
		"GET /login/done?next=https://evil.example",
	} {
		method, target, _ := strings.Cut(line, " ")
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(method, target, nil))
		out := []string{line, "->", fmt.Sprint(w.Code)}
		if allow := w.Header().Get("Allow"); allow != "" {
			out = append(out, "Allow: "+allow)
		}
		if loc := w.Header().Get("Location"); loc != "" {
			out = append(out, "Location: "+loc)
		}
		if strings.HasPrefix(w.Header().Get("Content-Type"), "application/json") {
			out = append(out, w.Body.String())
		}
		fmt.Println(strings.Join(out, " "))
	}
}

r.NoRoute(func(c *gin.Context) {
	if strings.HasPrefix(c.Request.URL.Path, "/api/") {
		c.JSON(http.StatusNotFound, apiError{Code: "not_found", Message: "no such resource"})
		return
	}
	c.HTML(http.StatusNotFound, "404.html", gin.H{"Title": "Page not found"})
})

package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

// Principal is everything downstream code may know about the caller.
type Principal struct {
	Subject string
	Scopes  []string
}

// principalKey is unexported, so no other package can overwrite the value.
type principalKey struct{}

var (
	errMalformed = errors.New("malformed token")
	errSignature = errors.New("bad signature")
	errExpired   = errors.New("expired")
)

// Verifier checks tokens shaped base64url(payload) "." base64url(HMAC-SHA256).
type Verifier struct {
	key []byte
	now func() time.Time
}

func (v Verifier) mac(payload []byte) []byte {
	m := hmac.New(sha256.New, v.key)
	m.Write(payload)
	return m.Sum(nil)
}

// Issue exists for the demo; in production a separate login flow issues tokens.
func (v Verifier) Issue(subject, scopes string, exp time.Time) string {
	payload := []byte(subject + "|" + scopes + "|" + strconv.FormatInt(exp.Unix(), 10))
	enc := base64.RawURLEncoding
	return enc.EncodeToString(payload) + "." + enc.EncodeToString(v.mac(payload))
}

func (v Verifier) Verify(token string) (Principal, error) {
	encPayload, encMAC, ok := strings.Cut(token, ".")
	if !ok {
		return Principal{}, errMalformed
	}
	payload, err1 := base64.RawURLEncoding.DecodeString(encPayload)
	got, err2 := base64.RawURLEncoding.DecodeString(encMAC)
	if err1 != nil || err2 != nil {
		return Principal{}, errMalformed
	}
	if !hmac.Equal(got, v.mac(payload)) {
		return Principal{}, errSignature
	}
	// Only a payload with a valid MAC is worth parsing.
	parts := strings.Split(string(payload), "|")
	if len(parts) != 3 {
		return Principal{}, errMalformed
	}
	exp, err := strconv.ParseInt(parts[2], 10, 64)
	if err != nil {
		return Principal{}, errMalformed
	}
	if !v.now().Before(time.Unix(exp, 0)) {
		return Principal{}, errExpired
	}
	return Principal{Subject: parts[0], Scopes: strings.Fields(parts[1])}, nil
}

const realm = `Bearer realm="notes"`

func authenticate(v Verifier, log *slog.Logger) gin.HandlerFunc {
	return func(c *gin.Context) {
		scheme, token, ok := strings.Cut(c.GetHeader("Authorization"), " ")
		if !ok || !strings.EqualFold(scheme, "Bearer") || token == "" {
			c.Header("WWW-Authenticate", realm)
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "authentication required"})
			return
		}
		p, err := v.Verify(token)
		if err != nil {
			// Log the route and the reason, never the credential.
			log.Info("auth rejected", "route", c.FullPath(), "reason", err.Error())
			c.Header("WWW-Authenticate", realm+`, error="invalid_token"`)
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "invalid token"})
			return
		}
		c.Set(principalKey{}, p)
		c.Next()
	}
}

func principalFrom(c *gin.Context) (Principal, bool) {
	v, ok := c.Get(principalKey{})
	if !ok {
		return Principal{}, false
	}
	p, ok := v.(Principal)
	return p, ok
}

func requireScope(scope string) gin.HandlerFunc {
	return func(c *gin.Context) {
		p, ok := principalFrom(c)
		if !ok {
			// A route was wired without authenticate: fail closed.
			c.AbortWithStatus(http.StatusInternalServerError)
			return
		}
		if !slices.Contains(p.Scopes, scope) {
			c.Header("WWW-Authenticate", realm+`, error="insufficient_scope", scope="`+scope+`"`)
			c.AbortWithStatusJSON(http.StatusForbidden, gin.H{"error": "insufficient scope"})
			return
		}
		c.Next()
	}
}

func newRouter(v Verifier, log *slog.Logger) *gin.Engine {
	r := gin.New()
	r.GET("/healthz", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"status": "ok"}) })

	api := r.Group("/api", authenticate(v, log))
	api.GET("/notes", func(c *gin.Context) {
		p, _ := principalFrom(c)
		c.JSON(http.StatusOK, gin.H{"owner": p.Subject})
	})
	admin := api.Group("/admin", requireScope("notes:admin"))
	admin.DELETE("/notes/:id", func(c *gin.Context) { c.Status(http.StatusNoContent) })
	return r
}

func main() {
	gin.SetMode(gin.TestMode)
	now := time.Unix(1_800_000_000, 0)
	// Test key only. A real key comes from a secret store and is rotated.
	v := Verifier{key: []byte("test-only-key-0123456789abcdef!!"), now: func() time.Time { return now }}
	log := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{
		ReplaceAttr: func(groups []string, a slog.Attr) slog.Attr {
			if a.Key == slog.TimeKey && len(groups) == 0 {
				return slog.Attr{}
			}
			return a
		},
	}))
	r := newRouter(v, log)

	reader := v.Issue("user-42", "notes:read", now.Add(15*time.Minute))
	expired := v.Issue("user-42", "notes:read", now.Add(-time.Minute))
	// Swap in an admin payload but keep the reader's MAC.
	forged := base64.RawURLEncoding.EncodeToString([]byte("user-42|notes:read notes:admin|1800000900")) +
		reader[strings.IndexByte(reader, '.'):]

	cases := []struct{ method, path, auth string }{
		{"GET", "/healthz", ""},
		{"GET", "/api/notes", ""},
		{"GET", "/api/notes", "Bearer " + forged},
		{"GET", "/api/notes", "Bearer " + expired},
		{"GET", "/api/notes", "bearer " + reader},
		{"DELETE", "/api/admin/notes/7", "Bearer " + reader},
	}
	for _, tc := range cases {
		req := httptest.NewRequest(tc.method, tc.path, nil)
		if tc.auth != "" {
			req.Header.Set("Authorization", tc.auth)
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Println(tc.method, tc.path, w.Code, w.Body.String())
		if h := w.Header().Get("WWW-Authenticate"); h != "" {
			fmt.Println("  WWW-Authenticate:", h)
		}
	}
}

// In auth_test.go: every route outside the public allow-list must refuse anonymous calls.
func TestRoutesRequireAuth(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := newRouter(testVerifier(), slog.New(slog.DiscardHandler))
	public := map[string]bool{"GET /healthz": true}
	for _, rt := range r.Routes() {
		if public[rt.Method+" "+rt.Path] {
			continue
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(rt.Method, rt.Path, nil))
		if w.Code != http.StatusUnauthorized {
			t.Errorf("%s %s answered %d without a token", rt.Method, rt.Path, w.Code)
		}
	}
}

package main

import (
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

type CORSConfig struct {
	Origins     []string // exact scheme://host[:port] values
	Methods     []string // methods a preflight may ask for
	Headers     []string // request headers a preflight may ask for
	Credentials bool     // allow cookies or Authorization from the page
	MaxAge      time.Duration
}

func newCORS(cfg CORSConfig) (gin.HandlerFunc, error) {
	origins := map[string]bool{}
	for _, o := range cfg.Origins {
		if o == "*" && cfg.Credentials {
			return nil, errors.New(`cors: "*" cannot be combined with credentials`)
		}
		if o == "null" {
			return nil, errors.New(`cors: never allow the "null" origin`)
		}
		origins[o] = true
	}
	headers := map[string]bool{}
	for _, h := range cfg.Headers {
		headers[strings.ToLower(h)] = true
	}
	allowMethods := strings.Join(cfg.Methods, ", ")
	allowHeaders := strings.Join(cfg.Headers, ", ")
	maxAge := strconv.Itoa(int(cfg.MaxAge / time.Second))

	return func(c *gin.Context) {
		h := c.Writer.Header()
		// The response depends on Origin whether or not one was sent.
		h.Add("Vary", "Origin")
		origin := c.GetHeader("Origin")
		preflight := c.Request.Method == http.MethodOptions &&
			c.GetHeader("Access-Control-Request-Method") != ""
		if preflight {
			h.Add("Vary", "Access-Control-Request-Method")
			h.Add("Vary", "Access-Control-Request-Headers")
		}
		allowed := origin != "" && (origins[origin] || origins["*"])
		if !allowed {
			if preflight {
				c.AbortWithStatus(http.StatusForbidden)
				return
			}
			c.Next() // no CORS headers: the browser hides the response from the page
			return
		}
		if origins["*"] {
			h.Set("Access-Control-Allow-Origin", "*")
		} else {
			h.Set("Access-Control-Allow-Origin", origin)
		}
		if cfg.Credentials {
			h.Set("Access-Control-Allow-Credentials", "true")
		}
		if !preflight {
			c.Next()
			return
		}
		if !slices.Contains(cfg.Methods, c.GetHeader("Access-Control-Request-Method")) {
			c.AbortWithStatus(http.StatusForbidden)
			return
		}
		for name := range strings.SplitSeq(c.GetHeader("Access-Control-Request-Headers"), ",") {
			if name = strings.ToLower(strings.TrimSpace(name)); name != "" && !headers[name] {
				c.AbortWithStatus(http.StatusForbidden)
				return
			}
		}
		h.Set("Access-Control-Allow-Methods", allowMethods)
		h.Set("Access-Control-Allow-Headers", allowHeaders)
		h.Set("Access-Control-Max-Age", maxAge)
		c.AbortWithStatus(http.StatusNoContent)
	}, nil
}

func show(r http.Handler, method, origin string, extra ...string) {
	req := httptest.NewRequest(method, "/api/notes", nil)
	if origin != "" {
		req.Header.Set("Origin", origin)
	}
	for i := 0; i+1 < len(extra); i += 2 {
		req.Header.Set(extra[i], extra[i+1])
	}
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	line := fmt.Sprintf("%s from %q: %d", method, origin, w.Code)
	if body := w.Body.String(); body != "" {
		line += " " + body
	}
	fmt.Println(line)
	for _, k := range []string{"Access-Control-Allow-Origin", "Access-Control-Allow-Credentials",
		"Access-Control-Allow-Methods", "Access-Control-Allow-Headers", "Access-Control-Max-Age"} {
		if v := w.Header().Get(k); v != "" {
			fmt.Printf("  %s: %s\n", k, v)
		}
	}
	fmt.Printf("  Vary: %s\n", strings.Join(w.Header().Values("Vary"), ", "))
}

func main() {
	gin.SetMode(gin.TestMode)
	if _, err := newCORS(CORSConfig{Origins: []string{"*"}, Credentials: true}); err != nil {
		fmt.Println("rejected config:", err)
	}
	cors, err := newCORS(CORSConfig{
		Origins:     []string{"https://app.example.com"},
		Methods:     []string{"GET", "POST", "PUT", "DELETE"},
		Headers:     []string{"Authorization", "Content-Type"},
		Credentials: true,
		MaxAge:      10 * time.Minute,
	})
	if err != nil {
		panic(err)
	}
	r := gin.New()
	r.Use(cors) // engine-wide, so it also runs for OPTIONS requests that match no route
	r.GET("/api/notes", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"notes": 3}) })

	show(r, "OPTIONS", "https://app.example.com",
		"Access-Control-Request-Method", "PUT",
		"Access-Control-Request-Headers", "authorization,content-type")
	show(r, "OPTIONS", "https://evil.example", "Access-Control-Request-Method", "PUT")
	show(r, "GET", "https://app.example.com")
	show(r, "GET", "https://evil.example")
	show(r, "GET", "")
}

package main

import (
	"container/list"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
	"golang.org/x/time/rate"
)

// Limiters keeps one token bucket per client key, at most max of them.
type Limiters struct {
	mu    sync.Mutex
	limit rate.Limit
	burst int
	max   int
	lru   *list.List // front = most recently used
	byKey map[string]*list.Element
}

type bucket struct {
	key string
	lim *rate.Limiter
}

func NewLimiters(limit rate.Limit, burst, max int) *Limiters {
	return &Limiters{limit: limit, burst: burst, max: max, lru: list.New(), byKey: map[string]*list.Element{}}
}

func (s *Limiters) get(key string) *rate.Limiter {
	s.mu.Lock()
	defer s.mu.Unlock()
	if el, ok := s.byKey[key]; ok {
		s.lru.MoveToFront(el)
		return el.Value.(*bucket).lim
	}
	if s.lru.Len() >= s.max {
		oldest := s.lru.Back()
		s.lru.Remove(oldest)
		delete(s.byKey, oldest.Value.(*bucket).key)
	}
	b := &bucket{key: key, lim: rate.NewLimiter(s.limit, s.burst)}
	s.byKey[key] = s.lru.PushFront(b)
	return b.lim
}

func (s *Limiters) Keys() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	var keys []string
	for el := s.lru.Front(); el != nil; el = el.Next() {
		keys = append(keys, el.Value.(*bucket).key)
	}
	return keys
}

type subjectKey struct{}

// fakeAuth stands in for the bearer-token middleware of the auth lesson.
func fakeAuth(c *gin.Context) {
	if c.GetHeader("Authorization") == "Bearer t-user-17" {
		c.Set(subjectKey{}, "user-17")
	}
	c.Next()
}

func clientKey(c *gin.Context) string {
	if sub, ok := c.Get(subjectKey{}); ok {
		return "user:" + sub.(string)
	}
	return "ip:" + c.ClientIP() // safe only because trusted proxies are configured
}

func rateLimit(s *Limiters, now func() time.Time) gin.HandlerFunc {
	return func(c *gin.Context) {
		t := now()
		res := s.get(clientKey(c)).ReserveN(t, 1)
		if !res.OK() {
			c.AbortWithStatus(http.StatusTooManyRequests) // burst < 1: never allowed
			return
		}
		if d := res.DelayFrom(t); d > 0 {
			res.CancelAt(t) // we will not wait, so return the reserved token
			c.Header("Retry-After", strconv.Itoa(int((d+time.Second-1)/time.Second)))
			c.AbortWithStatusJSON(http.StatusTooManyRequests, gin.H{"error": "rate limited"})
			return
		}
		c.Next()
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	start := time.Date(2026, 11, 1, 12, 0, 0, 0, time.UTC)
	now := start
	limiters := NewLimiters(rate.Every(time.Second), 2, 3)

	r := gin.New()
	if err := r.SetTrustedProxies([]string{"192.0.2.1"}); err != nil {
		panic(err)
	}
	r.Use(fakeAuth, rateLimit(limiters, func() time.Time { return now }))
	r.GET("/api/search", func(c *gin.Context) { c.String(http.StatusOK, clientKey(c)) })

	send := func(label, peer, xff, auth string) {
		req := httptest.NewRequest("GET", "/api/search", nil)
		req.RemoteAddr = peer + ":40000"
		if xff != "" {
			req.Header.Set("X-Forwarded-For", xff)
		}
		if auth != "" {
			req.Header.Set("Authorization", auth)
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		line := fmt.Sprintf("t=%v %s: %d %s", now.Sub(start), label, w.Code, w.Body.String())
		if ra := w.Header().Get("Retry-After"); ra != "" {
			line += " Retry-After=" + ra
		}
		fmt.Println(line)
	}

	for range 3 {
		send("user-17", "192.0.2.1", "198.51.100.7", "Bearer t-user-17")
	}
	send("anonymous via proxy", "192.0.2.1", "198.51.100.7", "")
	for _, spoof := range []string{"10.0.0.1", "10.0.0.2", "10.0.0.3"} {
		send("direct, spoofed XFF "+spoof, "203.0.113.9", spoof, "")
	}
	now = start.Add(time.Second)
	send("user-17", "192.0.2.1", "198.51.100.7", "Bearer t-user-17")
	send("new client", "192.0.2.1", "198.51.100.8", "")
	fmt.Println("buckets:", strings.Join(limiters.Keys(), " "))
}

package main

import (
	"context"
	"fmt"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

type requestIDKey struct{}

// validRequestID accepts 8 to 64 characters from a conservative alphabet.
func validRequestID(s string) bool {
	if len(s) < 8 || len(s) > 64 {
		return false
	}
	for _, r := range s {
		ok := r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '-' || r == '_' || r == '.'
		if !ok {
			return false
		}
	}
	return true
}

func requestID(generate func() string) gin.HandlerFunc {
	return func(c *gin.Context) {
		id := c.GetHeader("X-Request-ID")
		if !validRequestID(id) {
			id = generate()
		}
		c.Set(requestIDKey{}, id)
		c.Request = c.Request.WithContext(context.WithValue(c.Request.Context(), requestIDKey{}, id))
		c.Header("X-Request-ID", id)
		c.Next()
	}
}

func accessLog(log *slog.Logger) gin.HandlerFunc {
	return func(c *gin.Context) {
		start := time.Now()
		c.Next()
		route := c.FullPath() // "/notes/:id", never "/notes/42?token=..."
		if route == "" {
			route = "unmatched"
		}
		status := c.Writer.Status()
		level := slog.LevelInfo
		if status >= 500 {
			level = slog.LevelError
		}
		id, _ := c.Get(requestIDKey{})
		log.LogAttrs(c.Request.Context(), level, "request",
			slog.Any("request_id", id),
			slog.String("method", c.Request.Method),
			slog.String("route", route),
			slog.Int("status", status),
			slog.Duration("latency", time.Since(start)),
			slog.Group("headers",
				slog.String("user_agent", c.Request.UserAgent()),
				slog.String("authorization", c.GetHeader("Authorization"))),
		)
	}
}

// redact is the production ReplaceAttr: credentials never reach the sink.
func redact(groups []string, a slog.Attr) slog.Attr {
	switch strings.ToLower(a.Key) {
	case "authorization", "cookie", "set-cookie":
		if a.Value.String() != "" {
			return slog.String(a.Key, "[REDACTED]")
		}
	}
	return a
}

// stableForTest also removes the timestamp and pins latency, the only
// values that change from run to run.
func stableForTest(groups []string, a slog.Attr) slog.Attr {
	if len(groups) == 0 && a.Key == slog.TimeKey {
		return slog.Attr{}
	}
	if len(groups) == 0 && a.Key == "latency" {
		return slog.Duration(a.Key, 0)
	}
	return redact(groups, a)
}

func main() {
	gin.SetMode(gin.TestMode)
	log := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{ReplaceAttr: stableForTest}))
	n := 0
	generate := func() string { n++; return fmt.Sprintf("gen-%06d", n) } // production: crypto/rand.Text

	// Recovery sits inside accessLog, so a panic still produces an access line.
	recovery := gin.CustomRecoveryWithWriter(nil, func(c *gin.Context, rec any) {
		id, _ := c.Get(requestIDKey{})
		log.Error("panic recovered", "request_id", id, "panic", fmt.Sprint(rec))
		c.AbortWithStatus(http.StatusInternalServerError)
	})
	r := gin.New()
	r.Use(requestID(generate), accessLog(log), recovery)
	r.GET("/notes/:id", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"id": c.Param("id")}) })
	r.POST("/notes", func(c *gin.Context) { panic("storage adapter bug") })

	send := func(method, target, incomingID string) {
		req := httptest.NewRequest(method, target, nil)
		req.Header.Set("User-Agent", "probe/1.0")
		req.Header.Set("Authorization", "Bearer secret-token-value")
		if incomingID != "" {
			req.Header.Set("X-Request-ID", incomingID)
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Println("->", w.Code, "X-Request-ID:", w.Header().Get("X-Request-ID"))
	}
	send("GET", "/notes/42?token=leaked", "edge-7f3a9c21")
	send("GET", "/notes/43", "bad id\nlevel=ERROR")
	send("GET", "/admin.php", "")
	send("POST", "/notes", "")
}

logger := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{
	Level:       slog.LevelInfo,
	ReplaceAttr: redact, // real time and latency; credentials still masked
}))
r := gin.New()
r.Use(requestID(rand.Text), accessLog(logger), recovery)

package main

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"time"

	"github.com/gin-gonic/gin"
)

// Store models a dependency. A hung store never answers on its own.
type Store struct{ hung bool }

func (s Store) Lookup(ctx context.Context, id string) (string, error) {
	if s.hung {
		<-ctx.Done() // only the caller's deadline or cancellation ends the wait
		return "", ctx.Err()
	}
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return "note " + id, nil
}

// deadline gives every request a budget that downstream calls inherit.
func deadline(d time.Duration) gin.HandlerFunc {
	return func(c *gin.Context) {
		ctx, cancel := context.WithTimeout(c.Request.Context(), d)
		defer cancel()
		c.Request = c.Request.WithContext(ctx)
		c.Next()
	}
}

func getNote(s Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		note, err := s.Lookup(c.Request.Context(), c.Param("id"))
		switch {
		case errors.Is(err, context.DeadlineExceeded):
			c.AbortWithStatusJSON(http.StatusGatewayTimeout, gin.H{"error": "dependency timed out"})
		case errors.Is(err, context.Canceled):
			c.AbortWithStatus(499) // client went away: a log label, nobody reads it
		case err != nil:
			c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{"error": "internal"})
		default:
			c.JSON(http.StatusOK, gin.H{"note": note})
		}
	}
}

func inspect(c *gin.Context) {
	_, hasDeadline := c.Deadline()
	c.String(http.StatusOK, "deadline=%t done-nil=%t", hasDeadline, c.Done() == nil)
}

func newRouter(fallback bool) *gin.Engine {
	r := gin.New()
	r.ContextWithFallback = fallback
	r.Use(deadline(20 * time.Millisecond))
	r.GET("/notes/:id", getNote(Store{}))
	r.GET("/reports/:id", getNote(Store{hung: true}))
	r.GET("/inspect", inspect)
	return r
}

func do(r http.Handler, req *http.Request) string {
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	if w.Body.Len() == 0 {
		return fmt.Sprint(w.Code)
	}
	return fmt.Sprint(w.Code, " ", w.Body.String())
}

func main() {
	gin.SetMode(gin.TestMode)
	r := newRouter(false)
	fmt.Println("fast dependency:", do(r, httptest.NewRequest("GET", "/notes/7", nil)))
	fmt.Println("hung dependency:", do(r, httptest.NewRequest("GET", "/reports/7", nil)))

	gone, cancel := context.WithCancel(context.Background())
	cancel() // the client disconnected before the handler ran
	req := httptest.NewRequest("GET", "/reports/8", nil).WithContext(gone)
	fmt.Println("client gone:", do(r, req))

	fmt.Println("c as context, fallback off:", do(r, httptest.NewRequest("GET", "/inspect", nil)))
	fmt.Println("c as context, fallback on:", do(newRouter(true), httptest.NewRequest("GET", "/inspect", nil)))
}

ctx := c.Request.Context()
clientGone := c.Stream(func(w io.Writer) bool {
	select {
	case <-ctx.Done():
		return false // without this case, a blocked step never sees the disconnect
	case ev, ok := <-feed:
		if !ok {
			return false
		}
		c.SSEvent(ev.Name, ev.Data)
		return true // Stream flushes after every step
	}
})

package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"time"

	"github.com/gin-gonic/gin"
)

type Event struct {
	Name string
	Data any
}

// events delivers published events; beats is a ticker channel in production.
func events(feed <-chan Event, beats <-chan time.Time, writeBudget time.Duration) gin.HandlerFunc {
	return func(c *gin.Context) {
		rc := http.NewResponseController(c.Writer)
		extend := func() bool {
			// Replace the server-wide WriteTimeout with a per-write budget.
			err := rc.SetWriteDeadline(time.Now().Add(writeBudget))
			return err == nil || errors.Is(err, http.ErrNotSupported)
		}
		c.Header("Content-Type", "text/event-stream")
		c.Header("Cache-Control", "no-cache")
		c.Status(http.StatusOK)
		if !extend() {
			return
		}
		c.Writer.Flush() // commit headers: the client now knows the stream is open

		ctx := c.Request.Context()
		for {
			select {
			case <-ctx.Done():
				return // client gone, or the server is canceling requests
			case ev, ok := <-feed:
				if !ok || !extend() {
					return
				}
				c.SSEvent(ev.Name, ev.Data)
				c.Writer.Flush()
			case <-beats:
				if !extend() {
					return
				}
				if _, err := io.WriteString(c.Writer, ": ping\n\n"); err != nil {
					return
				}
				c.Writer.Flush()
			}
		}
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	feed := make(chan Event)
	beats := make(chan time.Time)
	r := gin.New()
	r.GET("/events", events(feed, beats, 10*time.Second))

	ctx, disconnect := context.WithCancel(context.Background())
	req := httptest.NewRequest("GET", "/events", nil).WithContext(ctx)
	go func() {
		// Unbuffered sends: exactly one select case is ready at a time.
		feed <- Event{"note", "line one\nline two"}
		beats <- time.Time{}
		feed <- Event{"price", gin.H{"cents": 4200, "symbol": "GO"}}
		disconnect()
	}()
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req) // returns once the handler sees ctx.Done()

	res := w.Result()
	fmt.Println(res.StatusCode, res.Header.Get("Content-Type"), res.Header.Get("Cache-Control"), "flushed:", w.Flushed)
	fmt.Print(w.Body.String())
	err := http.NewResponseController(w).SetWriteDeadline(time.Now())
	fmt.Println("recorder supports write deadlines:", !errors.Is(err, http.ErrNotSupported))
}

package main

import (
	"cmp"
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"slices"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/gin-gonic/gin"
)

type series struct{ method, route, class string }

// Counters is a tiny concurrency-safe stand-in for a metrics client.
type Counters struct {
	mu sync.Mutex
	m  map[series]uint64
}

func (c *Counters) Inc(s series) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.m[s]++
}

func (c *Counters) WriteText(b *strings.Builder) {
	type row struct {
		s series
		n uint64
	}
	c.mu.Lock()
	rows := make([]row, 0, len(c.m))
	for s, n := range c.m {
		rows = append(rows, row{s, n})
	}
	c.mu.Unlock()
	slices.SortFunc(rows, func(a, b row) int { // map order is random; sort for stable output
		return cmp.Or(cmp.Compare(a.s.route, b.s.route), cmp.Compare(a.s.method, b.s.method), cmp.Compare(a.s.class, b.s.class))
	})
	for _, r := range rows {
		fmt.Fprintf(b, "http_requests_total{method=%q,route=%q,class=%q} %d\n", r.s.method, r.s.route, r.s.class, r.n)
	}
}

func normMethod(m string) string {
	switch m {
	case "GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS":
		return m
	}
	return "OTHER" // the method string is client-controlled too
}

func countRequests(cnt *Counters) gin.HandlerFunc {
	return func(c *gin.Context) {
		c.Next()
		route := c.FullPath() // the route template, never the raw path
		if route == "" {
			route = "unmatched"
		}
		cnt.Inc(series{normMethod(c.Request.Method), route, fmt.Sprintf("%dxx", c.Writer.Status()/100)})
	}
}

type Check struct {
	Name string
	Run  func(context.Context) error
}

func readiness(checks []Check, budget time.Duration, draining *atomic.Bool) gin.HandlerFunc {
	return func(c *gin.Context) {
		if draining.Load() {
			c.JSON(http.StatusServiceUnavailable, gin.H{"status": "draining"})
			return
		}
		ctx, cancel := context.WithTimeout(c.Request.Context(), budget)
		defer cancel()
		errs := make([]error, len(checks))
		var wg sync.WaitGroup
		for i, ch := range checks {
			wg.Go(func() { errs[i] = ch.Run(ctx) }) // concurrent: one slow check cannot starve the others
		}
		wg.Wait()
		var failed []string
		for i, err := range errs {
			if err != nil {
				failed = append(failed, checks[i].Name)
			}
		}
		if len(failed) > 0 {
			c.JSON(http.StatusServiceUnavailable, gin.H{"status": "not ready", "failed": failed})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ready"})
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	var dbUp, draining atomic.Bool
	dbUp.Store(true)
	pingDB := func(ctx context.Context) error {
		if dbUp.Load() {
			return nil
		}
		<-ctx.Done() // a hung database answers nothing; the budget decides
		return ctx.Err()
	}
	pingCache := func(ctx context.Context) error { return nil }

	cnt := &Counters{m: map[series]uint64{}}
	r := gin.New()
	r.Use(countRequests(cnt))
	r.GET("/livez", func(c *gin.Context) { c.String(http.StatusOK, "ok") })
	r.GET("/readyz", readiness([]Check{{"db", pingDB}, {"cache", pingCache}}, 25*time.Millisecond, &draining))
	r.GET("/users/:id", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"id": c.Param("id")}) })
	r.GET("/metrics", func(c *gin.Context) {
		var b strings.Builder
		cnt.WriteText(&b)
		c.String(http.StatusOK, b.String())
	})

	call := func(method, path string) string {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(method, path, nil))
		return fmt.Sprint(w.Code, " ", w.Body.String())
	}
	raw := map[string]bool{}
	for _, p := range []string{"/users/1", "/users/2", "/users/3", "/wp-login.php", "/.env"} {
		raw[p] = true
		call("GET", p)
	}
	call("BREW", "/users/1")
	fmt.Println("livez:", call("GET", "/livez"), "| readyz:", call("GET", "/readyz"))
	dbUp.Store(false)
	fmt.Println("livez:", call("GET", "/livez"), "| readyz:", call("GET", "/readyz"))
	draining.Store(true)
	fmt.Println("readyz while draining:", call("GET", "/readyz"))
	fmt.Println(len(raw), "distinct raw paths, but only these series:")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/metrics", nil))
	fmt.Print(w.Body.String())
}

