package main

import (
	"bytes"
	"crypto/sha256"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
)

// ---- the idempotency record store ----

type record struct {
	fingerprint [32]byte
	done        bool
	status      int
	location    string
	body        []byte
	expires     time.Time
}

type outcome int

const (
	started    outcome = iota // key reserved; run the handler
	replay                    // same request finished before; return the stored response
	mismatch                  // same key, different request
	inProgress                // same request is still running
)

type IdempotencyStore struct {
	mu      sync.Mutex
	records map[string]*record
	now     func() time.Time
	ttl     time.Duration
}

// Begin checks and reserves a key in one critical section.
func (s *IdempotencyStore) Begin(key string, fp [32]byte) (outcome, record) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if r, ok := s.records[key]; ok && s.now().Before(r.expires) {
		switch {
		case r.fingerprint != fp:
			return mismatch, record{}
		case !r.done:
			return inProgress, record{}
		default:
			return replay, *r
		}
	}
	s.records[key] = &record{fingerprint: fp, expires: s.now().Add(s.ttl)}
	return started, record{}
}

func (s *IdempotencyStore) Finish(key string, status int, location string, body []byte) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if r, ok := s.records[key]; ok {
		r.done, r.status, r.location, r.body = true, status, location, body
	}
}

func (s *IdempotencyStore) Release(key string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.records, key)
}

// ---- the Gin middleware ----

type captureWriter struct {
	gin.ResponseWriter
	body bytes.Buffer
}

func (w *captureWriter) Write(b []byte) (int, error) {
	w.body.Write(b)
	return w.ResponseWriter.Write(b)
}

func (w *captureWriter) WriteString(s string) (int, error) {
	w.body.WriteString(s)
	return w.ResponseWriter.WriteString(s)
}

func problem(c *gin.Context, status int, title string) {
	c.Header("Content-Type", "application/problem+json")
	c.AbortWithStatusJSON(status, gin.H{"title": title, "status": status})
}

func Idempotent(store *IdempotencyStore) gin.HandlerFunc {
	return func(c *gin.Context) {
		key := c.GetHeader("Idempotency-Key")
		if key == "" || len(key) > 64 {
			problem(c, http.StatusBadRequest, "Idempotency-Key header is required")
			return
		}
		body, err := io.ReadAll(c.Request.Body) // already bounded by MaxBytesReader upstream
		if err != nil {
			problem(c, http.StatusBadRequest, "Unreadable body")
			return
		}
		c.Request.Body = io.NopCloser(bytes.NewReader(body))

		scope := c.GetString("principal") + "\x00" + key
		fp := sha256.Sum256(append([]byte(c.Request.Method+" "+c.FullPath()+"\n"), body...))

		switch result, rec := store.Begin(scope, fp); result {
		case replay:
			c.Header("Location", rec.location)
			c.Header("Idempotent-Replayed", "true")
			c.Data(rec.status, "application/json; charset=utf-8", rec.body)
			c.Abort()
			return
		case mismatch:
			problem(c, http.StatusUnprocessableEntity, "Idempotency-Key was used with a different request")
			return
		case inProgress:
			c.Header("Retry-After", "1")
			problem(c, http.StatusConflict, "A request with this Idempotency-Key is in progress")
			return
		}

		finished := false
		defer func() {
			if !finished {
				store.Release(scope) // 5xx or panic: let the client retry
			}
		}()
		cw := &captureWriter{ResponseWriter: c.Writer}
		c.Writer = cw
		c.Next()
		if status := cw.Status(); status < http.StatusInternalServerError {
			store.Finish(scope, status, cw.Header().Get("Location"), bytes.Clone(cw.body.Bytes()))
			finished = true
		}
	}
}

// ---- the resource ----

type Note struct {
	ID    string `json:"id"`
	Title string `json:"title"`
}

type Notes struct {
	mu       sync.Mutex
	items    []Note
	onCreate func(title string) // demo hook to hold a request open
}

func (n *Notes) Create(title string) Note {
	if n.onCreate != nil {
		n.onCreate(title)
	}
	n.mu.Lock()
	defer n.mu.Unlock()
	note := Note{ID: fmt.Sprintf("n%d", len(n.items)+1), Title: title}
	n.items = append(n.items, note)
	return note
}

func newRouter(store *IdempotencyStore, notes *Notes) *gin.Engine {
	r := gin.New()
	r.Use(func(c *gin.Context) { c.Set("principal", "u1") }) // stand-in for real authentication
	r.POST("/notes", Idempotent(store), func(c *gin.Context) {
		var in struct {
			Title string `json:"title" binding:"required"`
		}
		if err := c.ShouldBindJSON(&in); err != nil {
			problem(c, http.StatusBadRequest, "Malformed note")
			return
		}
		note := notes.Create(in.Title)
		c.Header("Location", "/notes/"+note.ID)
		c.JSON(http.StatusCreated, note)
	})
	return r
}

func post(r http.Handler, key, body string) string {
	req := httptest.NewRequest(http.MethodPost, "/notes", strings.NewReader(body))
	if key != "" {
		req.Header.Set("Idempotency-Key", key)
	}
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	line := fmt.Sprint(w.Code)
	for _, h := range []string{"Location", "Idempotent-Replayed", "Retry-After"} {
		if v := w.Header().Get(h); v != "" {
			line += " " + h + "=" + v
		}
	}
	if w.Code >= 400 {
		line += " " + w.Body.String()
	}
	return line
}

func main() {
	gin.SetMode(gin.TestMode)
	clock := time.Date(2026, 5, 1, 12, 0, 0, 0, time.UTC)
	store := &IdempotencyStore{records: map[string]*record{}, ttl: 24 * time.Hour,
		now: func() time.Time { return clock }}

	entered, release := make(chan struct{}), make(chan struct{})
	notes := &Notes{onCreate: func(title string) {
		if title == "Slow report" {
			entered <- struct{}{}
			<-release
		}
	}}
	r := newRouter(store, notes)

	fmt.Println("first k1:  ", post(r, "k1", `{"title":"Groceries"}`))
	fmt.Println("retry k1:  ", post(r, "k1", `{"title":"Groceries"}`))
	fmt.Println("reuse k1:  ", post(r, "k1", `{"title":"Errands"}`))
	fmt.Println("no key:    ", post(r, "", `{"title":"Errands"}`))

	first := make(chan string)
	go func() { first <- post(r, "k2", `{"title":"Slow report"}`) }()
	<-entered // the first k2 request now holds the reservation
	fmt.Println("second k2: ", post(r, "k2", `{"title":"Slow report"}`))
	close(release)
	fmt.Println("first k2:  ", <-first)

	clock = clock.Add(25 * time.Hour) // past the 24h retention window
	fmt.Println("late k1:   ", post(r, "k1", `{"title":"Groceries"}`))
	fmt.Println("notes created:", len(notes.items))
}

package main

import (
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"

	"github.com/gin-gonic/gin"
)

type Note struct {
	ID      string `json:"id"`
	Title   string `json:"title"`
	Body    string `json:"body"`
	Version int    `json:"version"`
}

var (
	ErrNotFound        = errors.New("notes: not found")
	ErrVersionMismatch = errors.New("notes: version mismatch")
)

type MemoryStore struct {
	mu    sync.Mutex
	notes map[string]Note
}

// Replace is a compare-and-swap: it writes only if the stored version still
// equals expected (-1 means "skip the check", used by the naive route).
func (m *MemoryStore) Replace(id string, expected int, title, body string) (Note, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	n, ok := m.notes[id]
	if !ok {
		return Note{}, ErrNotFound
	}
	if expected >= 0 && n.Version != expected {
		return Note{}, ErrVersionMismatch
	}
	n.Title, n.Body, n.Version = title, body, n.Version+1
	m.notes[id] = n
	return n, nil
}

func (m *MemoryStore) Get(id string) (Note, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	n, ok := m.notes[id]
	if !ok {
		return Note{}, ErrNotFound
	}
	return n, nil
}

func etag(version int) string { return `"` + strconv.Itoa(version) + `"` }

// matchVersion reads If-Match with strong comparison. Weak tags (W/"...") never match.
func matchVersion(header string, current int) bool {
	for _, tag := range strings.Split(header, ",") {
		tag = strings.TrimSpace(tag)
		if tag == "*" || tag == etag(current) {
			return true
		}
	}
	return false
}

type noteBody struct {
	Title string `json:"title" binding:"required"`
	Body  string `json:"body"`
}

func newRouter(st *MemoryStore) *gin.Engine {
	r := gin.New()
	r.GET("/notes/:id", func(c *gin.Context) {
		n, err := st.Get(c.Param("id"))
		if err != nil {
			c.Status(http.StatusNotFound)
			return
		}
		c.Header("ETag", etag(n.Version))
		c.JSON(http.StatusOK, n)
	})
	// The naive route: last write wins.
	r.PUT("/naive/notes/:id", func(c *gin.Context) {
		var in noteBody
		if c.ShouldBindJSON(&in) != nil {
			c.Status(http.StatusBadRequest)
			return
		}
		n, _ := st.Replace(c.Param("id"), -1, in.Title, in.Body)
		c.JSON(http.StatusOK, n)
	})
	// The guarded route: the client must prove which version it edited.
	r.PUT("/notes/:id", func(c *gin.Context) {
		ifMatch := c.GetHeader("If-Match")
		if ifMatch == "" {
			c.JSON(http.StatusPreconditionRequired, gin.H{"title": "If-Match header is required"})
			return
		}
		var in noteBody
		if c.ShouldBindJSON(&in) != nil {
			c.Status(http.StatusBadRequest)
			return
		}
		cur, err := st.Get(c.Param("id"))
		if err != nil {
			c.Status(http.StatusNotFound)
			return
		}
		if !matchVersion(ifMatch, cur.Version) {
			c.JSON(http.StatusPreconditionFailed, gin.H{"title": "Note was changed by someone else"})
			return
		}
		// The store re-checks atomically: another writer may have won since Get.
		n, err := st.Replace(cur.ID, cur.Version, in.Title, in.Body)
		if errors.Is(err, ErrVersionMismatch) {
			c.JSON(http.StatusPreconditionFailed, gin.H{"title": "Note was changed by someone else"})
			return
		}
		c.Header("ETag", etag(n.Version))
		c.JSON(http.StatusOK, n)
	})
	return r
}

func do(r http.Handler, method, path, ifMatch, body string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	if ifMatch != "" {
		req.Header.Set("If-Match", ifMatch)
	}
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	return w
}

func seed() *MemoryStore {
	return &MemoryStore{notes: map[string]Note{
		"n1": {ID: "n1", Title: "Trip", Body: "flights", Version: 1},
	}}
}

func main() {
	gin.SetMode(gin.TestMode)

	// Lost update: both clients read version 1, both write, the second silently wins.
	st := seed()
	r := newRouter(st)
	do(r, "PUT", "/naive/notes/n1", "", `{"title":"Trip","body":"flights, hotel"}`)  // client A adds the hotel
	do(r, "PUT", "/naive/notes/n1", "", `{"title":"Trip to Rome","body":"flights"}`) // client B renames from a stale copy
	n, _ := st.Get("n1")
	fmt.Printf("naive final: title=%q body=%q\n", n.Title, n.Body)

	// The same race with ETag and If-Match.
	st = seed()
	r = newRouter(st)
	tag := do(r, "GET", "/notes/n1", "", "").Header().Get("ETag")
	fmt.Println("A and B read ETag", tag)
	w := do(r, "PUT", "/notes/n1", tag, `{"title":"Trip","body":"flights, hotel"}`)
	fmt.Println("A PUT If-Match", tag, "->", w.Code, "ETag", w.Header().Get("ETag"))
	w = do(r, "PUT", "/notes/n1", tag, `{"title":"Trip to Rome","body":"flights"}`)
	fmt.Println("B PUT If-Match", tag, "->", w.Code, w.Body.String())
	w = do(r, "PUT", "/notes/n1", "", `{"title":"Trip to Rome","body":"flights"}`)
	fmt.Println("B PUT without If-Match ->", w.Code, w.Body.String())
	w = do(r, "PUT", "/notes/n1", `W/"2"`, `{"title":"Trip to Rome","body":"flights, hotel"}`)
	fmt.Println(`B PUT If-Match W/"2" ->`, w.Code)

	g := do(r, "GET", "/notes/n1", "", "")
	fresh := g.Header().Get("ETag")
	w = do(r, "PUT", "/notes/n1", fresh, `{"title":"Trip to Rome","body":"flights, hotel"}`)
	fmt.Println("B re-reads", fresh, "and retries ->", w.Code, "ETag", w.Header().Get("ETag"))
	fmt.Println("final:", w.Body.String())
}

const replaceNote = `
UPDATE notes
   SET title = $1, body = $2, version = version + 1
 WHERE id = $3 AND owner_id = $4 AND version = $5
RETURNING version`

func (s *Postgres) Replace(ctx context.Context, owner, id string, expected int, title, body string) (int, error) {
	var v int
	err := s.db.QueryRowContext(ctx, replaceNote, title, body, id, owner, expected).Scan(&v)
	if !errors.Is(err, sql.ErrNoRows) {
		return v, err // success, or a real database error
	}
	// No row matched: the note is gone, or another writer moved the version on.
	var exists bool
	if err := s.db.QueryRowContext(ctx,
		`SELECT EXISTS (SELECT 1 FROM notes WHERE id = $1 AND owner_id = $2)`, id, owner).Scan(&exists); err != nil {
		return 0, err
	}
	if !exists {
		return 0, ErrNotFound
	}
	return 0, ErrVersionMismatch
}

