func TestMain(m *testing.M) {
	gin.SetMode(gin.TestMode) // process-wide: set once, before any test builds an engine
	os.Exit(m.Run())
}

func TestNotesAPI(t *testing.T) {
	tests := []struct {
		name       string
		method     string
		path       string
		body       string
		storeErr   error
		wantStatus int
		wantHeader map[string]string
		wantBody   string
	}{
		{
			name: "create returns 201 and Location", method: "POST", path: "/notes", body: `{"title":" Review PR "}`,
			wantStatus: 201,
			wantHeader: map[string]string{"Location": "/notes/n1", "Content-Type": "application/json; charset=utf-8"},
			wantBody:   `{"title": "Review PR", "id": "n1", "createdAt": "2026-01-02T03:04:05Z"}`,
		},
		{
			name: "missing note is a problem document", method: "GET", path: "/notes/n9",
			wantStatus: 404,
			wantHeader: map[string]string{"Content-Type": "application/problem+json"},
			wantBody:   `{"type": "https://example.com/problems/not-found", "title": "Note not found", "status": 404, "instance": "/notes/n9"}`,
		},
		{
			name: "blank title is rejected with a reason", method: "POST", path: "/notes", body: `{"title":"   "}`,
			wantStatus: 422,
			wantHeader: map[string]string{"Content-Type": "application/problem+json"},
			wantBody:   `{"type": "https://example.com/problems/validation", "title": "Invalid note", "status": 422, "detail": "title must not be blank", "instance": "/notes"}`,
		},
		{
			name: "store failure hides the cause", method: "GET", path: "/notes/n1",
			storeErr:   errors.New("dial tcp 192.0.2.10:5432: connection refused"),
			wantStatus: 500,
			wantHeader: map[string]string{"Content-Type": "application/problem+json"},
			wantBody:   `{"type": "about:blank", "title": "Internal Server Error", "status": 500, "instance": "/notes/n1"}`,
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			r := newTestRouter(t, tc.storeErr)
			req := httptest.NewRequest(tc.method, tc.path, strings.NewReader(tc.body))
			if tc.body != "" {
				req.Header.Set("Content-Type", "application/json")
			}
			w := httptest.NewRecorder()
			r.ServeHTTP(w, req)

			if w.Code != tc.wantStatus {
				t.Errorf("status = %d, want %d", w.Code, tc.wantStatus)
			}
			for k, want := range tc.wantHeader {
				if got := w.Header().Get(k); got != want {
					t.Errorf("header %s = %q, want %q", k, got, want)
				}
			}
			assertJSONEqual(t, tc.wantBody, w.Body.Bytes())
		})
	}
}

func newTestRouter(t *testing.T, storeErr error) http.Handler {
	t.Helper()
	fake := newFakeStore()
	fake.err = storeErr
	seq := 0
	ids := func() string { seq++; return fmt.Sprintf("n%d", seq) }
	clock := func() time.Time { return time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC) }
	svc, err := notes.NewService(fake, clock, ids)
	if err != nil {
		t.Fatal(err)
	}
	r, err := httpapi.NewRouter(httpapi.NewHandler(svc, slog.New(slog.DiscardHandler)), httpapi.Options{})
	if err != nil {
		t.Fatal(err)
	}
	return r
}

func assertJSONEqual(t *testing.T, want string, got []byte) {
	t.Helper()
	var w, g any
	if err := json.Unmarshal([]byte(want), &w); err != nil {
		t.Fatalf("test table has invalid JSON: %v", err)
	}
	if err := json.Unmarshal(got, &g); err != nil {
		t.Fatalf("response is not JSON: %v\n%s", err, got)
	}
	if !reflect.DeepEqual(w, g) {
		t.Errorf("body mismatch\n got: %s\nwant: %s", got, want)
	}
}

