// ---- condensed code under test: notes + httpapi from earlier lessons ----

type Note struct {
	ID        string    `json:"id"`
	Title     string    `json:"title"`
	CreatedAt time.Time `json:"createdAt"`
}

var (
	ErrNotFound = errors.New("notes: not found")
	ErrInvalid  = errors.New("notes: title must not be blank")
)

type Store interface {
	Insert(ctx context.Context, n Note) error
	Get(ctx context.Context, id string) (Note, error)
}

type Handler struct {
	store  Store
	now    func() time.Time
	nextID func() string
}

type Problem struct {
	Type     string `json:"type"`
	Title    string `json:"title"`
	Status   int    `json:"status"`
	Detail   string `json:"detail,omitempty"`
	Instance string `json:"instance,omitempty"`
}

func problems(exposeCause bool) gin.HandlerFunc {
	return func(c *gin.Context) {
		c.Next()
		if len(c.Errors) == 0 || c.Writer.Written() {
			return
		}
		err := c.Errors.Last().Err
		p := Problem{Type: "about:blank", Title: "Internal Server Error", Status: 500}
		switch {
		case errors.Is(err, ErrNotFound):
			p = Problem{Type: "https://example.com/problems/not-found", Title: "Note not found", Status: 404}
		case errors.Is(err, ErrInvalid):
			p = Problem{Type: "https://example.com/problems/validation", Title: "Invalid note", Status: 422,
				Detail: "title must not be blank"}
		case exposeCause:
			p.Detail = err.Error() // the "helpful" regression
		}
		p.Instance = c.Request.URL.Path
		c.Header("Content-Type", "application/problem+json")
		c.JSON(p.Status, p)
	}
}

func NewRouter(h *Handler, exposeCause bool) *gin.Engine {
	r := gin.New()
	r.Use(problems(exposeCause))
	r.POST("/notes", func(c *gin.Context) {
		var in struct {
			Title string `json:"title"`
		}
		if err := c.ShouldBindJSON(&in); err != nil || strings.TrimSpace(in.Title) == "" {
			_ = c.Error(ErrInvalid)
			return
		}
		n := Note{ID: h.nextID(), Title: strings.TrimSpace(in.Title), CreatedAt: h.now()}
		if err := h.store.Insert(c.Request.Context(), n); err != nil {
			_ = c.Error(fmt.Errorf("insert %s: %w", n.ID, err))
			return
		}
		c.Header("Location", "/notes/"+n.ID)
		c.JSON(http.StatusCreated, n)
	})
	r.GET("/notes/:id", func(c *gin.Context) {
		n, err := h.store.Get(c.Request.Context(), c.Param("id"))
		if err != nil {
			_ = c.Error(fmt.Errorf("get %s: %w", c.Param("id"), err))
			return
		}
		c.JSON(http.StatusOK, n)
	})
	return r
}

