		wantStatus: 500,
		wantHeader: map[string]string{"Content-Type": "application/problem+json"},
		wantBody:   `{"type": "about:blank", "title": "Internal Server Error", "status": 500, "instance": "/notes/n1"}`,
	},
}

func newRouterFor(tc apiCase, exposeCause bool) http.Handler {
	seq := 0
	h := &Handler{
		store:  &fakeStore{notes: map[string]Note{}, err: tc.storeErr},
		now:    func() time.Time { return time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC) },
		nextID: func() string { seq++; return fmt.Sprintf("n%d", seq) },
	}
	return NewRouter(h, exposeCause)
}

func check(r http.Handler, tc apiCase, statusOnly bool) []string {
	req := httptest.NewRequest(tc.method, tc.path, strings.NewReader(tc.body))
	if tc.body != "" {
		req.Header.Set("Content-Type", "application/json")
	}
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)

	var fails []string
	if w.Code != tc.wantStatus {
		fails = append(fails, fmt.Sprintf("status %d, want %d", w.Code, tc.wantStatus))
	}
	if statusOnly {
		return fails
	}
	for _, k := range slices.Sorted(maps.Keys(tc.wantHeader)) {
		if got := w.Header().Get(k); got != tc.wantHeader[k] {
			fails = append(fails, fmt.Sprintf("%s %q, want %q", k, got, tc.wantHeader[k]))
		}
	}
	if !jsonEqual(tc.wantBody, w.Body.Bytes()) {
		fails = append(fails, "body "+w.Body.String())
	}
	return fails
}

func run(label string, exposeCause, statusOnly bool) {
	fmt.Println(label)
	for _, tc := range cases {
		if fails := check(newRouterFor(tc, exposeCause), tc, statusOnly); len(fails) > 0 {
			fmt.Printf("  FAIL %s: %s\n", tc.name, strings.Join(fails, "; "))
		} else {
			fmt.Printf("  PASS %s\n", tc.name)
		}
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	run("current build, full checks:", false, false)
	run("regressed build, status-only checks:", true, true)
	run("regressed build, full checks:", true, false)
}

package main

import (
	"errors"
	"fmt"
	"net"
	"net/netip"
	"net/url"
	"slices"
	"strconv"
	"strings"
	"time"
)

type Config struct {
	Addr              string
	Mode              string // gin mode: release or debug
	Store             string // memory or postgres
	DatabaseURL       *url.URL
	ReadHeaderTimeout time.Duration
	ShutdownTimeout   time.Duration
	MaxBodyBytes      int64
	IdempotencyTTL    time.Duration
	TrustedProxies    []netip.Prefix
}

var known = []string{
	"NOTES_ADDR", "NOTES_MODE", "NOTES_STORE", "NOTES_DATABASE_URL", "NOTES_READ_HEADER_TIMEOUT",
	"NOTES_SHUTDOWN_TIMEOUT", "NOTES_MAX_BODY_BYTES", "NOTES_IDEMPOTENCY_TTL", "NOTES_TRUSTED_PROXIES",
}

// Load reads KEY=value pairs (os.Environ() in production) and reports every problem at once.
func Load(environ []string) (Config, error) {
	env := map[string]string{}
	var errs []error
	for _, kv := range environ {
		k, v, _ := strings.Cut(kv, "=")
		if strings.HasPrefix(k, "NOTES_") && !slices.Contains(known, k) {
			errs = append(errs, fmt.Errorf("%s: unknown setting", k))
		}
		env[k] = v
	}
	str := func(key, def string, allowed ...string) string {
		v, ok := env[key]
		if !ok {
			return def
		}
		if len(allowed) > 0 && !slices.Contains(allowed, v) {
			errs = append(errs, fmt.Errorf("%s: %q is not one of %s", key, v, strings.Join(allowed, ", ")))
		}
		return v
	}
	dur := func(key string, def, lo, hi time.Duration) time.Duration {
		v, ok := env[key]
		if !ok {
			return def
		}
		d, err := time.ParseDuration(v)
		switch {
		case err != nil:
			errs = append(errs, fmt.Errorf("%s: %q is not a duration such as 5s", key, v))
		case d < lo || d > hi:
			errs = append(errs, fmt.Errorf("%s: %s is outside %s..%s", key, d, lo, hi))
		}
		return d
	}

	c := Config{
		Addr:              str("NOTES_ADDR", ":8080"),
		Mode:              str("NOTES_MODE", "release", "release", "debug"),
		Store:             str("NOTES_STORE", "memory", "memory", "postgres"),
		ReadHeaderTimeout: dur("NOTES_READ_HEADER_TIMEOUT", 5*time.Second, time.Second, 30*time.Second),
		ShutdownTimeout:   dur("NOTES_SHUTDOWN_TIMEOUT", 20*time.Second, time.Second, 25*time.Second),
		IdempotencyTTL:    dur("NOTES_IDEMPOTENCY_TTL", 24*time.Hour, time.Hour, 7*24*time.Hour),
		MaxBodyBytes:      1 << 20,
	}
	if v, ok := env["NOTES_MAX_BODY_BYTES"]; ok {
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil || n < 1024 || n > 10<<20 {
			errs = append(errs, fmt.Errorf("NOTES_MAX_BODY_BYTES: %q must be an integer in 1024..%d", v, 10<<20))
		}
		c.MaxBodyBytes = n
	}
	if _, _, err := net.SplitHostPort(c.Addr); err != nil {
		errs = append(errs, fmt.Errorf("NOTES_ADDR: %q is not host:port", c.Addr))
	}
	if v := env["NOTES_TRUSTED_PROXIES"]; v != "" {
		for _, s := range strings.Split(v, ",") {
			p, err := parseProxy(strings.TrimSpace(s))
			switch {
			case err != nil:
				errs = append(errs, fmt.Errorf("NOTES_TRUSTED_PROXIES: %q is not an IP or CIDR prefix", s))
			case p.Bits() == 0:
				errs = append(errs, fmt.Errorf("NOTES_TRUSTED_PROXIES: %s would trust every client", p))
			default:
				c.TrustedProxies = append(c.TrustedProxies, p)
			}
		}
	}
	if raw, ok := env["NOTES_DATABASE_URL"]; ok {
		u, err := url.Parse(raw)
		if err != nil || u.Scheme != "postgres" || u.Host == "" {
			errs = append(errs, errors.New("NOTES_DATABASE_URL: must be a postgres:// URL with a host"))
		}
		c.DatabaseURL = u
	}
	if c.Store == "postgres" && c.DatabaseURL == nil {
		errs = append(errs, errors.New("NOTES_DATABASE_URL: required when NOTES_STORE=postgres"))
	}
	return c, errors.Join(errs...)
}

func parseProxy(s string) (netip.Prefix, error) {
	if p, err := netip.ParsePrefix(s); err == nil {
		return p.Masked(), nil
	}
	a, err := netip.ParseAddr(s)
	if err != nil {
		return netip.Prefix{}, err
	}
	return netip.PrefixFrom(a, a.BitLen()), nil
}

// String is what startup logs print: every effective value, secrets redacted.
func (c Config) String() string {
	db := "none"
	if c.DatabaseURL != nil {
		db = c.DatabaseURL.Redacted()
	}
	return fmt.Sprintf("addr=%s mode=%s store=%s db=%s read_header=%s shutdown=%s max_body=%d idem_ttl=%s proxies=%v",
		c.Addr, c.Mode, c.Store, db, c.ReadHeaderTimeout, c.ShutdownTimeout, c.MaxBodyBytes, c.IdempotencyTTL, c.TrustedProxies)
}

func main() {
	good := []string{
		"HOME=/home/app",
		"NOTES_STORE=postgres",
		"NOTES_DATABASE_URL=postgres://notes_rw:s3cret@db.internal:5432/notes",
		"NOTES_TRUSTED_PROXIES=10.0.0.0/8, 192.0.2.10",
	}
	if c, err := Load(good); err == nil {
		fmt.Println("config ok:", c)
	}

	if c, err := Load(nil); err == nil {
		fmt.Println("defaults:", c)
	}

	bad := []string{
		"NOTES_STORE=postgres",
		"NOTES_READ_HEADER_TIMEOUT=5",
		"NOTES_SHUTDOWN_TIMEOUT=45s",
		"NOTES_SHUTDOWN_TIMOUT=10s",
		"NOTES_ADDR=8080",
		"NOTES_TRUSTED_PROXIES=0.0.0.0/0",
	}
	if _, err := Load(bad); err != nil {
		fmt.Println("refusing to start:")
		for _, line := range strings.Split(err.Error(), "\n") {
			fmt.Println("  " + line)
		}
	}
}

// cmd/api/main.go, package main
import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/gin-gonic/gin"

	"example.com/notes-api/internal/config"
	"example.com/notes-api/internal/httpapi"
	"example.com/notes-api/internal/notes"
	"example.com/notes-api/internal/store"
)

func main() {
	if err := run(os.Environ()); err != nil {
		fmt.Fprintln(os.Stderr, "notes-api:", err)
		os.Exit(1)
	}
}

func run(environ []string) error {
	cfg, err := config.Load(environ)
	if err != nil {
		return fmt.Errorf("invalid configuration:\n%w", err)
	}
	log := slog.New(slog.NewJSONHandler(os.Stderr, nil))
	log.Info("config", "effective", cfg.String())

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	// Wire from the inside out: store -> service -> handlers -> engine -> server.
	st := store.NewMemory() // a Postgres adapter would be opened here and closed after Shutdown
	svc, err := notes.NewService(st, time.Now, notes.RandomIDs)
	if err != nil {
		return err
	}
	gin.SetMode(cfg.Mode) // before gin.New; GIN_MODE is ignored from here on
	engine, err := httpapi.NewRouter(httpapi.NewHandler(svc, log), httpapi.Options{
		MaxBodyBytes:   cfg.MaxBodyBytes,
		IdempotencyTTL: cfg.IdempotencyTTL,
		TrustedProxies: cfg.TrustedProxyStrings(),
	})
	if err != nil {
		return err
	}
	srv := &http.Server{
		Handler:           engine,
		ReadHeaderTimeout: cfg.ReadHeaderTimeout,
		IdleTimeout:       time.Minute,
		// No BaseContext(ctx): a signal must not cancel requests that are draining.
	}

	ln, err := net.Listen("tcp", cfg.Addr) // a busy port fails here, before "listening" is logged
	if err != nil {
		return err
	}
	serveErr := make(chan error, 1)
	go func() { serveErr <- srv.Serve(ln) }()
	log.Info("listening", "addr", ln.Addr().String())

	select {
	case err := <-serveErr:
		return fmt.Errorf("serve: %w", err)
	case <-ctx.Done():
		log.Info("shutting down", "cause", context.Cause(ctx).Error())
	}
	stop() // restore default handling: a second Ctrl-C ends the process at once

	shutdownCtx, cancel := context.WithTimeout(context.Background(), cfg.ShutdownTimeout)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		_ = srv.Close() // budget spent: drop what is left rather than hang
		return fmt.Errorf("shutdown: %w", err)
	}
	if err := <-serveErr; !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	log.Info("stopped")
	return nil
}

package main

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"time"

	"github.com/gin-gonic/gin"
)

// traceKey is a typed context key, the way tracing libraries store spans.
type traceKey struct{}

// Store models a database driver: it refuses work for a finished context
// and reads request-scoped values from the context it is given.
type Store struct{ queries int }

func (s *Store) Query(ctx context.Context) string {
	if err := ctx.Err(); err != nil {
		return "skipped: " + err.Error()
	}
	s.queries++
	trace, _ := ctx.Value(traceKey{}).(string)
	return fmt.Sprintf("ran query %d, trace=%q", s.queries, trace)
}

// tracing stores a trace ID in the request context and a tenant in c.Keys.
func tracing(c *gin.Context) {
	ctx := context.WithValue(c.Request.Context(), traceKey{}, "t-42")
	c.Request = c.Request.WithContext(ctx)
	c.Set("tenant", "acme")
	c.Next()
}

func newRouter(fallback bool, store *Store, later *[]func()) *gin.Engine {
	r := gin.New()
	r.ContextWithFallback = fallback
	r.Use(tracing)
	r.GET("/inspect", func(c *gin.Context) {
		_, hasDeadline := c.Deadline()
		c.String(http.StatusOK, "Deadline ok=%t, Done nil=%t, Err=%v, trace=%v, tenant=%v",
			hasDeadline, c.Done() == nil, c.Err(), c.Value(traceKey{}), c.Value("tenant"))
	})
	r.GET("/via-gin", func(c *gin.Context) {
		c.String(http.StatusOK, "%s", store.Query(c)) // compiles: *gin.Context is a context.Context
	})
	r.GET("/via-request", func(c *gin.Context) {
		c.String(http.StatusOK, "%s", store.Query(c.Request.Context()))
	})
	r.GET("/after", func(c *gin.Context) {
		req, cp := c.Request, c.Copy()
		detached := context.WithoutCancel(c.Request.Context())
		c.Set("tenant", "changed after Copy")
		*later = append(*later,
			func() { fmt.Println("  copy shares the request:", cp.Request == req) },
			func() { fmt.Println("  copy keeps its own Keys: tenant =", cp.Value("tenant")) },
			func() { fmt.Println("  store(cp.Request.Context()):", store.Query(cp.Request.Context())) },
			func() { fmt.Println("  store(WithoutCancel):", store.Query(detached)) },
		)
		c.Status(http.StatusAccepted)
	})
	return r
}

// call sends one request whose context carries a deadline and, if gone is
// true, has already been canceled, as when a client disconnects.
func call(r http.Handler, path string, gone bool) string {
	ctx, cancel := context.WithDeadline(context.Background(), time.Date(2100, 1, 1, 0, 0, 0, 0, time.UTC))
	defer cancel()
	if gone {
		cancel()
	}
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, path, nil).WithContext(ctx))
	return w.Body.String()
}

func main() {
	gin.SetMode(gin.TestMode)
	store := &Store{}
	var later []func()
	off := newRouter(false, store, &later)
	on := newRouter(true, store, &later)

	fmt.Println("c as context.Context, client gone:")
	fmt.Println("  fallback off:", call(off, "/inspect", true))
	fmt.Println("  fallback on: ", call(on, "/inspect", true))

	fmt.Println("store calls when the client is gone:")
	fmt.Println("  store(c), fallback off:", call(off, "/via-gin", true))
	fmt.Println("  store(c.Request.Context()):", call(off, "/via-request", true))
	fmt.Println("  store(c), fallback on:", call(on, "/via-gin", true))
	fmt.Println("store(c.Request.Context()), client still here:", call(off, "/via-request", false))

	fmt.Println("work that runs after the handler returned:")
	ctx, cancel := context.WithCancel(context.Background())
	w := httptest.NewRecorder()
	off.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/after", nil).WithContext(ctx))
	cancel() // net/http cancels the request context once ServeHTTP returns
	for _, f := range later {
		f()
	}
}

func (h *Handlers) publish(c *gin.Context) {
	ev := AuditEvent{Route: c.FullPath(), NoteID: c.Param("id"), Tenant: tenantFrom(c)}
	base := context.WithoutCancel(c.Request.Context()) // keeps trace values, drops cancellation
	h.wg.Add(1)
	go func() {
		defer h.wg.Done()
		ctx, cancel := context.WithTimeout(base, 5*time.Second)
		defer cancel()
		stop := context.AfterFunc(h.shutdown, cancel) // also stop when the process drains
		defer stop()
		if err := h.audit.Write(ctx, ev); err != nil {
			h.log.ErrorContext(ctx, "audit write failed", "err", err)
		}
	}()
	c.Status(http.StatusAccepted)
}

package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"mime"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"

	"github.com/gin-gonic/gin"
	"github.com/gin-gonic/gin/binding"
	"github.com/go-playground/validator/v10"
)

type Settings struct {
	Color  string `json:"color,omitempty" binding:"omitempty,oneof=red blue green"`
	Pinned bool   `json:"pinned"`
}

type Note struct {
	ID       int      `json:"id"`
	Title    string   `json:"title" binding:"required,max=40"`
	Due      string   `json:"due,omitempty" binding:"omitempty,datetime=2006-01-02"`
	Tags     []string `json:"tags,omitempty" binding:"max=3,dive,min=1,max=12"`
	Settings Settings `json:"settings"`
}

// patchable lists the top-level members a client may change; id is read-only.
var patchable = map[string]bool{"title": true, "due": true, "tags": true, "settings": true}

// mergePatch is the algorithm of RFC 7396, section 2: objects merge member by
// member, null removes a member, and anything else replaces the target.
func mergePatch(target, patch any) any {
	p, ok := patch.(map[string]any)
	if !ok {
		return patch
	}
	t, ok := target.(map[string]any)
	if !ok {
		t = map[string]any{}
	}
	for k, v := range p {
		if v == nil {
			delete(t, k)
		} else {
			t[k] = mergePatch(t[k], v)
		}
	}
	return t
}

// decodeOne reads exactly one JSON value and keeps numbers exact.
func decodeOne(r io.Reader, v any) error {
	dec := json.NewDecoder(r)
	dec.UseNumber()
	if err := dec.Decode(v); err != nil {
		return err
	}
	if err := dec.Decode(new(any)); err != io.EOF {
		return errors.New("trailing data after the JSON value")
	}
	return nil
}

func apply(current Note, patch any) (Note, error) {
	doc, _ := json.Marshal(current)
	var target any
	if err := decodeOne(bytes.NewReader(doc), &target); err != nil {
		return Note{}, err
	}
	merged, _ := json.Marshal(mergePatch(target, patch))
	dec := json.NewDecoder(bytes.NewReader(merged))
	dec.DisallowUnknownFields()
	var next Note
	if err := dec.Decode(&next); err != nil {
		return Note{}, err
	}
	return next, binding.Validator.ValidateStruct(&next) // validate the result, not the patch
}

func newRouter() *gin.Engine {
	var mu sync.Mutex
	notes := map[int]Note{7: {ID: 7, Title: "Ship v2", Due: "2026-12-01",
		Tags: []string{"go", "api"}, Settings: Settings{Color: "blue", Pinned: true}}}

	r := gin.New()
	r.PATCH("/notes/7", func(c *gin.Context) {
		mt, _, err := mime.ParseMediaType(c.GetHeader("Content-Type"))
		if err != nil || mt != "application/merge-patch+json" {
			c.Header("Accept-Patch", "application/merge-patch+json")
			c.AbortWithStatusJSON(http.StatusUnsupportedMediaType, gin.H{"error": "use application/merge-patch+json"})
			return
		}
		var patch any
		if err := decodeOne(http.MaxBytesReader(c.Writer, c.Request.Body, 16<<10), &patch); err != nil {
			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "malformed JSON"})
			return
		}
		obj, ok := patch.(map[string]any)
		if !ok {
			c.AbortWithStatusJSON(http.StatusUnprocessableEntity, gin.H{"error": "patch must be a JSON object"})
			return
		}
		for k := range obj {
			if !patchable[k] {
				c.AbortWithStatusJSON(http.StatusUnprocessableEntity, gin.H{"error": "member not patchable: " + k})
				return
			}
		}
		mu.Lock()
		defer mu.Unlock()
		next, err := apply(notes[7], patch)
		var invalid validator.ValidationErrors
		switch {
		case errors.As(err, &invalid):
			fields := make([]string, len(invalid))
			for i, fe := range invalid {
				fields[i] = fe.Namespace() + " " + fe.Tag()
			}
			c.AbortWithStatusJSON(http.StatusUnprocessableEntity, gin.H{"error": "invalid result", "fields": fields})
			return
		case err != nil:
			c.AbortWithStatusJSON(http.StatusUnprocessableEntity, gin.H{"error": err.Error()})
			return
		}
		notes[7] = next
		c.JSON(http.StatusOK, next)
	})
	return r
}

type pointerDTO struct {
	Title *string `json:"title"`
}

func main() {
	gin.SetMode(gin.TestMode)

	fmt.Println("what each decoding target can see:")
	for _, body := range []string{`{}`, `{"title":null}`, `{"title":"x"}`} {
		var dto pointerDTO
		_ = json.Unmarshal([]byte(body), &dto)
		var raw map[string]json.RawMessage
		_ = json.Unmarshal([]byte(body), &raw)
		pointer, member := "nil", "absent"
		if dto.Title != nil {
			pointer = fmt.Sprintf("%q", *dto.Title)
		}
		if m, ok := raw["title"]; ok {
			member = string(m)
		}
		fmt.Printf("  %-16s pointer field: %-5s map member: %s\n", body, pointer, member)
	}

	r := newRouter()
	send := func(contentType, body string) {
		req := httptest.NewRequest(http.MethodPatch, "/notes/7", strings.NewReader(body))
		req.Header.Set("Content-Type", contentType)
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Printf("PATCH %s\n  %d %s\n", body, w.Code, w.Body.String())
		if v := w.Header().Get("Accept-Patch"); v != "" {
			fmt.Println("  Accept-Patch:", v)
		}
	}
	const mp = "application/merge-patch+json"
	send(mp, `{"due":null,"tags":["go"]}`)
	send("Application/Merge-Patch+JSON", `{"title":"Ship v2.1","settings":{"color":null}}`)
	send(mp, `{"title":null}`)
	send(mp, `{"id":8}`)
	send(mp, `{"settings":{"colour":"red"}}`)
	send(mp, `{"tags":["go"]} {"tags":[]}`)
	send("application/json", `{"title":"Ship v3"}`)
}

// Optional records whether a member was present and whether it was null.
type Optional[T any] struct {
	Set   bool // the member appeared in the patch
	Null  bool // it appeared as JSON null
	Value T    // the zero value when Null is true
}

func (o *Optional[T]) UnmarshalJSON(b []byte) error {
	o.Set = true // encoding/json calls this only for members that are present
	if string(b) == "null" {
		o.Null = true
		return nil
	}
	return json.Unmarshal(b, &o.Value)
}

type notePatch struct {
	Title Optional[string] `json:"title"`
	Due   Optional[string] `json:"due"`
}

// applyTo edits a copy of the stored note; validate the result afterwards.
func (p notePatch) applyTo(n Note) Note {
	if p.Title.Set {
		n.Title = p.Title.Value // null gives "", which the required rule rejects
	}
	if p.Due.Set {
		n.Due = p.Due.Value // null clears the due date
	}
	return n
}

