// sortable maps a public sort key to a column. Only these strings reach SQL.
var sortable = map[string]struct {
	column   string
	nullable bool
}{
	"created":  {column: "created_at"},
	"priority": {column: "priority"},
	"due":      {column: "due_at", nullable: true},
}

var statuses = []string{"closed", "open", "triaged"}

var allowedParams = []string{"assignee", "created_after", "limit", "q", "sort", "status"}

const maxAssignees = 20

// likeEscaper makes %, _ and the escape character literal inside a pattern.
var likeEscaper = strings.NewReplacer("!", "!!", "%", "!%", "_", "!_")

// builder collects predicates and arguments; bind is the only way to add a value.
type builder struct {
	where []string
	args  []any
}

func (b *builder) bind(v any) string {
	b.args = append(b.args, v)
	return "$" + strconv.Itoa(len(b.args))
}

func (b *builder) in(column string, values []any) {
	ph := make([]string, len(values))
	for i, v := range values {
		ph[i] = b.bind(v)
	}
	b.where = append(b.where, column+" IN ("+strings.Join(ph, ", ")+")")
}

// list accepts both ?status=a&status=b and ?status=a,b.
func list(values []string) []string {
	var out []string
	for _, v := range values {
		out = append(out, strings.Split(v, ",")...)
	}
	return out
}

// canonical sorts and dedupes, so equivalent requests produce the same SQL
// text and the same arguments.
func canonical[T cmp.Ordered](values []T) []any {
	slices.Sort(values)
	values = slices.Compact(values)
	out := make([]any, len(values))
	for i, v := range values {
		out[i] = v
	}
	return out
}

func buildQuery(projectID int64, q url.Values) (string, []any, error) {
	for _, name := range slices.Sorted(maps.Keys(q)) { // sorted: the same error every time
		if !slices.Contains(allowedParams, name) {
			return "", nil, fmt.Errorf("unknown parameter %q", name)
		}
	}
	b := &builder{}
	b.where = append(b.where, "project_id = "+b.bind(projectID)) // scope first, from the path

	if values := list(q["status"]); len(values) > 0 {
		for _, s := range values {
			if !slices.Contains(statuses, s) {
				return "", nil, fmt.Errorf("status %q is not one of %v", s, statuses)
			}
		}
		b.in("status", canonical(values))
	}
	if values := list(q["assignee"]); len(values) > 0 {
		if len(values) > maxAssignees { // bound the raw input before any work
			return "", nil, fmt.Errorf("at most %d assignees", maxAssignees)
		}
		ids := make([]int64, len(values))
		for i, s := range values {
			id, err := strconv.ParseInt(s, 10, 64)
			if err != nil || id <= 0 {
				return "", nil, fmt.Errorf("assignee %q is not a positive ID", s)
			}
			ids[i] = id
		}
		b.in("assignee_id", canonical(ids))
	}
	if text := strings.TrimSpace(q.Get("q")); text != "" {
		if utf8.RuneCountInString(text) > 100 {
			return "", nil, errors.New("q is longer than 100 characters")
		}
		pattern := "%" + likeEscaper.Replace(text) + "%"
		b.where = append(b.where, "title ILIKE "+b.bind(pattern)+" ESCAPE '!'")
	}
	if raw := q.Get("created_after"); raw != "" {
		t, err := time.Parse(time.RFC3339, raw)
		if err != nil {
			return "", nil, errors.New("created_after must be RFC 3339")
		}
		b.where = append(b.where, "created_at > "+b.bind(t.UTC()))
	}

	var order []string
	seen := map[string]bool{}
	for key := range strings.SplitSeq(q.Get("sort"), ",") {
		if key == "" {
			continue
		}
		dir, name := "ASC", key
		if rest, ok := strings.CutPrefix(key, "-"); ok {
			dir, name = "DESC", rest
		}
		col, ok := sortable[name]
		if !ok || seen[name] || len(seen) == 3 {
			return "", nil, fmt.Errorf("bad sort key %q", key)
		}
		seen[name] = true
		term := col.column + " " + dir
		if col.nullable {
			term += " NULLS LAST" // the same place for NULL in both directions
		}
		order = append(order, term)
	}
	if len(order) == 0 {
		order = append(order, "created_at DESC")
	}
	order = append(order, "id ASC") // unique tiebreaker: a total, repeatable order

	limit := 25
	if raw := q.Get("limit"); raw != "" {
		n, err := strconv.Atoi(raw)
		if err != nil || n < 1 || n > 100 {
			return "", nil, errors.New("limit must be 1..100")
		}
		limit = n
	}
	sql := "SELECT id, title, status, priority FROM issues WHERE " + strings.Join(b.where, " AND ") +
		" ORDER BY " + strings.Join(order, ", ") + " LIMIT " + b.bind(limit)
	return sql, b.args, nil
}

func formatArgs(args []any) string {
	parts := make([]string, len(args))
	for i, a := range args {
		switch v := a.(type) {
		case string:
			parts[i] = strconv.Quote(v)
		case time.Time:
			parts[i] = v.Format(time.RFC3339)
		default:
			parts[i] = fmt.Sprint(v)
		}
	}
	return "[" + strings.Join(parts, " ") + "]"
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.GET("/projects/:project/issues", func(c *gin.Context) {
		projectID, err := strconv.ParseInt(c.Param("project"), 10, 64)
		if err != nil || projectID <= 0 {
			c.AbortWithStatusJSON(http.StatusNotFound, gin.H{"error": "no such project"})
			return
		}
		query, err := url.ParseQuery(c.Request.URL.RawQuery) // strict: c.Request.URL.Query drops errors
		if err != nil {
			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "malformed query string"})
			return
		}
		sql, args, err := buildQuery(projectID, query)
		if err != nil {
			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.String(http.StatusOK, "%s\n  args: %s", sql, formatArgs(args))
	})

	for _, target := range []string{
		"/projects/7/issues",
		"/projects/7/issues?status=triaged,open&assignee=42&assignee=9,42&q=100%25_done&sort=-priority,due",
		"/projects/7/issues?status=open&status=triaged&created_after=2026-11-01T09:00:00%2B02:00&limit=50",
		"/projects/7/issues?sort=created%3BDROP+TABLE+issues",
		"/projects/7/issues?status=open;closed",
		"/projects/7/issues?status=open&status=archived",
		"/projects/7/issues?sort=priority,-priority",
		"/projects/7/issues?state=open",
	} {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, target, nil))
		fmt.Printf("GET %s\n  %d %s\n", target, w.Code, w.Body.String())
	}
}

// One placeholder per element: the statement text changes with the count.
//   status IN ($2, $3)
// One array argument: the statement text is the same for 1 or 20 values.
//   status = ANY($2)
func (b *builder) anyOf(column string, values any) {
	b.where = append(b.where, column+" = ANY("+b.bind(values)+")")
}

// With pgx, a []string or []int64 argument is sent as a PostgreSQL array.
// With lib/pq, wrap it: b.anyOf("assignee_id", pq.Array(ids)).
b.anyOf("assignee_id", ids)

package main

import (
	"context"
	"errors"
	"fmt"
	"maps"
	"net/http"
	"net/http/httptest"
	"slices"
	"strings"
	"sync"

	"github.com/gin-gonic/gin"
	"golang.org/x/sync/errgroup"
)

type Post struct {
	ID       int
	AuthorID int
	Title    string
}

type Author struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

// Store is an in-memory model of a database. It counts every call so the
// program can show how many round trips one request costs.
type Store struct {
	mu       sync.Mutex
	calls    map[string]int
	failTags bool
}

func (s *Store) count(name string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.calls[name]++
}

func (s *Store) Calls() string {
	s.mu.Lock()
	defer s.mu.Unlock()
	var parts []string
	for _, name := range slices.Sorted(maps.Keys(s.calls)) {
		parts = append(parts, fmt.Sprintf("%s=%d", name, s.calls[name]))
	}
	clear(s.calls)
	if len(parts) == 0 {
		return "none"
	}
	return strings.Join(parts, " ")
}

var authors = map[int]Author{7: {7, "kestrel"}, 9: {9, "heron"}}
var tags = map[int][]string{1: {"go", "concurrency"}, 3: {"sql"}}

func (s *Store) ListPosts(ctx context.Context) ([]Post, error) {
	s.count("ListPosts")
	return []Post{{1, 7, "Channels"}, {2, 9, "Interfaces"}, {3, 7, "database/sql"}, {4, 9, "Generics"}}, ctx.Err()
}

// AuthorByID is what a naive include calls once per post.
func (s *Store) AuthorByID(ctx context.Context, id int) (Author, error) {
	s.count("AuthorByID")
	return authors[id], ctx.Err()
}

// AuthorsByIDs is one round trip for a whole page: WHERE id = ANY($1).
func (s *Store) AuthorsByIDs(ctx context.Context, ids []int) (map[int]Author, error) {
	s.count("AuthorsByIDs")
	out := map[int]Author{}
	for _, id := range ids {
		if a, ok := authors[id]; ok {
			out[id] = a
		}
	}
	return out, ctx.Err()
}

func (s *Store) TagsByPostIDs(ctx context.Context, ids []int) (map[int][]string, error) {
	s.count("TagsByPostIDs")
	if s.failTags {
		return nil, errors.New("tags replica unavailable")
	}
	out := map[int][]string{}
	for _, id := range ids {
		out[id] = slices.Sorted(slices.Values(tags[id]))
	}
	return out, ctx.Err()
}

type postDTO struct {
	ID     int      `json:"id"`
	Title  string   `json:"title"`
	Author *Author  `json:"author,omitzero"`
	Tags   []string `json:"tags,omitzero"`
}

// relations is the allow-list: each include names one batched loader that
// fills only its own field of the page.
type page struct {
	posts   []Post
	authors map[int]Author
	tags    map[int][]string
}

var relations = map[string]func(context.Context, *Store, *page) error{
	"author": func(ctx context.Context, s *Store, p *page) error {
		ids := make([]int, 0, len(p.posts))
		for _, post := range p.posts {
			ids = append(ids, post.AuthorID)
		}
		slices.Sort(ids)
		var err error
		p.authors, err = s.AuthorsByIDs(ctx, slices.Compact(ids))
		return err
	},
	"tags": func(ctx context.Context, s *Store, p *page) error {
		ids := make([]int, len(p.posts))
		for i, post := range p.posts {
			ids[i] = post.ID
		}
		var err error
		p.tags, err = s.TagsByPostIDs(ctx, ids)
		return err
	},
}

func parseIncludes(raw []string) ([]string, error) {
	var out []string
	for _, v := range raw {
		for name := range strings.SplitSeq(v, ",") {
			if _, ok := relations[name]; !ok {
				return nil, fmt.Errorf("unknown include %q", name)
			}
			if !slices.Contains(out, name) {
				out = append(out, name)
			}
		}
	}
	return out, nil
}

func listPosts(s *Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		includes, err := parseIncludes(c.QueryArray("include"))
		if err != nil {
			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": err.Error(),
				"allowed": slices.Sorted(maps.Keys(relations))})
			return
		}
		ctx := c.Request.Context() // goroutines get this, never c
		posts, err := s.ListPosts(ctx)
		if err != nil {
			c.AbortWithStatus(http.StatusInternalServerError)
			return
		}
		p := &page{posts: posts}
		g, gctx := errgroup.WithContext(ctx)
		g.SetLimit(2) // at most two relation queries hold pool connections at once
		for _, name := range includes {
			load := relations[name]
			g.Go(func() error { return load(gctx, s, p) })
		}
		if err := g.Wait(); err != nil { // gctx is canceled from here on
			c.AbortWithStatusJSON(http.StatusServiceUnavailable, gin.H{"error": "related data unavailable"})
			return
		}
		out := make([]postDTO, len(posts)) // response order is the order of posts
		for i, post := range posts {
			out[i] = postDTO{ID: post.ID, Title: post.Title}
			if a, ok := p.authors[post.AuthorID]; ok {
				out[i].Author = &a
			}
			if p.tags != nil {
				out[i].Tags = append([]string{}, p.tags[post.ID]...) // [] when included but empty
			}
		}
		c.JSON(http.StatusOK, gin.H{"posts": out})
	}
}

// naiveAuthors is the N+1 shape: one query for the list, one per row.
func naiveAuthors(s *Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		ctx := c.Request.Context()
		posts, _ := s.ListPosts(ctx)
		names := make([]string, len(posts))
		for i, post := range posts {
			a, _ := s.AuthorByID(ctx, post.AuthorID)
			names[i] = a.Name
		}
		c.JSON(http.StatusOK, gin.H{"authors": names})
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	s := &Store{calls: map[string]int{}}
	r := gin.New()
	r.GET("/posts", listPosts(s))
	r.GET("/naive/posts", naiveAuthors(s))

	get := func(target string, showBody bool) {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, target, nil))
		fmt.Printf("GET %s -> %d, store calls: %s\n", target, w.Code, s.Calls())
		if showBody {
			fmt.Println(" ", w.Body.String())
		}
	}
	get("/naive/posts", false)
	get("/posts", false)
	get("/posts?include=author", false)
	get("/posts?include=author,tags&include=author", true)
	get("/posts?include=author,reviews", true)

	s.failTags = true
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/posts?include=tags", nil))
	fmt.Println("tags store failing ->", w.Code, w.Body.String())
}

// TagsByPostIDs is one round trip for the whole page, ordered by the database.
func (s *PG) TagsByPostIDs(ctx context.Context, ids []int64) (map[int64][]string, error) {
	rows, err := s.db.QueryContext(ctx,
		`SELECT post_id, tag FROM post_tags WHERE post_id = ANY($1) ORDER BY post_id, tag`, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := make(map[int64][]string, len(ids))
	for rows.Next() {
		var id int64
		var tag string
		if err := rows.Scan(&id, &tag); err != nil {
			return nil, err
		}
		out[id] = append(out[id], tag)
	}
	return out, rows.Err()
}

package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"maps"
	"net/http"
	"net/http/httptest"
	"net/url"
	"slices"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/gin-gonic/gin"
	"golang.org/x/sync/singleflight"
)

// Clock is injected so that tests, not the wall clock, decide when entries expire.
type Clock struct {
	mu  sync.Mutex
	now time.Time
}

func (c *Clock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *Clock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

// entry is everything needed to replay a response. It is shared by
// concurrent readers, so it is never modified after it is stored.
type entry struct {
	status int
	header http.Header
	body   []byte
	stored time.Time
}

type ResponseCache struct {
	now      func() time.Time
	ttl      time.Duration
	allowed  map[string][]string // route template -> query parameters it reads
	coalesce bool
	group    singleflight.Group

	mu      sync.Mutex
	entries map[string]entry
	gen     map[string]uint64 // bumped per route template on every invalidation
}

func (rc *ResponseCache) get(key string) (entry, bool) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	e, ok := rc.entries[key]
	if ok && rc.now().Sub(e.stored) >= rc.ttl {
		delete(rc.entries, key)
		return entry{}, false
	}
	return e, ok
}

func (rc *ResponseCache) generation(route string) uint64 {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	return rc.gen[route]
}

// put stores e unless the route was invalidated after the fill started.
func (rc *ResponseCache) put(route, key string, gen uint64, e entry) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	if rc.gen[route] == gen {
		rc.entries[key] = e
	}
}

func (rc *ResponseCache) Invalidate(routes ...string) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	for _, route := range routes {
		rc.gen[route]++
	}
	for key := range rc.entries {
		route, _, _ := strings.Cut(key, " ")
		if slices.Contains(routes, route) {
			delete(rc.entries, key)
		}
	}
}

// key returns false when the request must bypass the cache.
func (rc *ResponseCache) key(c *gin.Context) (route, key string, ok bool) {
	route = c.FullPath()
	params, listed := rc.allowed[route]
	if c.Request.Method != http.MethodGet || !listed {
		return "", "", false
	}
	if c.GetHeader("Authorization") != "" || c.GetHeader("Cookie") != "" {
		return "", "", false // the response may depend on who is asking
	}
	q, err := url.ParseQuery(c.Request.URL.RawQuery)
	if err != nil {
		return "", "", false
	}
	for name := range q {
		if !slices.Contains(params, name) {
			return "", "", false // an input the key would not capture
		}
	}
	key = route
	for _, p := range c.Params {
		key += " " + p.Key + "=" + url.QueryEscape(p.Value)
	}
	return route, key + " ?" + q.Encode(), true // Encode sorts by name
}

// capture buffers the handler's response instead of sending it.
type capture struct {
	gin.ResponseWriter
	header http.Header
	status int
	body   bytes.Buffer
}

func (w *capture) Header() http.Header               { return w.header }
func (w *capture) WriteHeader(code int)              { w.status = code }
func (w *capture) WriteHeaderNow()                   {}
func (w *capture) Write(b []byte) (int, error)       { return w.body.Write(b) }
func (w *capture) WriteString(s string) (int, error) { return w.body.WriteString(s) }
func (w *capture) Status() int                       { return w.status }
func (w *capture) Size() int                         { return w.body.Len() }
func (w *capture) Written() bool                     { return w.body.Len() > 0 }
func (w *capture) Flush()                            {}

// record runs the rest of the chain for a full, unconditional response.
func (rc *ResponseCache) record(c *gin.Context) entry {
	w := &capture{ResponseWriter: c.Writer, header: http.Header{}, status: http.StatusOK}
	writer, req := c.Writer, c.Request
	defer func() { c.Writer, c.Request = writer, req }() // also when a handler panics
	c.Writer, c.Request = w, req.Clone(req.Context())
	c.Request.Header.Del("If-None-Match") // never store a 304 meant for one client
	c.Request.Header.Del("If-Modified-Since")
	c.Next()
	return entry{status: w.status, header: w.header, body: bytes.Clone(w.body.Bytes()), stored: rc.now()}
}

func storable(e entry) bool {
	var cc []string
	for d := range strings.SplitSeq(strings.ToLower(e.header.Get("Cache-Control")), ",") {
		cc = append(cc, strings.TrimSpace(d))
	}
	return e.status == http.StatusOK && e.header.Get("Set-Cookie") == "" && e.header.Get("Vary") == "" &&
		slices.Contains(cc, "public") && !slices.Contains(cc, "private") && !slices.Contains(cc, "no-store")
}

func matches(ifNoneMatch, etag string) bool {
	for candidate := range strings.SplitSeq(ifNoneMatch, ",") {
		if t := strings.TrimSpace(candidate); t == "*" || strings.TrimPrefix(t, "W/") == etag {
			return true
		}
	}
	return false
}

func (rc *ResponseCache) replay(c *gin.Context, e entry, state string) {
	h := c.Writer.Header()
	h.Set("X-Cache", state)
	h.Set("Age", strconv.Itoa(int(rc.now().Sub(e.stored)/time.Second)))
	if etag := e.header.Get("ETag"); etag != "" && matches(c.GetHeader("If-None-Match"), etag) {
		h.Set("ETag", etag)
		h.Set("Cache-Control", e.header.Get("Cache-Control"))
		c.AbortWithStatus(http.StatusNotModified)
		return
	}
	maps.Copy(h, e.header.Clone()) // copies: outer middleware may append to these slices
	c.Status(e.status)
	_, _ = c.Writer.Write(e.body)
	c.Abort()
}

func (rc *ResponseCache) Middleware(c *gin.Context) {
	route, key, ok := rc.key(c)
	if !ok {
		c.Header("X-Cache", "BYPASS")
		c.Next()
		return
	}
	if e, ok := rc.get(key); ok {
		rc.replay(c, e, "HIT")
		return
	}
	gen := rc.generation(route)
	fill := func() (any, error) {
		if e, ok := rc.get(key); ok {
			return e, nil // a flight that ended a moment ago already stored it
		}
		e := rc.record(c)
		if storable(e) {
			rc.put(route, key, gen, e)
		}
		return e, nil
	}
	var v any
	if rc.coalesce {
		v, _, _ = rc.group.Do(key+" #"+strconv.FormatUint(gen, 10), fill)
	} else {
		v, _ = fill()
	}
	rc.replay(c, v.(entry), "MISS")
}

// articles is the origin handler with counters the demo can read.
type articles struct {
	version atomic.Int64
	calls   atomic.Int64
	gate    chan struct{} // when set, the handler waits so misses overlap
	entered chan struct{}
}

func (a *articles) list(c *gin.Context) {
	a.calls.Add(1)
	version := a.version.Load() // read the data first, as a query would
	if a.gate != nil {
		a.entered <- struct{}{}
		<-a.gate
	}
	body := fmt.Sprintf(`{"page":%q,"sort":%q,"version":%d}`, c.DefaultQuery("page", "1"),
		c.DefaultQuery("sort", "new"), version)
	sum := sha256.Sum256([]byte(body))
	c.Header("ETag", `"`+hex.EncodeToString(sum[:8])+`"`)
	c.Header("Cache-Control", "public, max-age=60")
	c.Data(http.StatusOK, "application/json", []byte(body))
}

func main() {
	gin.SetMode(gin.TestMode)
	clock := &Clock{now: time.Date(2026, 11, 18, 12, 0, 0, 0, time.UTC)}
	rc := &ResponseCache{now: clock.Now, ttl: time.Minute, coalesce: true,
		allowed: map[string][]string{"/articles": {"page", "sort"}},
		entries: map[string]entry{}, gen: map[string]uint64{}}
	a := &articles{}
	a.version.Store(1)

	r := gin.New()
	r.Use(rc.Middleware)
	r.GET("/articles", a.list)
	r.POST("/articles", func(c *gin.Context) {
		a.version.Add(1) // the write commits first,
		rc.Invalidate("/articles")
		c.Status(http.StatusCreated) // then the cache forgets
	})

	do := func(method, target string, header ...string) *httptest.ResponseRecorder {
		req := httptest.NewRequest(method, target, nil)
		for i := 0; i+1 < len(header); i += 2 {
			req.Header.Set(header[i], header[i+1])
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		return w
	}
	show := func(label, method, target string, header ...string) *httptest.ResponseRecorder {
		w := do(method, target, header...)
		age := w.Header().Get("Age")
		if age == "" {
			age = "-"
		}
		fmt.Printf("%-13s %d %-6s age=%-2s handler calls=%d\n", label, w.Code, w.Header().Get("X-Cache"), age, a.calls.Load())
		return w
	}

	first := show("first", "GET", "/articles?page=1&sort=new")
	clock.Advance(10 * time.Second)
	show("reordered", "GET", "/articles?sort=new&page=1")
	show("bearer", "GET", "/articles?page=1&sort=new", "Authorization", "Bearer t-1")
	show("cookie", "GET", "/articles?page=1&sort=new", "Cookie", "session=s-1")
	show("utm param", "GET", "/articles?page=1&sort=new&utm_source=mail")
	show("If-None-Match", "GET", "/articles?page=1&sort=new", "If-None-Match", first.Header().Get("ETag"))
	fmt.Println("POST /articles", do("POST", "/articles").Code)
	after := show("after write", "GET", "/articles?page=1&sort=new")
	fmt.Println("  new body:", after.Body.String())
	clock.Advance(time.Minute)
	show("after TTL", "GET", "/articles?page=1&sort=new")

	a.gate, a.entered = make(chan struct{}), make(chan struct{}, 1)
	slow := make(chan string)
	go func() { slow <- do("GET", "/articles?page=4").Body.String() }()
	<-a.entered // this fill has read version 2 and is still running
	do("POST", "/articles")
	close(a.gate)
	inflight := <-slow
	a.gate = nil
	next := do("GET", "/articles?page=4")
	fmt.Println("write during a fill: in-flight", inflight)
	fmt.Println("  next GET", next.Header().Get("X-Cache"), next.Body.String())

	burst := func(target string, wait int) (calls int64, identical bool) {
		a.gate, a.entered = make(chan struct{}), make(chan struct{}, 5)
		before := a.calls.Load()
		bodies := make([]string, 5)
		var wg sync.WaitGroup
		for i := range bodies {
			wg.Go(func() { bodies[i] = do("GET", target).Body.String() })
		}
		for range wait {
			<-a.entered // these handler calls are now in flight together
		}
		close(a.gate)
		wg.Wait()
		a.gate = nil
		identical = true
		for _, b := range bodies {
			identical = identical && b == bodies[0]
		}
		return a.calls.Load() - before, identical
	}
	calls, same := burst("/articles?page=2", 1)
	fmt.Printf("5 concurrent misses, singleflight: handler calls=%d identical bodies=%t\n", calls, same)
	rc.coalesce = false
	calls, same = burst("/articles?page=3", 5)
	fmt.Printf("5 concurrent misses, no coalescing: handler calls=%d identical bodies=%t\n", calls, same)
}

package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"reflect"
	"strings"

	"github.com/gin-gonic/gin"
	"github.com/gin-gonic/gin/binding"
	"github.com/go-playground/validator/v10"
)

const (
	maxBody = 1 << 10 // whole request; a real service allows megabytes
	maxLine = 120     // one record, newline included
	maxRows = 1000    // bounds the transaction and the report
)

type Product struct {
	SKU        string `json:"sku" binding:"required,alphanum,max=12"`
	Name       string `json:"name" binding:"required,max=40"`
	PriceCents int    `json:"price_cents" binding:"gt=0"`
}

type Row struct {
	Line   int    `json:"line"`
	Status string `json:"status"` // "valid" or "rejected"
	SKU    string `json:"sku,omitempty"`
	Reason string `json:"reason,omitempty"`
}

type Report struct {
	Mode     string `json:"mode"`
	Imported int    `json:"imported"`
	Rows     []Row  `json:"rows"`
}

// Catalog models the database; Tx models one transaction.
type Catalog struct{ items map[string]Product }
type Tx struct {
	cat     *Catalog
	pending []Product
}

func (c *Catalog) Begin() *Tx { return &Tx{cat: c} }
func (t *Tx) Put(p Product)   { t.pending = append(t.pending, p) }
func (t *Tx) Rollback()       { t.pending = nil }
func (t *Tx) Commit() (n int) {
	for _, p := range t.pending {
		t.cat.items[p.SKU] = p
	}
	n, t.pending = len(t.pending), nil
	return n
}

var errTooManyRows = errors.New("too many rows")

// readLines calls fn once per non-blank line. A line longer than limit bytes is
// reported with a nil slice and skipped without ever being held in memory.
func readLines(r io.Reader, limit int, fn func(n int, line []byte) error) error {
	br := bufio.NewReaderSize(r, limit)
	for n := 1; ; n++ {
		line, err := br.ReadSlice('\n')
		tooLong := errors.Is(err, bufio.ErrBufferFull)
		for errors.Is(err, bufio.ErrBufferFull) {
			_, err = br.ReadSlice('\n') // discard the rest of the line
		}
		if err != nil && err != io.EOF {
			return err // *http.MaxBytesError or a broken connection
		}
		if tooLong {
			line = nil
		}
		if tooLong || len(bytes.TrimSpace(line)) > 0 { // blank lines count, but are skipped
			if ferr := fn(n, line); ferr != nil {
				return ferr
			}
		}
		if err == io.EOF {
			return nil
		}
	}
}

// decodeRow decodes exactly one JSON object and validates it with Gin's validator.
func decodeRow(line []byte) (Product, string) {
	var p Product
	dec := json.NewDecoder(bytes.NewReader(line))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&p); err != nil {
		var syn *json.SyntaxError
		var typ *json.UnmarshalTypeError
		switch {
		case errors.As(err, &syn), errors.Is(err, io.ErrUnexpectedEOF):
			return p, "invalid JSON"
		case errors.As(err, &typ):
			return p, typ.Field + " has the wrong type"
		default:
			return p, strings.TrimPrefix(err.Error(), "json: ")
		}
	}
	if dec.Decode(new(json.RawMessage)) != io.EOF {
		return p, "more than one JSON value on the line"
	}
	if err := binding.Validator.ValidateStruct(&p); err != nil {
		var ves validator.ValidationErrors
		if errors.As(err, &ves) {
			return p, ves[0].Field() + " fails " + ves[0].Tag()
		}
		return p, "invalid"
	}
	return p, ""
}

func importProducts(cat *Catalog) gin.HandlerFunc {
	return func(c *gin.Context) {
		if c.ContentType() != "application/x-ndjson" {
			c.JSON(http.StatusUnsupportedMediaType, gin.H{"error": "send application/x-ndjson"})
			return
		}
		mode := c.DefaultQuery("mode", "all")
		if mode != "all" && mode != "partial" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "mode is all or partial"})
			return
		}
		body := http.MaxBytesReader(c.Writer, c.Request.Body, maxBody)
		tx := cat.Begin()
		rep := Report{Mode: mode, Rows: []Row{}}
		seen := map[string]int{} // sku -> first line, to catch duplicates in one file
		valid := 0
		err := readLines(body, maxLine, func(n int, line []byte) error {
			if len(rep.Rows) == maxRows {
				return errTooManyRows
			}
			if line == nil {
				rep.Rows = append(rep.Rows, Row{Line: n, Status: "rejected", Reason: fmt.Sprintf("longer than %d bytes", maxLine)})
				return nil
			}
			p, reason := decodeRow(line)
			if first, dup := seen[p.SKU]; reason == "" && dup {
				reason = fmt.Sprintf("duplicate sku %s, first on line %d", p.SKU, first)
			}
			if reason != "" {
				rep.Rows = append(rep.Rows, Row{Line: n, Status: "rejected", Reason: reason})
				return nil
			}
			seen[p.SKU] = n
			tx.Put(p) // the database holds pending rows, not the handler
			valid++
			rep.Rows = append(rep.Rows, Row{Line: n, Status: "valid", SKU: p.SKU})
			return nil
		})
		var tooBig *http.MaxBytesError
		switch {
		case errors.As(err, &tooBig):
			tx.Rollback()
			c.JSON(http.StatusRequestEntityTooLarge, gin.H{"error": fmt.Sprintf("body exceeds %d bytes", tooBig.Limit)})
			return
		case errors.Is(err, errTooManyRows):
			tx.Rollback()
			c.JSON(http.StatusRequestEntityTooLarge, gin.H{"error": fmt.Sprintf("more than %d rows", maxRows)})
			return
		case err != nil:
			tx.Rollback()
			c.JSON(http.StatusBadRequest, gin.H{"error": "could not read body"})
			return
		case len(rep.Rows) == 0:
			tx.Rollback()
			c.JSON(http.StatusBadRequest, gin.H{"error": "no rows"})
			return
		}
		if valid == 0 || (mode == "all" && valid < len(rep.Rows)) {
			tx.Rollback() // 422 always means nothing was written
			c.JSON(http.StatusUnprocessableEntity, rep)
			return
		}
		rep.Imported = tx.Commit() // 200 means every row marked valid was written
		c.JSON(http.StatusOK, rep)
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	if v, ok := binding.Validator.Engine().(*validator.Validate); ok {
		v.RegisterTagNameFunc(func(f reflect.StructField) string {
			name, _, _ := strings.Cut(f.Tag.Get("json"), ",")
			return name
		})
	}
	cat := &Catalog{items: map[string]Product{}}
	r := gin.New()
	r.POST("/products/import", importProducts(cat))

	file := strings.Join([]string{
		`{"sku":"MUG1","name":"Gopher mug","price_cents":1200}`,
		`{"sku":"CAP2","name":"Cap","price_cents":0}`,
		`{"sku":"PIN3","name":"Pin","price_cents":300,"color":"red"}`,
		`{"sku":"HAT4","name":"Hat",`,
		`{"sku":"TEE5","name":"` + strings.Repeat("x", 100) + `","price_cents":2500}`,
		`{"sku":"MUG1","name":"Mug again","price_cents":900}`,
		``,
		`{"sku":"PIN3","name":"Pin","price_cents":300}`,
	}, "\n") + "\n"

	send := func(mode, body string) (int, Report, string) {
		req := httptest.NewRequest("POST", "/products/import?mode="+mode, strings.NewReader(body))
		req.Header.Set("Content-Type", "application/x-ndjson")
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		var rep Report
		_ = json.Unmarshal(w.Body.Bytes(), &rep)
		return w.Code, rep, w.Body.String()
	}

	code, rep, _ := send("all", file)
	fmt.Println("mode=all:", code, "imported:", rep.Imported, "catalog:", len(cat.items))
	for _, row := range rep.Rows {
		if row.Status == "valid" {
			fmt.Printf("  line %d valid %s\n", row.Line, row.SKU)
		} else {
			fmt.Printf("  line %d rejected: %s\n", row.Line, row.Reason)
		}
	}
	code, rep, _ = send("partial", file)
	fmt.Println("mode=partial:", code, "imported:", rep.Imported, "catalog:", len(cat.items))

	big := strings.Repeat(`{"sku":"MUG1","name":"Gopher mug","price_cents":1200}`+"\n", 25)
	code, _, raw := send("partial", big)
	fmt.Println("oversized body:", code, raw, "catalog:", len(cat.items))

	// The usual binder on the same body: one Decode call, the rest is ignored.
	c, _ := gin.CreateTestContext(httptest.NewRecorder())
	c.Request = httptest.NewRequest("POST", "/", strings.NewReader(file))
	var first Product
	err := c.ShouldBindJSON(&first)
	fmt.Println("ShouldBindJSON on NDJSON: err =", err, "sku =", first.SKU)
}

package main

import (
	"context"
	"encoding/csv"
	"errors"
	"fmt"
	"io"
	"mime"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"unicode"

	"github.com/gin-gonic/gin"
)

type Contact struct {
	ID                int
	Name, Email, Note string
}

// Store models a database read with keyset pagination: rows after a key, in key order.
type Store struct {
	rows   []Contact // sorted by ID
	failAt int       // page number that fails; 0 means never
	served int
	onPage func(page int)
}

func (s *Store) Page(ctx context.Context, afterID, limit int) ([]Contact, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	s.served++
	if s.served == s.failAt {
		return nil, errors.New("replica connection lost")
	}
	var out []Contact
	for _, r := range s.rows {
		if r.ID > afterID && len(out) < limit {
			out = append(out, r)
		}
	}
	if s.onPage != nil {
		s.onPage(s.served)
	}
	return out, nil
}

// safeCell keeps spreadsheet apps from evaluating user text as a formula.
func safeCell(s string) string {
	if s != "" && strings.ContainsRune("=+-@\t\r\n", rune(s[0])) {
		return "'" + s
	}
	return s
}

// exportName builds a filename from user input: letters, digits, space, - _ only.
func exportName(list string) string {
	name := strings.Map(func(r rune) rune {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || strings.ContainsRune(" -_", r) {
			return r
		}
		return -1
	}, list)
	if name = strings.TrimSpace(name); name == "" || len(name) > 60 {
		name = "contacts"
	}
	return name + ".csv"
}

func exportContacts(s *Store, pageSize int) gin.HandlerFunc {
	return func(c *gin.Context) {
		ctx := c.Request.Context()
		page, err := s.Page(ctx, 0, pageSize)
		if err != nil { // nothing is written yet, so the status can still say so
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": "export unavailable"})
			return
		}
		disp := mime.FormatMediaType("attachment", map[string]string{"filename": exportName(c.Query("list"))})
		if disp == "" {
			disp = "attachment; filename=contacts.csv"
		}
		c.Header("Content-Type", "text/csv; charset=utf-8")
		c.Header("Content-Disposition", disp)
		c.Header("X-Content-Type-Options", "nosniff")
		c.Status(http.StatusOK)

		w := csv.NewWriter(c.Writer)
		_ = w.Write([]string{"id", "name", "email", "note"})
		for {
			for _, ct := range page {
				_ = w.Write([]string{strconv.Itoa(ct.ID), safeCell(ct.Name), safeCell(ct.Email), safeCell(ct.Note)})
			}
			w.Flush() // csv's buffer -> c.Writer; the first flush commits 200
			if w.Error() != nil {
				return // the client stopped reading; nobody is left to tell
			}
			c.Writer.Flush() // c.Writer -> the connection
			if len(page) < pageSize {
				return // short page: the export is complete
			}
			page, err = s.Page(ctx, page[len(page)-1].ID, pageSize)
			if ctx.Err() != nil {
				return // client gone or server shutting down: stop reading the database
			}
			if err != nil {
				_ = c.Error(err) // for the access log
				panic(http.ErrAbortHandler)
			}
		}
	}
}

// abortPassthrough must run outside gin.Recovery, which swallows http.ErrAbortHandler.
func abortPassthrough(c *gin.Context) {
	c.Next()
	for _, e := range c.Errors {
		if errors.Is(e.Err, http.ErrAbortHandler) {
			panic(http.ErrAbortHandler) // net/http now breaks the connection
		}
	}
}

// serve is what net/http does around a handler: an ErrAbortHandler panic means
// "close the connection without finishing the body".
func serve(h http.Handler, req *http.Request) (w *httptest.ResponseRecorder, aborted bool) {
	w = httptest.NewRecorder()
	defer func() {
		if rec := recover(); rec != nil {
			if rec != http.ErrAbortHandler {
				panic(rec)
			}
			aborted = true
		}
	}()
	h.ServeHTTP(w, req)
	return w, false
}

func newRouter(s *Store, passthrough bool) *gin.Engine {
	r := gin.New()
	if passthrough {
		r.Use(abortPassthrough)
	}
	r.Use(gin.Recovery())
	r.GET("/contacts.csv", exportContacts(s, 3))
	return r
}

func main() {
	gin.SetMode(gin.TestMode)
	gin.DefaultErrorWriter = io.Discard // keep Recovery's log out of the demo
	rows := []Contact{
		{1, "Avery", "avery@example.com", `=HYPERLINK("https://attacker.example","invoice")`},
		{2, "Blake, Jr.", "blake@example.com", "+44 20 7946 0000"},
		{3, "Casey", "casey@example.com", "-2+3"},
		{4, "Devon", "devon@example.com", "@SUM(A1:A9)"},
		{5, "Emery", "emery@example.com", `says "hi"`},
		{6, "Finley", "finley@example.com", "plain note"},
		{7, "Gray", "gray@example.com", ""},
	}
	for _, list := range []string{"Q4 leads", "Zoë's list", "../../etc/passwd\r\nX: 1"} {
		fmt.Printf("%q -> %s\n", list, mime.FormatMediaType("attachment", map[string]string{"filename": exportName(list)}))
	}

	s := &Store{rows: rows}
	w, _ := serve(newRouter(s, true), httptest.NewRequest("GET", "/contacts.csv?list=Q4+leads", nil))
	fmt.Println(w.Code, w.Header().Get("Content-Type"), "pages:", s.served, "flushed:", w.Flushed)
	fmt.Print(w.Body.String())

	ctx, disconnect := context.WithCancel(context.Background())
	s = &Store{rows: rows, onPage: func(int) { disconnect() }}
	w, aborted := serve(newRouter(s, true), httptest.NewRequest("GET", "/contacts.csv", nil).WithContext(ctx))
	fmt.Println("client gone after page 1:", w.Code, "pages:", s.served, "lines:", strings.Count(w.Body.String(), "\n"), "aborted:", aborted)

	s = &Store{rows: rows, failAt: 1}
	w, _ = serve(newRouter(s, true), httptest.NewRequest("GET", "/contacts.csv", nil))
	fmt.Println("store down before first byte:", w.Code, w.Body.String())

	for _, passthrough := range []bool{false, true} {
		s = &Store{rows: rows, failAt: 2}
		w, aborted = serve(newRouter(s, passthrough), httptest.NewRequest("GET", "/contacts.csv", nil))
		fmt.Println("store fails on page 2, passthrough", passthrough, "->", w.Code, "lines:", strings.Count(w.Body.String(), "\n"), "aborted:", aborted)
	}
}

tx, err := db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelRepeatableRead, ReadOnly: true})
if err != nil {
	return err // still before the first byte: the handler can answer 503
}
defer tx.Rollback() // read-only: rolling back just releases the snapshot

rc := http.NewResponseController(c.Writer)
nextPage := func(afterID int64) (*sql.Rows, error) {
	// A fresh write budget per page instead of the server-wide WriteTimeout.
	if err := rc.SetWriteDeadline(time.Now().Add(30 * time.Second)); err != nil && !errors.Is(err, http.ErrNotSupported) {
		return nil, err
	}
	return tx.QueryContext(ctx, `SELECT id, name, email, note FROM contacts
		WHERE account_id = $1 AND id > $2 ORDER BY id LIMIT $3`, accountID, afterID, pageSize)
}

package main

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
)

type Job struct {
	ID     string `json:"id"`
	Status string `json:"status"` // queued, running, succeeded, failed
	Result string `json:"result,omitempty"`
	Error  string `json:"error,omitempty"`
}

type task struct {
	id, month string
	ctx       context.Context // request values without request cancellation
}

var errBusy = errors.New("queue full or shutting down")

// Pool is a fixed set of workers reading one bounded queue.
type Pool struct {
	mu     sync.Mutex
	jobs   map[string]*Job
	queue  chan task
	closed bool
	last   int
	wg     sync.WaitGroup
	budget time.Duration
	work   func(ctx context.Context, month string) error
}

func NewPool(workers, depth int, budget time.Duration, work func(context.Context, string) error) *Pool {
	p := &Pool{jobs: map[string]*Job{}, queue: make(chan task, depth), budget: budget, work: work}
	for range workers {
		p.wg.Go(func() {
			for t := range p.queue {
				p.update(t.id, func(j *Job) { j.Status = "running" })
				err := p.execute(t)
				p.update(t.id, func(j *Job) {
					if err != nil {
						j.Status, j.Error = "failed", err.Error()
					} else {
						j.Status, j.Result = "succeeded", "/reports/"+t.id+"/result"
					}
				})
			}
		})
	}
	return p
}

// execute gives each job its own deadline and turns a panic into a failed job.
func (p *Pool) execute(t task) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("job panicked: %v", r)
		}
	}()
	ctx, cancel := context.WithTimeout(t.ctx, p.budget)
	defer cancel()
	return p.work(ctx, t.month)
}

func (p *Pool) Submit(reqCtx context.Context, month string) (Job, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.closed {
		return Job{}, errBusy
	}
	id := strconv.Itoa(p.last + 1)
	select {
	case p.queue <- task{id: id, month: month, ctx: context.WithoutCancel(reqCtx)}:
		p.last++
		p.jobs[id] = &Job{ID: id, Status: "queued"} // workers wait for p.mu, so this lands first
		return *p.jobs[id], nil
	default:
		return Job{}, errBusy
	}
}

func (p *Pool) update(id string, f func(*Job)) {
	p.mu.Lock()
	defer p.mu.Unlock()
	f(p.jobs[id])
}

func (p *Pool) Get(id string) (Job, bool) {
	p.mu.Lock()
	defer p.mu.Unlock()
	j, ok := p.jobs[id]
	if !ok {
		return Job{}, false
	}
	return *j, true
}

// Shutdown stops intake, lets workers drain the queue and waits for them.
func (p *Pool) Shutdown() {
	p.mu.Lock()
	p.closed = true
	close(p.queue)
	p.mu.Unlock()
	p.wg.Wait()
}

func createReport(p *Pool) gin.HandlerFunc {
	return func(c *gin.Context) {
		var in struct {
			Month string `json:"month" binding:"required,datetime=2006-01"`
		}
		if err := c.ShouldBindJSON(&in); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "month must look like 2026-10"})
			return
		}
		job, err := p.Submit(c.Request.Context(), in.Month)
		if err != nil {
			c.Header("Retry-After", "30")
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": "report queue is full"})
			return
		}
		c.Header("Location", "/jobs/"+job.ID)
		c.JSON(http.StatusAccepted, job)
	}
}

func getJob(p *Pool) gin.HandlerFunc {
	return func(c *gin.Context) {
		job, ok := p.Get(c.Param("id"))
		if !ok {
			c.JSON(http.StatusNotFound, gin.H{"error": "no such job"})
			return
		}
		c.JSON(http.StatusOK, job)
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	started := make(chan string)
	release := make(chan struct{})
	work := func(ctx context.Context, month string) error {
		started <- month
		<-release
		if err := ctx.Err(); err != nil {
			return err // a job built on c.Request.Context() would stop here
		}
		if month == "2026-09" {
			return errors.New("ledger archive offline")
		}
		return nil
	}
	pool := NewPool(2, 1, time.Minute, work)
	r := gin.New()
	r.POST("/reports", createReport(pool))
	r.GET("/jobs/:id", getJob(pool))

	post := func(month string) context.Context {
		ctx, cancel := context.WithCancel(context.Background())
		req := httptest.NewRequest("POST", "/reports", strings.NewReader(`{"month":"`+month+`"}`)).WithContext(ctx)
		req.Header.Set("Content-Type", "application/json")
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		cancel() // net/http cancels the request context when ServeHTTP returns
		hdr := ""
		if v := w.Header().Get("Location"); v != "" {
			hdr = " Location: " + v
		}
		if v := w.Header().Get("Retry-After"); v != "" {
			hdr = " Retry-After: " + v
		}
		fmt.Printf("POST %s -> %d%s %s\n", month, w.Code, hdr, w.Body.String())
		return ctx
	}
	get := func(id string) {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest("GET", "/jobs/"+id, nil))
		fmt.Printf("GET /jobs/%s -> %d %s\n", id, w.Code, w.Body.String())
	}

	reqCtx := post("2026-10")
	fmt.Println("request context of job 1 after the 202:", reqCtx.Err())
	<-started // job 1 is running on one worker
	post("2026-09")
	<-started       // job 2 is running on the other
	post("2026-08") // waits in the queue
	post("2026-07") // queue full
	post("October")
	get("1")
	get("3")

	release <- struct{}{} // one worker finishes and takes job 3
	<-started
	release <- struct{}{}
	release <- struct{}{}
	pool.Shutdown()
	fmt.Println("shutdown: queue drained, workers joined")
	for _, id := range []string{"1", "2", "3", "4"} {
		get(id)
	}
}

package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
)

const (
	maxPayload = 64 << 10
	tolerance  = 5 * time.Minute
)

type Event struct {
	ID   string          `json:"id" binding:"required"`
	Type string          `json:"type" binding:"required"`
	Data json.RawMessage `json:"data"`
}

func sign(secret []byte, ts string, body []byte) []byte {
	mac := hmac.New(sha256.New, secret)
	mac.Write([]byte(ts))
	mac.Write([]byte{'.'})
	mac.Write(body)
	return mac.Sum(nil)
}

// verify checks every v1= signature in the header, so a sender can rotate secrets.
func verify(secret []byte, ts, header string, body []byte, now time.Time) error {
	want := sign(secret, ts, body)
	ok := false
	for part := range strings.SplitSeq(header, ",") {
		if v, found := strings.CutPrefix(strings.TrimSpace(part), "v1="); found {
			got, err := hex.DecodeString(v)
			ok = ok || (err == nil && hmac.Equal(got, want))
		}
	}
	if !ok {
		return errors.New("signature mismatch")
	}
	sec, err := strconv.ParseInt(ts, 10, 64)
	if err != nil {
		return errors.New("bad timestamp")
	}
	if age := now.Sub(time.Unix(sec, 0)); age > tolerance || age < -tolerance {
		return errors.New("timestamp outside tolerance")
	}
	return nil
}

// verifySignature authenticates the raw bytes before anything parses them,
// then hands the same bytes to the handler.
func verifySignature(secret []byte, now func() time.Time) gin.HandlerFunc {
	return func(c *gin.Context) {
		raw, err := io.ReadAll(http.MaxBytesReader(c.Writer, c.Request.Body, maxPayload))
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			c.AbortWithStatusJSON(http.StatusRequestEntityTooLarge, gin.H{"error": "payload too large"})
			return
		}
		if err != nil {
			c.AbortWithStatus(http.StatusBadRequest)
			return
		}
		ts, sig := c.GetHeader("Webhook-Timestamp"), c.GetHeader("Webhook-Signature")
		if err := verify(secret, ts, sig, raw, now()); err != nil {
			_ = c.Error(err) // the reason goes to the log, not to the caller
			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "invalid signature"})
			return
		}
		c.Request.Body = io.NopCloser(bytes.NewReader(raw))
		c.Next()
	}
}

// Inbox records event IDs and queues events; both happen under one lock.
type Inbox struct {
	mu    sync.Mutex
	seen  map[string]bool
	queue chan Event
}

var errBusy = errors.New("queue full")

func (in *Inbox) Accept(e Event) (duplicate bool, err error) {
	in.mu.Lock()
	defer in.mu.Unlock()
	if in.seen[e.ID] {
		return true, nil
	}
	select {
	case in.queue <- e:
		in.seen[e.ID] = true // only once the event is safely queued
		return false, nil
	default:
		return false, errBusy
	}
}

var handled = map[string]bool{"payment.succeeded": true, "payment.refunded": true}

func receive(in *Inbox) gin.HandlerFunc {
	return func(c *gin.Context) {
		var e Event
		if err := c.ShouldBindJSON(&e); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "malformed event"}) // a retry sends the same bytes
			return
		}
		if !handled[e.Type] {
			c.JSON(http.StatusOK, gin.H{"status": "ignored"}) // 4xx here would only cause retries
			return
		}
		dup, err := in.Accept(e)
		switch {
		case err != nil:
			c.Header("Retry-After", "60")
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": "busy, retry later"})
		case dup:
			c.JSON(http.StatusOK, gin.H{"status": "duplicate"})
		default:
			c.JSON(http.StatusAccepted, gin.H{"status": "queued"})
		}
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	secret := []byte("whsec-test-only-not-a-real-secret") // test key, never a production secret
	clock := time.Unix(1_800_000_000, 0)
	in := &Inbox{seen: map[string]bool{}, queue: make(chan Event, 2)}
	r := gin.New()
	var logged string
	r.Use(func(c *gin.Context) { // stands in for the access log
		c.Next()
		if e := c.Errors.Last(); e != nil {
			logged = " (log: " + e.Error() + ")"
		}
	})
	hooks := r.Group("/webhooks", verifySignature(secret, func() time.Time { return clock }))
	hooks.POST("/payments", receive(in))

	event := func(id, typ string) string {
		return `{"id":"` + id + `","type":"` + typ + `","data":{"amount":1200}}`
	}
	deliver := func(label, signed, sent string, at time.Time) {
		ts := strconv.FormatInt(at.Unix(), 10)
		req := httptest.NewRequest("POST", "/webhooks/payments", strings.NewReader(sent))
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("Webhook-Timestamp", ts)
		req.Header.Set("Webhook-Signature", "v1="+hex.EncodeToString(sign(secret, ts, []byte(signed))))
		w := httptest.NewRecorder()
		logged = ""
		r.ServeHTTP(w, req)
		fmt.Printf("%-24s %d %s%s\n", label, w.Code, w.Body.String(), logged)
	}

	e1 := event("evt_1", "payment.succeeded")
	deliver("first delivery", e1, e1, clock)
	deliver("sender retry", e1, e1, clock.Add(40*time.Second))
	deliver("tampered body", e1, strings.Replace(e1, "1200", "9900", 1), clock)
	deliver("replay after 10 minutes", e1, e1, clock.Add(-10*time.Minute))
	e2 := event("evt_2", "customer.updated")
	deliver("unhandled type", e2, e2, clock)
	e3, e4 := event("evt_3", "payment.refunded"), event("evt_4", "payment.succeeded")
	deliver("second event", e3, e3, clock)
	deliver("queue full", e4, e4, clock)
	fmt.Println("evt_4 recorded as seen:", in.seen["evt_4"])

	// The worker runs after the requests here only so the queue-full case is deterministic.
	close(in.queue)
	var wg sync.WaitGroup
	var processed []string
	wg.Go(func() {
		for e := range in.queue {
			processed = append(processed, e.ID)
		}
	})
	wg.Wait()
	fmt.Println("worker processed:", strings.Join(processed, " "))
}

// Same contract as Inbox.Accept, so the handler does not change.
func (s *Store) Accept(ctx context.Context, e Event, raw []byte) (duplicate bool, err error) {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return false, err // the handler answers 503 and the sender retries
	}
	defer tx.Rollback()
	res, err := tx.ExecContext(ctx, `INSERT INTO webhook_inbox (sender, event_id, payload)
		VALUES ($1, $2, $3) ON CONFLICT (sender, event_id) DO NOTHING`, "payments", e.ID, raw)
	if err != nil {
		return false, err
	}
	n, err := res.RowsAffected()
	if err != nil {
		return false, err
	}
	if n == 0 {
		return true, nil // already received: the handler answers 200
	}
	if _, err := tx.ExecContext(ctx, `INSERT INTO jobs (kind, input) VALUES ('webhook', $1)`, raw); err != nil {
		return false, err
	}
	return false, tx.Commit() // the handler answers 202 only when this is nil
}

func newInventoryClient() *http.Client {
	dialer := &net.Dialer{Timeout: 2 * time.Second, KeepAlive: 30 * time.Second}
	transport := &http.Transport{
		Proxy:                  http.ProxyFromEnvironment,
		DialContext:            dialer.DialContext,
		ForceAttemptHTTP2:      true, // a custom DialContext turns HTTP/2 off otherwise
		TLSHandshakeTimeout:    3 * time.Second,
		ResponseHeaderTimeout:  2 * time.Second,
		ExpectContinueTimeout:  time.Second,
		IdleConnTimeout:        90 * time.Second,
		MaxIdleConns:           100,
		MaxIdleConnsPerHost:    32, // the default of 2 churns connections under load
		MaxConnsPerHost:        64, // a hard cap: extra requests wait for a free connection
		MaxResponseHeaderBytes: 64 << 10,
	}
	return &http.Client{
		Transport: transport,
		Timeout:   5 * time.Second, // a backstop; the per-call context is the real budget
		CheckRedirect: func(*http.Request, []*http.Request) error {
			return http.ErrUseLastResponse // an API that redirects is misconfigured
		},
	}
}

