import (
	"cmp"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

// fakeInventory plays the upstream API. A RoundTripper answers in-process,
// so the real http.Client code path runs without opening a socket.
type fakeInventory struct{ seen []string }

func (f *fakeInventory) RoundTrip(req *http.Request) (*http.Response, error) {
	if err := req.Context().Err(); err != nil {
		return nil, err // http.Transport also fails fast on a finished context
	}
	_, deadline := req.Context().Deadline()
	f.seen = append(f.seen, fmt.Sprintf("%s %s deadline=%t auth=%q cookie=%q",
		req.Method, req.URL.Path, deadline, req.Header.Get("Authorization"), req.Header.Get("Cookie")))
	switch sku := strings.TrimPrefix(req.URL.Path, "/v1/stock/"); sku {
	case "DOWN":
		return nil, errors.New("dial tcp 192.0.2.10:443: connect: connection refused")
	case "SLOW":
		<-req.Context().Done() // a hung upstream: only our deadline ends the wait
		return nil, req.Context().Err()
	case "ERR":
		return reply(req, 500, `pq: relation "stock" does not exist`, "X-Backend-Host", "db-3.internal"), nil
	case "BIG":
		return reply(req, 200, `{"sku":"BIG","notes":"`+strings.Repeat("x", 1<<20)+`"}`), nil
	case "NOPE":
		return reply(req, 404, `{"message":"no such sku"}`), nil
	default:
		return reply(req, 200, `{"sku":"`+sku+`","available":4,"warehouse":"wh-eu-2","cost_cents":1250}`), nil
	}
}

func reply(req *http.Request, status int, body string, kv ...string) *http.Response {
	h := http.Header{"Content-Type": {"application/json"}}
	for i := 0; i+1 < len(kv); i += 2 {
		h.Set(kv[i], kv[i+1])
	}
	return &http.Response{StatusCode: status, Header: h, Body: io.NopCloser(strings.NewReader(body)),
		ContentLength: int64(len(body)), Request: req}
}

var errUnknownSKU = errors.New("inventory: unknown sku")

// Stock is the subset of the upstream document this service relies on.
type Stock struct {
	SKU       string `json:"sku"`
	Available int    `json:"available"`
}

type Inventory struct {
	Client  *http.Client // shared by every request: it owns the connection pool
	BaseURL string
	Token   string        // this service's credential, never the caller's
	Budget  time.Duration // per-call deadline, below the route's own budget
	MaxBody int64
}

func (inv *Inventory) Stock(ctx context.Context, sku string) (Stock, error) {
	ctx, cancel := context.WithTimeout(ctx, inv.Budget)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, inv.BaseURL+"/v1/stock/"+url.PathEscape(sku), nil)
	if err != nil {
		return Stock{}, err
	}
	req.Header.Set("Accept", "application/json")
	req.Header.Set("Authorization", "Bearer "+inv.Token)
	resp, err := inv.Client.Do(req)
	if err != nil {
		return Stock{}, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		io.Copy(io.Discard, io.LimitReader(resp.Body, 4<<10)) // drain a little so the connection can be reused
		if resp.StatusCode == http.StatusNotFound {
			return Stock{}, errUnknownSKU
		}
		return Stock{}, fmt.Errorf("inventory: status %d", resp.StatusCode)
	}
	body, err := io.ReadAll(io.LimitReader(resp.Body, inv.MaxBody+1))
	if err != nil {
		return Stock{}, fmt.Errorf("inventory: read: %w", err)
	}
	if int64(len(body)) > inv.MaxBody {
		return Stock{}, fmt.Errorf("inventory: body over %d bytes", inv.MaxBody)
	}
	var s Stock
	if err := json.Unmarshal(body, &s); err != nil {
		return Stock{}, fmt.Errorf("inventory: decode: %w", err)
	}
	return s, nil
}

var logs []string // stands in for a structured logger

// fail maps an upstream failure to this API's own error format.
func fail(c *gin.Context, err error) {
	status, code := http.StatusBadGateway, "inventory_unavailable"
	switch {
	case errors.Is(err, errUnknownSKU):
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "unknown_sku"}})
		return
	case c.Request.Context().Err() != nil:
		logs = append(logs, "client went away: "+err.Error())
		c.AbortWithStatus(499) // nobody reads this; it only labels logs and metrics
		return
	case errors.Is(err, context.DeadlineExceeded):
		status, code = http.StatusGatewayTimeout, "inventory_timeout"
	}
	logs = append(logs, err.Error()) // the cause goes to logs, never to the client
	c.JSON(status, gin.H{"error": gin.H{"code": code}})
}

func main() {
	gin.SetMode(gin.TestMode)
	upstream := &fakeInventory{}
	inv := &Inventory{
		Client:  &http.Client{Transport: upstream},
		BaseURL: "https://inventory.internal.example",
		Token:   "svc-test-token",
		Budget:  50 * time.Millisecond,
		MaxBody: 64 << 10,
	}
	r := gin.New()
	r.GET("/products/:sku/stock", func(c *gin.Context) {
		s, err := inv.Stock(c.Request.Context(), c.Param("sku"))
		if err != nil {
			fail(c, err)
			return
		}
		c.JSON(http.StatusOK, s) // our type: warehouse and cost_cents never reach the client
	})

	for _, sku := range []string{"A-1", "NOPE", "ERR", "BIG", "DOWN", "SLOW", "GONE"} {
		req := httptest.NewRequest(http.MethodGet, "/products/"+sku+"/stock", nil)
		req.Header.Set("Authorization", "Bearer end-user-token")
		req.Header.Set("Cookie", "session=s3cr3t")
		if sku == "GONE" {
			ctx, cancel := context.WithCancel(req.Context())
			cancel() // the client disconnected before the upstream call
			req = req.WithContext(ctx)
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Printf("%s -> %d %s\n", sku, w.Code, cmp.Or(w.Body.String(), "(no body)"))
		for _, line := range logs {
			fmt.Println("  log:", line)
		}
		logs = logs[:0]
		if sku == "A-1" {
			fmt.Println("  upstream saw:", upstream.seen[0])
		}
		if sku == "ERR" {
			leaked := w.Header().Get("X-Backend-Host") != "" || strings.Contains(w.Body.String(), "pq:")
			fmt.Println("  upstream detail leaked:", leaked)
		}
	}
}

package main

import (
	"errors"
	"fmt"
	"io"
	"math/rand/v2"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
)

// fakeClock is the injected clock: Sleep advances time instead of blocking.
type fakeClock struct{ now time.Time }

func (c *fakeClock) Now() time.Time        { return c.now }
func (c *fakeClock) Sleep(d time.Duration) { c.now = c.now.Add(d) }

// scripted plays the upstream: each call takes the next step of the script.
type scripted struct {
	script []string // "200", "503", "429:2" (status:Retry-After)
	calls  int
}

func (s *scripted) RoundTrip(req *http.Request) (*http.Response, error) {
	s.calls++
	step := "200"
	if len(s.script) > 0 {
		step, s.script = s.script[0], s.script[1:]
	}
	code, after, _ := strings.Cut(step, ":")
	status, _ := strconv.Atoi(code)
	h := http.Header{}
	if after != "" {
		h.Set("Retry-After", after)
	}
	return &http.Response{StatusCode: status, Header: h, Body: io.NopCloser(strings.NewReader("{}")), Request: req}, nil
}

type state int

const (
	closed state = iota
	open
	halfOpen
)

// Breaker opens after Threshold consecutive failures, stays open for
// Cooldown, then lets exactly one probe through.
type Breaker struct {
	mu        sync.Mutex
	Clock     *fakeClock
	Threshold int
	Cooldown  time.Duration
	state     state
	failures  int
	openedAt  time.Time
	probing   bool
}

// Allow reports whether a call may go out and, if not, when to try again.
func (b *Breaker) Allow() (time.Duration, bool) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.state == open {
		if wait := b.openedAt.Add(b.Cooldown).Sub(b.Clock.Now()); wait > 0 {
			return wait, false
		}
		b.state, b.probing = halfOpen, false
	}
	if b.state == halfOpen {
		if b.probing {
			return time.Second, false // one probe at a time
		}
		b.probing = true
	}
	return 0, true
}

func (b *Breaker) Record(ok bool) {
	b.mu.Lock()
	defer b.mu.Unlock()
	switch {
	case ok:
		b.state, b.failures, b.probing = closed, 0, false
	case b.state == halfOpen:
		b.state, b.openedAt, b.probing = open, b.Clock.Now(), false
	default:
		b.failures++
		if b.failures >= b.Threshold {
			b.state, b.openedAt = open, b.Clock.Now()
		}
	}
}

func (b *Breaker) Open() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.state == open
}

// Budget caps retries at a fraction of traffic: every call deposits Ratio,
// every retry spends one token, and the balance never exceeds Max.
type Budget struct {
	mu                 sync.Mutex
	Tokens, Ratio, Max float64
}

func (b *Budget) Deposit() {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.Tokens = min(b.Max, b.Tokens+b.Ratio)
}

func (b *Budget) Spend() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.Tokens < 1 {
		return false
	}
	b.Tokens--
	return true
}

type OpenError struct{ RetryAfter time.Duration }

func (e *OpenError) Error() string { return "circuit open" }

type Retrier struct {
	Client      *http.Client
	Clock       *fakeClock
	Rand        *rand.Rand // seeded, so the jitter below is reproducible
	Breaker     *Breaker
	Budget      *Budget
	MaxAttempts int
	Base, Cap   time.Duration
	MaxWait     time.Duration // total waiting allowed for one call
	trace       []string
}

func safeToRetry(req *http.Request) bool {
	if req.Body != nil && req.Body != http.NoBody && req.GetBody == nil {
		return false // the body was consumed and cannot be sent again
	}
	switch req.Method {
	case http.MethodGet, http.MethodHead, http.MethodOptions, http.MethodPut, http.MethodDelete:
		return true
	}
	return req.Header.Get("Idempotency-Key") != ""
}

func retryableStatus(code int) bool {
	return code == http.StatusTooManyRequests || code == http.StatusBadGateway ||
		code == http.StatusServiceUnavailable || code == http.StatusGatewayTimeout
}

// retryAfter accepts delay-seconds or an HTTP-date, as RFC 9110 allows.
func retryAfter(v string, now time.Time) (time.Duration, bool) {
	if s, err := strconv.Atoi(v); err == nil && s >= 0 {
		return time.Duration(s) * time.Second, true
	}
	if t, err := http.ParseTime(v); err == nil {
		return max(0, t.Sub(now)), true
	}
	return 0, false
}

// backoff is "full jitter": uniform in [0, min(Cap, Base*2^(attempt-1))).
func (r *Retrier) backoff(attempt int) time.Duration {
	ceiling := min(r.Cap, r.Base<<(attempt-1))
	return time.Duration(r.Rand.Int64N(int64(ceiling))).Truncate(time.Millisecond)
}

func (r *Retrier) Do(req *http.Request) (*http.Response, error) {
	r.trace = r.trace[:0]
	r.Budget.Deposit()
	deadline := r.Clock.Now().Add(r.MaxWait)
	for attempt := 1; ; attempt++ {
		if wait, ok := r.Breaker.Allow(); !ok {
			r.trace = append(r.trace, "rejected by open breaker")
			return nil, &OpenError{RetryAfter: wait}
		}
		if req.GetBody != nil {
			req.Body, _ = req.GetBody() // a fresh copy of the body for every attempt
		}
		resp, err := r.Client.Do(req)
		r.Breaker.Record(err == nil && resp.StatusCode < 500)
		if err == nil && !retryableStatus(resp.StatusCode) {
			r.trace = append(r.trace, strconv.Itoa(resp.StatusCode))
			return resp, nil
		}
		label := "error"
		wait := r.backoff(attempt)
		if err == nil {
			label = strconv.Itoa(resp.StatusCode)
			if d, ok := retryAfter(resp.Header.Get("Retry-After"), r.Clock.Now()); ok {
				wait = d // the server named the wait; honor it instead of guessing
			}
		}
		stop := ""
		switch {
		case !safeToRetry(req):
			stop = "not idempotent"
		case attempt == r.MaxAttempts:
			stop = "attempts used"
		case r.Breaker.Open():
			stop = "circuit opened"
		case r.Clock.Now().Add(wait).After(deadline):
			stop = "deadline"
		case !r.Budget.Spend():
			stop = "budget empty"
		}
		if stop != "" {
			r.trace = append(r.trace, label+" stop: "+stop)
			return resp, err
		}
		if resp != nil {
			io.Copy(io.Discard, resp.Body)
			resp.Body.Close()
		}
		r.trace = append(r.trace, label+" wait "+wait.String())
		r.Clock.Sleep(wait)
	}
}

// respond turns the outcome into this API's answer.
func respond(c *gin.Context, resp *http.Response, err error) {
	var open *OpenError
	switch {
	case errors.As(err, &open):
		secs := int((open.RetryAfter + time.Second - 1) / time.Second)
		c.Header("Retry-After", strconv.Itoa(secs))
		c.JSON(http.StatusServiceUnavailable, gin.H{"error": "quotes_unavailable"})
	case err != nil || resp.StatusCode >= 500 || resp.StatusCode == http.StatusTooManyRequests:
		c.JSON(http.StatusBadGateway, gin.H{"error": "quotes_failed"})
	default:
		resp.Body.Close()
		c.JSON(resp.StatusCode, gin.H{"ok": true})
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	clock := &fakeClock{now: time.Date(2026, 11, 18, 9, 0, 0, 0, time.UTC)}
	up := &scripted{}
	rt := &Retrier{
		Client:      &http.Client{Transport: up},
		Clock:       clock,
		Rand:        rand.New(rand.NewPCG(1, 2)),
		Breaker:     &Breaker{Clock: clock, Threshold: 3, Cooldown: 30 * time.Second},
		Budget:      &Budget{Tokens: 3, Ratio: 0.5, Max: 3},
		MaxAttempts: 3,
		Base:        100 * time.Millisecond,
		Cap:         time.Second,
		MaxWait:     3 * time.Second,
	}
	const upstream = "https://quotes.internal.example/v1"
	r := gin.New()
	r.GET("/quotes/:sym", func(c *gin.Context) {
		req, _ := http.NewRequestWithContext(c.Request.Context(), http.MethodGet, upstream+"/quotes/"+c.Param("sym"), nil)
		resp, err := rt.Do(req)
		respond(c, resp, err)
	})
	r.POST("/orders", func(c *gin.Context) {
		body, _ := io.ReadAll(io.LimitReader(c.Request.Body, 1<<20))
		req, _ := http.NewRequestWithContext(c.Request.Context(), http.MethodPost, upstream+"/orders", strings.NewReader(string(body)))
		if key := c.GetHeader("Idempotency-Key"); key != "" {
			req.Header.Set("Idempotency-Key", key) // the upstream dedupes on it
		}
		resp, err := rt.Do(req)
		respond(c, resp, err)
	})

	call := func(label, method, path, key string, script ...string) {
		up.script = script
		req := httptest.NewRequest(method, path, strings.NewReader(`{"qty":1}`))
		if key != "" {
			req.Header.Set("Idempotency-Key", key)
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		extra := ""
		if ra := w.Header().Get("Retry-After"); ra != "" {
			extra = " Retry-After=" + ra
		}
		fmt.Printf("%-14s %s -> %d%s\n", label, strings.Join(rt.trace, ", "), w.Code, extra)
	}
	call("GET flaky", "GET", "/quotes/GO", "", "503", "503", "200")
	call("POST no key", "POST", "/orders", "", "503")
	call("POST with key", "POST", "/orders", "k-7f3a", "503", "201")
	call("GET throttled", "GET", "/quotes/GO", "", "429:2", "200")
	call("GET outage", "GET", "/quotes/GO", "", "503", "503")
	call("GET outage", "GET", "/quotes/GO", "", "503")
	call("GET while open", "GET", "/quotes/GO", "")
	clock.Sleep(31 * time.Second)
	call("GET probe", "GET", "/quotes/GO", "", "200")
	fmt.Println("upstream calls:", up.calls, "for 8 client requests; breaker open:", rt.Breaker.Open())
}

// realClock sleeps on a timer but wakes as soon as the request is canceled.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

func (realClock) Sleep(ctx context.Context, d time.Duration) error {
	if deadline, ok := ctx.Deadline(); ok && time.Until(deadline) < d {
		return context.DeadlineExceeded // the wait cannot finish in time: give up now
	}
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-t.C:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

