import (
	"bytes"
	"compress/gzip"
	"errors"
	"fmt"
	"html"
	"io"
	"mime"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync"

	"github.com/gin-gonic/gin"
)

const minSize = 512 // below this, gzip framing and CPU cost more than they save

// acceptsGzip applies q-values: an explicit gzip entry beats *, and q=0
// means "not acceptable". Several Accept-Encoding lines form one list.
func acceptsGzip(values []string) bool {
	gzipQ, anyQ := -1.0, -1.0
	for part := range strings.SplitSeq(strings.Join(values, ","), ",") {
		coding, params, _ := strings.Cut(part, ";")
		q := 1.0
		for p := range strings.SplitSeq(params, ";") {
			if v, ok := strings.CutPrefix(strings.ToLower(strings.TrimSpace(p)), "q="); ok {
				if f, err := strconv.ParseFloat(v, 64); err == nil && f >= 0 && f <= 1 {
					q = f
				} else {
					q = 0
				}
			}
		}
		switch strings.ToLower(strings.TrimSpace(coding)) {
		case "gzip", "x-gzip":
			gzipQ = q
		case "*":
			anyQ = q
		}
	}
	if gzipQ >= 0 {
		return gzipQ > 0
	}
	return anyQ > 0
}

// compressible is an allow-list: images, archives, video and fonts are
// already compressed, and an event stream must leave event by event.
func compressible(contentType string) bool {
	mt, _, err := mime.ParseMediaType(contentType)
	if err != nil || mt == "text/event-stream" {
		return false
	}
	return strings.HasPrefix(mt, "text/") || mt == "application/json" || mt == "application/javascript" ||
		mt == "image/svg+xml" || strings.HasSuffix(mt, "+json") || strings.HasSuffix(mt, "+xml")
}

func addVary(h http.Header, field string) {
	for _, v := range h.Values("Vary") {
		for f := range strings.SplitSeq(v, ",") {
			if strings.EqualFold(strings.TrimSpace(f), field) {
				return
			}
		}
	}
	h.Add("Vary", field)
}

var gzPool = sync.Pool{New: func() any { return gzip.NewWriter(io.Discard) }}

// gzipWriter buffers the first bytes so the decision can see the status,
// the headers and whether the body is big enough to be worth compressing.
type gzipWriter struct {
	gin.ResponseWriter
	accepts  bool
	disabled bool
	decided  bool
	buf      []byte
	gz       *gzip.Writer
}

func (w *gzipWriter) decide(sizeKnown bool) {
	if w.decided {
		return
	}
	w.decided = true
	h, status := w.Header(), w.Status()
	if status == http.StatusNotModified {
		addVary(h, "Accept-Encoding") // a 304 repeats the Vary of the 200 it stands for
		return
	}
	if w.disabled || status < 200 || status == http.StatusNoContent || status == http.StatusPartialContent ||
		h.Get("Content-Encoding") != "" || !compressible(h.Get("Content-Type")) {
		return
	}
	addVary(h, "Accept-Encoding") // caches must key this URL by Accept-Encoding
	if !w.accepts || (sizeKnown && len(w.buf) < minSize) {
		return
	}
	h.Set("Content-Encoding", "gzip")
	h.Del("Content-Length") // it described the uncompressed bytes
	h.Del("Accept-Ranges")  // ranges would now address the compressed stream
	if etag := h.Get("ETag"); strings.HasPrefix(etag, `"`) {
		h.Set("ETag", "W/"+etag) // different bytes, so no longer a strong validator
	}
	w.gz = gzPool.Get().(*gzip.Writer)
	w.gz.Reset(w.ResponseWriter)
}

func (w *gzipWriter) flushBuf() error {
	buf := w.buf
	w.buf = nil
	if len(buf) == 0 {
		return nil
	}
	if w.gz != nil {
		_, err := w.gz.Write(buf)
		return err
	}
	_, err := w.ResponseWriter.Write(buf)
	return err
}

func (w *gzipWriter) Write(p []byte) (int, error) {
	if !w.decided {
		w.buf = append(w.buf, p...)
		if len(w.buf) < minSize {
			return len(p), nil
		}
		w.decide(false)
		return len(p), w.flushBuf()
	}
	if w.gz != nil {
		return w.gz.Write(p)
	}
	return w.ResponseWriter.Write(p)
}

// Every write path must go through the wrapper, or bytes bypass gzip.
func (w *gzipWriter) WriteString(s string) (int, error) { return w.Write([]byte(s)) }

func (w *gzipWriter) Written() bool { return len(w.buf) > 0 || w.ResponseWriter.Written() }

func (w *gzipWriter) WriteHeaderNow() {
	w.decide(false)
	w.flushBuf()
	w.ResponseWriter.WriteHeaderNow()
}

func (w *gzipWriter) Flush() {
	w.decide(false)
	w.flushBuf()
	if w.gz != nil {
		w.gz.Flush()
	}
	w.ResponseWriter.Flush()
}

func (w *gzipWriter) Unwrap() http.ResponseWriter { return w.ResponseWriter }

func (w *gzipWriter) finish() {
	w.decide(true)
	w.flushBuf()
	if w.gz != nil {
		w.gz.Close() // writes the gzip trailer
		gzPool.Put(w.gz)
		w.gz = nil
	}
}

func Compress() gin.HandlerFunc {
	return func(c *gin.Context) {
		if c.Request.Method == http.MethodHead {
			c.Next() // no body to compress
			return
		}
		w := &gzipWriter{ResponseWriter: c.Writer, accepts: acceptsGzip(c.Request.Header.Values("Accept-Encoding"))}
		c.Writer = w
		c.Next()
		w.finish()
		c.Writer = w.ResponseWriter
	}
}

// NoCompression opts one response out: use it for pages that mix a secret
// with reflected input, the precondition for BREACH.
func NoCompression(c *gin.Context) {
	if w, ok := c.Writer.(*gzipWriter); ok {
		w.disabled = true
	}
}

// GunzipBody accepts gzip request bodies and bounds the compressed and
// the decompressed size separately.
func GunzipBody(maxWire, maxDecoded int64) gin.HandlerFunc {
	return func(c *gin.Context) {
		switch strings.ToLower(c.GetHeader("Content-Encoding")) {
		case "":
			c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, maxDecoded)
			c.Next()
			return
		case "gzip":
		default:
			c.Header("Accept-Encoding", "gzip") // RFC 7694: say what would work
			c.AbortWithStatusJSON(http.StatusUnsupportedMediaType, gin.H{"error": "unsupported_content_encoding"})
			return
		}
		zr, err := gzip.NewReader(http.MaxBytesReader(c.Writer, c.Request.Body, maxWire))
		if err != nil {
			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "invalid_gzip"})
			return
		}
		c.Request.Body = http.MaxBytesReader(c.Writer, zr, maxDecoded)
		c.Request.Header.Del("Content-Encoding")
		c.Request.ContentLength = -1
		c.Next()
	}
}

func gzipped(b []byte) []byte {
	var buf bytes.Buffer
	zw := gzip.NewWriter(&buf)
	zw.Write(b)
	zw.Close()
	return buf.Bytes()
}

func main() {
	gin.SetMode(gin.TestMode)
	report := []byte("region,orders,total\n" + strings.Repeat("eu-west,1200,98000.00\n", 180))
	r := gin.New()
	r.Use(Compress())
	r.GET("/report", func(c *gin.Context) {
		c.Header("ETag", `"r1"`)
		if strings.TrimPrefix(c.GetHeader("If-None-Match"), "W/") == `"r1"` {
			c.Status(http.StatusNotModified)
			return
		}
		c.Data(http.StatusOK, "text/csv; charset=utf-8", report)
	})
	r.GET("/small", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"ok": true}) })
	r.GET("/logo.png", func(c *gin.Context) { c.Data(http.StatusOK, "image/png", make([]byte, 2048)) })
	r.GET("/events", func(c *gin.Context) {
		c.Header("Content-Type", "text/event-stream")
		for i := 1; i <= 3; i++ {
			fmt.Fprintf(c.Writer, "data: tick %d\n\n", i)
			c.Writer.Flush()
		}
	})
	r.GET("/account", func(c *gin.Context) {
		NoCompression(c) // the CSRF token and the reflected query share one body
		page := `<form><input type="hidden" name="csrf" value="tok-test-9f2c">` +
			"<p>Results for " + html.EscapeString(c.Query("q")) + "</p>" + strings.Repeat("<li>row</li>", 60) + "</form>"
		c.Data(http.StatusOK, "text/html; charset=utf-8", []byte(page))
	})
	r.POST("/import", GunzipBody(64<<10, 1<<20), func(c *gin.Context) {
		data, err := io.ReadAll(c.Request.Body)
		var tooBig *http.MaxBytesError
		switch {
		case errors.As(err, &tooBig):
			c.JSON(http.StatusRequestEntityTooLarge, gin.H{"error": "body_too_large", "limit": tooBig.Limit})
		case err != nil:
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid_body"})
		default:
			c.JSON(http.StatusOK, gin.H{"imported": len(data)})
		}
	})

	show := func(label string, req *http.Request) {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		body := w.Body.Bytes()
		enc := w.Header().Get("Content-Encoding")
		if enc == "gzip" {
			zr, err := gzip.NewReader(bytes.NewReader(body))
			if err == nil {
				body, err = io.ReadAll(zr)
			}
			if err != nil {
				fmt.Println(label, "corrupt gzip:", err)
				return
			}
		}
		line := fmt.Sprintf("%-14s %d enc=%s vary=%s", label, w.Code, cmpOr(enc, "-"), cmpOr(w.Header().Get("Vary"), "-"))
		if etag := w.Header().Get("ETag"); etag != "" {
			line += " etag=" + etag
		}
		if strings.HasPrefix(w.Header().Get("Content-Type"), "application/json") {
			line += " " + string(body)
		} else {
			line += " body=" + strconv.Itoa(len(body))
		}
		if enc == "gzip" {
			line += " smaller=" + strconv.FormatBool(w.Body.Len() < len(body))
		}
		fmt.Println(line)
	}
	get := func(path, acceptEncoding string, kv ...string) *http.Request {
		req := httptest.NewRequest(http.MethodGet, path, nil)
		if acceptEncoding != "" {
			req.Header.Set("Accept-Encoding", acceptEncoding)
		}
		for i := 0; i+1 < len(kv); i += 2 {
			req.Header.Set(kv[i], kv[i+1])
		}
		return req
	}
	upload := func(encoding string, body []byte) *http.Request {
		req := httptest.NewRequest(http.MethodPost, "/import", bytes.NewReader(body))
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("Content-Encoding", encoding)
		return req
	}

	show("gzip", get("/report", "gzip, deflate, br"))
	show("gzip;q=0", get("/report", "gzip;q=0, br"))
	show("*;q=0.5", get("/report", "*;q=0.5"))
	show("no header", get("/report", ""))
	show("revalidate", get("/report", "gzip", "If-None-Match", `W/"r1"`))
	show("small json", get("/small", "gzip"))
	show("png", get("/logo.png", "gzip"))
	show("sse", get("/events", "gzip"))
	show("breach opt-out", get("/account?q=reflected", "gzip"))
	rows := []byte(`[` + strings.Repeat(`{"sku":"A-1","qty":3},`, 99) + `{"sku":"A-1","qty":3}]`)
	show("upload gzip", upload("gzip", gzipped(rows)))
	bomb := gzipped(make([]byte, 8<<20))
	fmt.Println("bomb: 8 MiB of zeros, gzip under 64 KiB:", len(bomb) < 64<<10)
	show("upload bomb", upload("gzip", bomb))
	show("upload br", upload("br", []byte("x")))
}

func cmpOr(s, fallback string) string {
	if s == "" {
		return fallback
	}
	return s
}

