// Export is a row from your database: the client sends only the ID.
type Export struct {
	Path     string // storage name chosen by the server, relative to the root
	Filename string // the name the user sees; never used to open anything
	ETag     string // a version you already track, quoted and strong
}

var exports = map[string]Export{
	"e-42": {Path: "exports/e-42.csv", Filename: `Q3 "final" résumé.csv`, ETag: `"v3"`},
}

// download serves from an fs.FS. In production that is root.FS() for an
// os.Root opened once at startup; here it is an in-memory fstest.MapFS.
func download(fsys fs.FS) gin.HandlerFunc {
	return func(c *gin.Context) {
		exp, ok := exports[c.Param("id")] // authorize the caller for this ID here
		if !ok {
			c.AbortWithStatusJSON(http.StatusNotFound, gin.H{"error": "unknown_export"})
			return
		}
		f, err := fsys.Open(exp.Path)
		if err != nil {
			c.AbortWithStatusJSON(http.StatusNotFound, gin.H{"error": "unknown_export"})
			return
		}
		defer f.Close()
		info, err := f.Stat()
		content, seekable := f.(io.ReadSeeker)
		if err != nil || !seekable || !info.Mode().IsRegular() {
			c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{"error": "export_unavailable"})
			return
		}
		h := c.Writer.Header()
		h.Set("Content-Type", "text/csv; charset=utf-8") // explicit: no sniffing
		h.Set("Content-Disposition", mime.FormatMediaType("attachment", map[string]string{"filename": exp.Filename}))
		h.Set("ETag", exp.ETag)
		h.Set("Cache-Control", "private, no-cache")
		h.Set("X-Content-Type-Options", "nosniff")
		http.ServeContent(c.Writer, c.Request, "", info.ModTime(), content)
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	data := "region,orders,total\neu-west,1200,98000.00\nus-east,900,71000.00\n"
	fsys := fstest.MapFS{"exports/e-42.csv": &fstest.MapFile{
		Data: []byte(data), ModTime: time.Date(2026, 11, 2, 9, 30, 0, 0, time.UTC)}}

	r := gin.New()
	r.Match([]string{http.MethodGet, http.MethodHead}, "/exports/:id", download(fsys))

	send := func(label, method, path string, kv ...string) *httptest.ResponseRecorder {
		req := httptest.NewRequest(method, path, nil)
		for i := 0; i+1 < len(kv); i += 2 {
			req.Header.Set(kv[i], kv[i+1])
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		h := w.Header()
		line := fmt.Sprintf("%-15s %d", label, w.Code)
		if n := h.Get("Content-Length"); n != "" && !strings.HasPrefix(h.Get("Content-Type"), "multipart/") {
			line += " len=" + n
		}
		if cr := h.Get("Content-Range"); cr != "" {
			line += " range=" + cr
		}
		if mt, _, _ := mime.ParseMediaType(h.Get("Content-Type")); mt == "multipart/byteranges" {
			line += " type=" + mt
		} else if w.Code == http.StatusPartialContent {
			line += fmt.Sprintf(" body=%q", w.Body.String())
		}
		line += " etag=" + cmpOr(h.Get("ETag"), "-")
		fmt.Println(line)
		return w
	}

	first := send("GET", "GET", "/exports/e-42")
	fmt.Println("  Accept-Ranges:", first.Header().Get("Accept-Ranges"))
	fmt.Println("  Last-Modified:", first.Header().Get("Last-Modified"))
	fmt.Println("  Content-Disposition:", first.Header().Get("Content-Disposition"))
	send("HEAD", "HEAD", "/exports/e-42")
	send("first 10 bytes", "GET", "/exports/e-42", "Range", "bytes=0-9")
	send("last 9 bytes", "GET", "/exports/e-42", "Range", "bytes=-9")
	send("two ranges", "GET", "/exports/e-42", "Range", "bytes=0-5,20-26")
	send("past the end", "GET", "/exports/e-42", "Range", "bytes=500-")
	send("If-Range fresh", "GET", "/exports/e-42", "Range", "bytes=20-26", "If-Range", `"v3"`)
	send("If-Range stale", "GET", "/exports/e-42", "Range", "bytes=20-26", "If-Range", `"v2"`)
	send("If-None-Match", "GET", "/exports/e-42", "If-None-Match", `"v3"`)
	send("unknown id", "GET", "/exports/e-7")

	// c.FileAttachment builds the header itself; compare it on a temp file.
	tmp, err := os.CreateTemp("", "gf-export-*.csv")
	if err != nil {
		panic(err)
	}
	defer os.Remove(tmp.Name())
	tmp.WriteString(data)
	tmp.Close()
	for _, name := range []string{`Q3 "final".csv`, "résumé 2026.csv"} {
		w := httptest.NewRecorder()
		c, _ := gin.CreateTestContext(w)
		c.Request = httptest.NewRequest(http.MethodGet, "/download", nil)
		c.Request.Header.Set("Range", "bytes=0-5")
		c.FileAttachment(tmp.Name(), name)
		fmt.Printf("FileAttachment  %d %s\n", w.Code, w.Header().Get("Content-Disposition"))
		fmt.Printf("FormatMediaType     %s\n", mime.FormatMediaType("attachment", map[string]string{"filename": name}))
	}
}

func cmpOr(s, fallback string) string {
	if s == "" {
		return fallback
