package main

import (
	"bytes"
	"cmp"
	"encoding/csv"
	"fmt"
	"html/template"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"

	"github.com/gin-gonic/gin"
	"github.com/gin-gonic/gin/binding"
)

const mimeCSV = "text/csv"

// offers is the server's preference order; ties go to the earlier entry.
var offers = []string{binding.MIMEJSON, mimeCSV, binding.MIMEHTML}

// negotiate follows RFC 9110 section 12.5.1: each offer takes the q of the
// most specific range that matches it, q=0 excludes, the highest q wins.
func negotiate(accept string, offers []string) string {
	if strings.TrimSpace(accept) == "" {
		return offers[0] // no Accept means any type is acceptable
	}
	best, bestQ := "", 0.0
	for _, offer := range offers {
		q, specificity := 0.0, -1
		for part := range strings.SplitSeq(accept, ",") {
			mediaRange, params, _ := strings.Cut(part, ";")
			s := specificityOf(strings.ToLower(strings.TrimSpace(mediaRange)), offer)
			if s > specificity {
				specificity, q = s, qValue(params)
			}
		}
		if q > bestQ {
			best, bestQ = offer, q
		}
	}
	return best
}

// specificityOf ranks a match: exact type 2, type/* 1, */* 0, no match -1.
func specificityOf(mediaRange, offer string) int {
	switch {
	case mediaRange == offer:
		return 2
	case mediaRange == "*/*":
		return 0
	case strings.HasSuffix(mediaRange, "/*") && strings.HasPrefix(offer, mediaRange[:len(mediaRange)-1]):
		return 1
	}
	return -1
}

func qValue(params string) float64 {
	for p := range strings.SplitSeq(params, ";") {
		if v, ok := strings.CutPrefix(strings.ToLower(strings.TrimSpace(p)), "q="); ok {
			q, err := strconv.ParseFloat(v, 64)
			if err != nil || q < 0 || q > 1 {
				return 0
			}
			return q
		}
	}
	return 1
}

type Row struct {
	Region string `json:"region"`
	Orders int    `json:"orders"`
}

var rows = []Row{{"eu-west", 1200}, {"us-east", 900}}

var formats = map[string]string{"json": binding.MIMEJSON, "csv": mimeCSV, "html": binding.MIMEHTML}

func report(c *gin.Context) {
	format := ""
	if f, ok := c.GetQuery("format"); ok {
		if format, ok = formats[f]; !ok { // the URL names the representation
			c.JSON(http.StatusBadRequest, gin.H{"error": "unknown_format", "formats": []string{"csv", "html", "json"}})
			return
		}
	} else {
		c.Header("Vary", "Accept") // the representation depends on Accept
		format = negotiate(c.GetHeader("Accept"), offers)
	}
	switch format {
	case binding.MIMEJSON:
		c.JSON(http.StatusOK, rows)
	case mimeCSV:
		var buf bytes.Buffer
		w := csv.NewWriter(&buf)
		w.Write([]string{"region", "orders"})
		for _, r := range rows {
			w.Write([]string{r.Region, strconv.Itoa(r.Orders)})
		}
		w.Flush()
		c.Data(http.StatusOK, "text/csv; charset=utf-8", buf.Bytes())
	case binding.MIMEHTML:
		c.HTML(http.StatusOK, "report", rows)
	default:
		c.JSON(http.StatusNotAcceptable, gin.H{"error": "not_acceptable", "available": offers})
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.SetHTMLTemplate(template.Must(template.New("report").Parse(
		`<table>{{range .}}<tr><td>{{.Region}}</td><td>{{.Orders}}</td></tr>{{end}}</table>`)))
	r.GET("/reports/sales", report)
	r.GET("/gin-negotiate", func(c *gin.Context) {
		c.Negotiate(http.StatusOK, gin.Negotiate{Offered: offers, Data: rows})
	})

	ginChoice := func(accept string) string {
		c, _ := gin.CreateTestContext(httptest.NewRecorder())
		c.Request = httptest.NewRequest(http.MethodGet, "/", nil)
		if accept != "" {
			c.Request.Header.Set("Accept", accept)
		}
		return cmp.Or(c.NegotiateFormat(offers...), "(none)")
	}
	fmt.Println("Accept header -> gin.NegotiateFormat | RFC 9110")
	for _, accept := range []string{
		"",
		"text/csv",
		"application/json;q=0.1, text/csv",
		"text/csv;q=0, */*",
		"Application/JSON",
		"image/png",
		"text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
	} {
		fmt.Printf("%q -> %s | %s\n", accept, ginChoice(accept), cmp.Or(negotiate(accept, offers), "(none)"))
	}

	fmt.Println("responses:")
	for _, tc := range []struct{ path, accept string }{
		{"/reports/sales", "application/json"},
		{"/reports/sales", "text/csv"},
		{"/reports/sales", "text/html"},
		{"/reports/sales", "image/png"},
		{"/reports/sales?format=csv", "application/json"},
		{"/reports/sales?format=xml", ""},
		{"/gin-negotiate", "text/csv"},
	} {
		req := httptest.NewRequest(http.MethodGet, tc.path, nil)
		req.Header.Set("Accept", tc.accept)
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		mediaType, _, _ := strings.Cut(w.Header().Get("Content-Type"), ";")
		fmt.Printf("%s Accept=%q -> %d %s vary=%s %s\n", tc.path, tc.accept, w.Code, cmp.Or(mediaType, "-"),
			cmp.Or(w.Header().Get("Vary"), "-"), cmp.Or(strings.ReplaceAll(w.Body.String(), "\n", `\n`), "(no body)"))
	}
}

func TestReportNegotiation(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := newRouter()
	cases := []struct {
		accept, wantType string
		wantStatus       int
	}{
		{"", "application/json", 200},
		{"*/*", "application/json", 200},
		{"text/csv", "text/csv", 200},
		{"application/json;q=0.1, text/csv", "text/csv", 200},
		{"text/csv;q=0, */*", "application/json", 200},
		{"TEXT/HTML", "text/html", 200},
		{"text/html,application/xhtml+xml,*/*;q=0.8", "text/html", 200},
		{"image/png", "application/json", 406},
	}
	for _, tc := range cases {
		req := httptest.NewRequest(http.MethodGet, "/reports/sales", nil)
		req.Header.Set("Accept", tc.accept)
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		mt, _, _ := mime.ParseMediaType(w.Header().Get("Content-Type"))
		if w.Code != tc.wantStatus || mt != tc.wantType || w.Header().Get("Vary") != "Accept" {
			t.Errorf("Accept %q: got %d %s, Vary %q", tc.accept, w.Code, mt, w.Header().Get("Vary"))
		}
	}
}

package main

import (
	"fmt"
	"maps"
	"net/http"
	"net/http/httptest"
	"net/url"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

// Note is the domain type. Neither version's JSON shape lives here.
type Note struct {
	ID      int64
	Author  string
	Created time.Time
}

type Notes struct{ byID map[int64]Note }

func (s *Notes) Get(id int64) (Note, bool) { n, ok := s.byID[id]; return n, ok }

func (s *Notes) List() []Note {
	var out []Note
	for _, id := range slices.Sorted(maps.Keys(s.byID)) {
		out = append(out, s.byID[id])
	}
	return out
}

// v1 wire shape: numeric id, flat author, date only, bare array lists.
type noteV1 struct {
	ID      int64  `json:"id"`
	Author  string `json:"author"`
	Created string `json:"created"`
}

// v2 wire shape: string id, nested author, RFC 3339 time, list envelope.
type authorV2 struct {
	Name string `json:"name"`
}

type noteV2 struct {
	ID        string   `json:"id"`
	Author    authorV2 `json:"author"`
	CreatedAt string   `json:"created_at"`
}

func toV1(n Note) noteV1 {
	return noteV1{ID: n.ID, Author: n.Author, Created: n.Created.Format(time.DateOnly)}
}

func toV2(n Note) noteV2 {
	return noteV2{ID: strconv.FormatInt(n.ID, 10), Author: authorV2{Name: n.Author},
		CreatedAt: n.Created.UTC().Format(time.RFC3339)}
}

// Retirement is the v1 plan, kept in one place for headers and tests.
type Retirement struct {
	Deprecated time.Time
	Sunset     time.Time
	DocsURL    string
	Successors map[string]string // "GET /v1/..." route -> "GET /v2/..." route
}

func deprecated(rt Retirement, now func() time.Time) gin.HandlerFunc {
	deprecation := "@" + strconv.FormatInt(rt.Deprecated.Unix(), 10)
	sunset := rt.Sunset.UTC().Format(http.TimeFormat)
	return func(c *gin.Context) {
		h := c.Writer.Header()
		h.Set("Deprecation", deprecation)
		h.Set("Sunset", sunset)
		links := []string{"<" + rt.DocsURL + `>; rel="deprecation"; type="text/html"`}
		if next, ok := rt.Successors[c.Request.Method+" "+c.FullPath()]; ok {
			_, template, _ := strings.Cut(next, " ")
			links = append(links, "<"+fill(template, c)+`>; rel="successor-version"`)
		}
		h.Set("Link", strings.Join(links, ", "))
		if !now().Before(rt.Sunset) {
			c.AbortWithStatusJSON(http.StatusGone, gin.H{"error": "v1 has been retired; follow the successor-version link"})
			return
		}
		c.Next()
	}
}

// fill turns "/v2/notes/:id" into "/v2/notes/7" using this request's parameters.
func fill(template string, c *gin.Context) string {
	parts := strings.Split(template, "/")
	for i, p := range parts {
		if name, ok := strings.CutPrefix(p, ":"); ok {
			parts[i] = url.PathEscape(c.Param(name))
		}
	}
	return strings.Join(parts, "/")
}

func noteID(c *gin.Context) (int64, bool) {
	id, err := strconv.ParseInt(c.Param("id"), 10, 64)
	return id, err == nil && id > 0
}

func newRouter(notes *Notes, rt Retirement, now func() time.Time) *gin.Engine {
	r := gin.New()
	v1 := r.Group("/v1", deprecated(rt, now))
	v1.GET("/notes", func(c *gin.Context) {
		out := []noteV1{}
		for _, n := range notes.List() {
			out = append(out, toV1(n))
		}
		c.JSON(http.StatusOK, out)
	})
	v1.GET("/notes/:id", func(c *gin.Context) {
		id, ok := noteID(c)
		n, found := notes.Get(id)
		if !ok || !found {
			c.JSON(http.StatusNotFound, gin.H{"error": "note not found"})
			return
		}
		c.JSON(http.StatusOK, toV1(n))
	})
	v2 := r.Group("/v2")
	v2.GET("/notes", func(c *gin.Context) {
		items := []noteV2{}
		for _, n := range notes.List() {
			items = append(items, toV2(n))
		}
		c.JSON(http.StatusOK, gin.H{"items": items, "next": nil})
	})
	v2.GET("/notes/:id", func(c *gin.Context) {
		id, ok := noteID(c)
		n, found := notes.Get(id)
		if !ok || !found {
			c.JSON(http.StatusNotFound, gin.H{"error": "note not found"})
			return
		}
		c.JSON(http.StatusOK, toV2(n))
	})
	return r
}

// checkRetirement is the route-table test: v1 stays until its sunset and
// every v1 route points at a successor that is really registered.
func checkRetirement(routes gin.RoutesInfo, rt Retirement, now time.Time) []string {
	have := map[string]bool{}
	for _, r := range routes {
		have[r.Method+" "+r.Path] = true
	}
	var problems []string
	for _, r := range routes {
		key := r.Method + " " + r.Path
		if strings.HasPrefix(r.Path, "/v1/") && rt.Successors[key] == "" {
			problems = append(problems, key+" has no successor-version mapping")
		}
	}
	for _, old := range slices.Sorted(maps.Keys(rt.Successors)) {
		if !have[old] && now.Before(rt.Sunset) {
			problems = append(problems, old+" removed before its sunset "+rt.Sunset.Format(time.DateOnly))
		}
		if next := rt.Successors[old]; !have[next] {
			problems = append(problems, "successor "+next+" is not registered")
		}
	}
	slices.Sort(problems)
	return problems
}

func report(label string, problems []string) {
	if len(problems) == 0 {
		fmt.Println(label + ": ok")
		return
	}
	for _, p := range problems {
		fmt.Println(label + ": " + p)
	}
}

func main() {
	gin.SetMode(gin.TestMode)
	notes := &Notes{byID: map[int64]Note{
		7: {ID: 7, Author: "Platform Team", Created: time.Date(2026, 11, 1, 9, 30, 0, 0, time.UTC)},
	}}
	rt := Retirement{
		Deprecated: time.Date(2026, 11, 1, 0, 0, 0, 0, time.UTC),
		Sunset:     time.Date(2027, 5, 1, 0, 0, 0, 0, time.UTC),
		DocsURL:    "https://docs.example.com/api/v1-retirement",
		Successors: map[string]string{
			"GET /v1/notes":     "GET /v2/notes",
			"GET /v1/notes/:id": "GET /v2/notes/:id",
		},
	}
	today := time.Date(2026, 11, 18, 12, 0, 0, 0, time.UTC)
	afterSunset := time.Date(2027, 5, 2, 0, 0, 0, 0, time.UTC)
	clock := today
	r := newRouter(notes, rt, func() time.Time { return clock })

	call := func(path string) {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, path, nil))
		fmt.Println(clock.Format(time.DateOnly), "GET", path, w.Code, w.Body.String())
		for _, k := range []string{"Deprecation", "Sunset", "Link"} {
			if v := w.Header().Get(k); v != "" {
				fmt.Printf("  %s: %s\n", k, v)
			}
		}
	}
	call("/v1/notes/7")
	call("/v2/notes/7")
	call("/v2/notes")
	clock = afterSunset
	call("/v1/notes")

	routes := r.Routes()
	report("table today", checkRetirement(routes, rt, today))
	trimmed := slices.DeleteFunc(slices.Clone(routes), func(ri gin.RouteInfo) bool {
		return ri.Method == http.MethodGet && ri.Path == "/v1/notes"
	})
	report("v1 list deleted today", checkRetirement(trimmed, rt, today))
	report("v1 list deleted after sunset", checkRetirement(trimmed, rt, afterSunset))
}

func TestV1RoutesSurviveUntilSunset(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := newRouter(seedNotes(), retirement, time.Now)
	for _, problem := range checkRetirement(r.Routes(), retirement, time.Now()) {
		t.Error(problem)
	}
}

func TestCheckRetirementAroundSunset(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := newRouter(seedNotes(), retirement, time.Now)
	routes := slices.DeleteFunc(r.Routes(), func(ri gin.RouteInfo) bool {
		return ri.Method == http.MethodGet && ri.Path == "/v1/notes"
	})
	if got := checkRetirement(routes, retirement, retirement.Sunset.Add(-time.Hour)); len(got) != 1 {
		t.Fatalf("before sunset: got %q, want one removal finding", got)
	}
	if got := checkRetirement(routes, retirement, retirement.Sunset); len(got) != 0 {
		t.Fatalf("at sunset: got %q, want none", got)
	}
}

