import (
	"encoding/json"
	"fmt"
	"maps"
	"net/http"
	"net/http/httptest"
	"slices"
	"strconv"
	"strings"
	"sync"

	"github.com/gin-gonic/gin"
)

// In the service this is //go:embed openapi.json; a constant keeps the example in one file.
const openAPI = `{
  "openapi": "3.1.0",
  "info": {"title": "notes", "version": "2.3.0"},
  "paths": {
    "/v2/notes": {
      "get": {"responses": {"200": {"description": "a page of notes"}}},
      "post": {"responses": {"201": {"description": "created"}, "400": {"description": "invalid note"}}}
    },
    "/v2/notes/{id}": {
      "parameters": [{"name": "id", "in": "path", "required": true, "schema": {"type": "string"}}],
      "get": {"responses": {"200": {"description": "the note"}, "4XX": {"description": "client error"}}},
      "delete": {"responses": {"204": {"description": "deleted"}}}
    },
    "/v2/files/{path}": {
      "get": {"responses": {"200": {"description": "file bytes"}}}
    }
  }
}`

var httpMethods = []string{"get", "put", "post", "delete", "options", "head", "patch", "trace"}

// operations maps "METHOD /template" to the declared response codes.
func operations(doc []byte) (map[string][]string, error) {
	var spec struct {
		Paths map[string]map[string]json.RawMessage `json:"paths"`
	}
	if err := json.Unmarshal(doc, &spec); err != nil {
		return nil, err
	}
	ops := map[string][]string{}
	for path, item := range spec.Paths {
		for _, m := range httpMethods {
			raw, ok := item[m]
			if !ok {
				continue
			}
			var op struct {
				Responses map[string]json.RawMessage `json:"responses"`
			}
			if err := json.Unmarshal(raw, &op); err != nil {
				return nil, fmt.Errorf("%s %s: %w", m, path, err)
			}
			ops[strings.ToUpper(m)+" "+path] = slices.Sorted(maps.Keys(op.Responses))
		}
	}
	return ops, nil
}

// template converts Gin's /notes/:id and /files/*path to /notes/{id} and /files/{path}.
func template(ginPath string) (string, bool) {
	parts := strings.Split(ginPath, "/")
	catchAll := false
	for i, p := range parts {
		switch {
		case strings.HasPrefix(p, ":"):
			parts[i] = "{" + p[1:] + "}"
		case strings.HasPrefix(p, "*"):
			parts[i] = "{" + p[1:] + "}"
			catchAll = true
		}
	}
	return strings.Join(parts, "/"), catchAll
}

func declared(codes []string, status int) bool {
	s := strconv.Itoa(status)
	return slices.Contains(codes, s) || slices.Contains(codes, s[:1]+"XX") || slices.Contains(codes, "default")
}

// observed records which status each route template actually answered with.
type observed struct {
	mu   sync.Mutex
	seen map[string]map[int]bool
}

func (o *observed) middleware(c *gin.Context) {
	c.Next()
	if c.FullPath() == "" {
		return // unmatched requests are not operations
	}
	t, _ := template(c.FullPath())
	key := c.Request.Method + " " + t
	o.mu.Lock()
	defer o.mu.Unlock()
	if o.seen[key] == nil {
		o.seen[key] = map[int]bool{}
	}
	o.seen[key][c.Writer.Status()] = true
}

func drift(routes gin.RoutesInfo, ops map[string][]string, seen map[string]map[int]bool, internal map[string]bool) []string {
	var out []string
	routed := map[string]bool{}
	for _, r := range routes {
		t, catchAll := template(r.Path)
		key := r.Method + " " + t
		routed[key] = true
		if internal[r.Method+" "+r.Path] {
			continue
		}
		if _, ok := ops[key]; !ok {
			out = append(out, "route missing from spec: "+key)
		}
		if catchAll {
			out = append(out, "warning: "+key+" is a Gin catch-all; OpenAPI {param} matches one segment")
		}
	}
	for key, codes := range ops {
		if !routed[key] {
			out = append(out, "spec operation without route: "+key)
		}
		for status := range seen[key] {
			if !declared(codes, status) {
				out = append(out, fmt.Sprintf("undeclared status: %s answered %d, spec declares %s", key, status, strings.Join(codes, " ")))
			}
		}
	}
	slices.Sort(out)
	return out
}

func newRouter(obs *observed) *gin.Engine {
	r := gin.New()
	r.Use(obs.middleware)
	r.GET("/healthz", func(c *gin.Context) { c.String(http.StatusOK, "ok") })
	v2 := r.Group("/v2")
	v2.GET("/notes", func(c *gin.Context) { c.JSON(http.StatusOK, gin.H{"items": []string{}}) })
	v2.POST("/notes", func(c *gin.Context) {
		var in struct {
			Title string `json:"title" binding:"required"`
		}
		if err := c.ShouldBindJSON(&in); err != nil {
			c.JSON(http.StatusUnprocessableEntity, gin.H{"error": "title is required"})
			return
		}
		c.JSON(http.StatusCreated, gin.H{"id": "8", "title": in.Title})
	})
	v2.GET("/notes/:id", func(c *gin.Context) {
		if c.Param("id") != "7" {
			c.JSON(http.StatusNotFound, gin.H{"error": "note not found"})
			return
		}
		c.JSON(http.StatusOK, gin.H{"id": "7"})
	})
	v2.PATCH("/notes/:id", func(c *gin.Context) { c.Status(http.StatusNoContent) })
	v2.GET("/files/*path", func(c *gin.Context) { c.String(http.StatusOK, "file %s", c.Param("path")) })
	return r
}

func main() {
	gin.SetMode(gin.TestMode)
	ops, err := operations([]byte(openAPI))
	if err != nil {
		panic(err)
	}
	obs := &observed{seen: map[string]map[int]bool{}}
	r := newRouter(obs)
	calls := []struct{ method, path, body string }{
		{"GET", "/v2/notes", ""},
		{"POST", "/v2/notes", `{"title":"retro"}`},
		{"POST", "/v2/notes", `{}`},
		{"GET", "/v2/notes/7", ""},
		{"GET", "/v2/notes/99", ""},
		{"GET", "/v2/files/a/b.txt", ""},
		{"GET", "/v2/typo", ""},
	}
	for _, tc := range calls {
		req := httptest.NewRequest(tc.method, tc.path, strings.NewReader(tc.body))
		req.Header.Set("Content-Type", "application/json")
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Println(tc.method, tc.path, w.Code)
	}
	problems := drift(r.Routes(), ops, obs.seen, map[string]bool{"GET /healthz": true})
	for _, p := range problems {
		fmt.Println(p)
	}
	fmt.Printf("%d operations in spec, %d findings\n", len(ops), len(problems))
}

