	}
	internal := map[string]bool{"GET /healthz": true, "GET /openapi.json": true}
	for _, finding := range drift(r.Routes(), ops, obs.seen, internal) {
		t.Error(finding)
	}
}

package main

import (
	"crypto/subtle"
	"encoding/json"
	"expvar"
	"fmt"
	"net/http"
	"net/http/httptest"
	"net/http/pprof"
	"net/netip"
	"slices"
	"strings"

	"github.com/gin-gonic/gin"
)

var notesServed = expvar.NewInt("notes_served")

// newPublic is the internet-facing engine. It never touches http.DefaultServeMux.
func newPublic() *gin.Engine {
	r := gin.New()
	r.GET("/notes", func(c *gin.Context) {
		notesServed.Add(1)
		c.JSON(http.StatusOK, gin.H{"items": []string{}})
	})
	return r
}

// adminOnly admits a caller only from an allowed network AND with the admin token.
func adminOnly(allowed []netip.Prefix, token string) gin.HandlerFunc {
	want := []byte("Bearer " + token)
	return func(c *gin.Context) {
		addr, err := netip.ParseAddr(c.RemoteIP())
		if err != nil || !slices.ContainsFunc(allowed, func(p netip.Prefix) bool { return p.Contains(addr.Unmap()) }) {
			c.AbortWithStatus(http.StatusForbidden)
			return
		}
		if subtle.ConstantTimeCompare([]byte(c.GetHeader("Authorization")), want) != 1 {
			c.AbortWithStatus(http.StatusUnauthorized)
			return
		}
		c.Next()
	}
}

// newAdmin is served on a separate, internal-only listener.
func newAdmin(allowed []netip.Prefix, token string) *gin.Engine {
	a := gin.New()
	a.Use(adminOnly(allowed, token))
	pp := a.Group("/debug/pprof")
	pp.GET("/", gin.WrapF(pprof.Index))
	pp.GET("/cmdline", gin.WrapF(pprof.Cmdline))
	pp.GET("/profile", gin.WrapF(pprof.Profile))
	pp.GET("/symbol", gin.WrapF(pprof.Symbol))
	pp.POST("/symbol", gin.WrapF(pprof.Symbol))
	pp.GET("/trace", gin.WrapF(pprof.Trace))
	pp.GET("/:profile", gin.WrapF(pprof.Index)) // heap, goroutine, allocs, block, mutex, threadcreate
	a.GET("/debug/vars", gin.WrapH(expvar.Handler()))
	return a
}

func send(h http.Handler, path, from, auth string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(http.MethodGet, path, nil)
	req.RemoteAddr = from + ":40000"
	if auth != "" {
		req.Header.Set("Authorization", auth)
	}
	w := httptest.NewRecorder()
	h.ServeHTTP(w, req)
	return w
}

func main() {
	gin.SetMode(gin.TestMode)
	public := newPublic()
	admin := newAdmin([]netip.Prefix{netip.MustParsePrefix("127.0.0.0/8"), netip.MustParsePrefix("192.0.2.0/24")}, "example-admin-token")

	// 1. The import of net/http/pprof already registered handlers on the default mux.
	for _, p := range []string{"/debug/pprof/", "/debug/vars"} {
		_, pattern := http.DefaultServeMux.Handler(httptest.NewRequest(http.MethodGet, p, nil))
		fmt.Printf("default mux %-14s -> pattern %q\n", p, pattern)
	}

	// 2. The public engine never consults the default mux: debug paths get Gin's 404 body.
	for _, p := range []string{"/notes", "/debug/pprof/", "/debug/pprof/heap", "/debug/vars"} {
		w := send(public, p, "198.51.100.7", "")
		fmt.Printf("public %-17s %d %q\n", p, w.Code, w.Body.String())
	}

	// 3. A "helpful" fallback to the default mux leaks every side-effect registration,
	// and the status still says 404 because Gin preset it before running NoRoute.
	leaky := newPublic()
	leaky.NoRoute(gin.WrapH(http.DefaultServeMux))
	w := send(leaky, "/debug/pprof/", "198.51.100.7", "")
	fmt.Printf("leaky  %-17s %d %s leaks index=%t\n", "/debug/pprof/", w.Code, w.Header().Get("Content-Type"),
		strings.Contains(w.Body.String(), "Types of profiles available"))

	// 4. The admin engine: network allow-list first, then the token.
	ok := "Bearer example-admin-token"
	fmt.Println("admin from 198.51.100.7:", send(admin, "/debug/pprof/", "198.51.100.7", ok).Code)
	fmt.Println("admin from 192.0.2.10, no token:", send(admin, "/debug/pprof/", "192.0.2.10", "").Code)
	w = send(admin, "/debug/pprof/goroutine?debug=1", "192.0.2.10", ok)
	fmt.Println("admin goroutine profile:", w.Code, w.Header().Get("Content-Type"))
	w = send(admin, "/debug/vars", "127.0.0.1", ok)
	var vars map[string]json.RawMessage
	if err := json.Unmarshal(w.Body.Bytes(), &vars); err != nil {
		panic(err)
	}
	_, hasCmdline := vars["cmdline"]
	fmt.Printf("admin expvar: %d notes_served=%s cmdline published=%t\n", w.Code, vars["notes_served"], hasCmdline)
}

public := &http.Server{Addr: ":8080", Handler: newPublic(), ReadHeaderTimeout: 5 * time.Second}
admin := &http.Server{
	Addr:              "127.0.0.1:6060",
	Handler:           newAdmin(cfg.AdminNetworks, cfg.AdminToken),
	ReadHeaderTimeout: 5 * time.Second,
	WriteTimeout:      10 * time.Second, // pprof extends it by ?seconds=
}
g, ctx := errgroup.WithContext(ctx)
g.Go(func() error { return listen(public) })
g.Go(func() error { return listen(admin) })
g.Go(func() error {
	<-ctx.Done()
	drain, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	return errors.Join(public.Shutdown(drain), admin.Shutdown(drain))
})
return g.Wait()

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"runtime/debug"

	"github.com/gin-gonic/gin"
)

// version is set at link time: go build -ldflags "-X main.version=v1.4.0".
var version = ""

// A fixed build record in the format debug.BuildInfo.String produces.
// In the service, debug.ReadBuildInfo returns the running binary's own record.
const recorded = "go\tgo1.27.3\n" +
	"path\texample.com/notes-api/cmd/api\n" +
	"mod\texample.com/notes-api\tv1.4.0\t\n" +
	"dep\tgithub.com/gin-gonic/gin\tv1.12.0\th1:b3YAbrZtnf8N//yjKeU2+MQsh2mY5htkZidOM7O0wG8=\n" +
	"build\t-buildmode=exe\n" +
	"build\t-compiler=gc\n" +
	"build\t-trimpath=true\n" +
	"build\tCGO_ENABLED=0\n" +
	"build\tGOARCH=amd64\n" +
	"build\tGOOS=linux\n" +
	"build\tGOAMD64=v1\n" +
	"build\tvcs=git\n" +
	"build\tvcs.revision=9f3c2b7d41e0a5c8b6f1e2d3c4b5a69788796a5b\n" +
	"build\tvcs.time=2026-11-17T09:30:00Z\n" +
	"build\tvcs.modified=false\n"

type Version struct {
	Version  string `json:"version"`
	Revision string `json:"revision"`
	Time     string `json:"time"`
	Modified bool   `json:"modified"`
	Go       string `json:"go"`
	Gin      string `json:"gin"`
	Cgo      bool   `json:"cgo"`
}

func versionFrom(bi *debug.BuildInfo, linked string) Version {
	v := Version{Version: linked, Go: bi.GoVersion}
	if v.Version == "" {
		v.Version = bi.Main.Version // "(devel)" when the build had no VCS or tag data
	}
	for _, s := range bi.Settings {
		switch s.Key {
		case "vcs.revision":
			v.Revision = s.Value
		case "vcs.time":
			v.Time = s.Value
		case "vcs.modified":
			v.Modified = s.Value == "true"
		case "CGO_ENABLED":
			v.Cgo = s.Value == "1"
		}
	}
	for _, d := range bi.Deps {
		if d.Path == "github.com/gin-gonic/gin" {
			v.Gin = d.Version
		}
	}
	return v
}

// ginMode validates the mode from the service's own config and defaults to
// release, where Gin itself would default to debug.
func ginMode(configured string) (string, error) {
	switch configured {
	case "":
		return gin.ReleaseMode, nil
	case gin.ReleaseMode, gin.DebugMode, gin.TestMode:
		return configured, nil
	}
	return "", fmt.Errorf("mode %q: want release, debug or test", configured)
}

func newRouter(v Version) *gin.Engine {
	r := gin.New()
	r.Use(gin.Recovery())
	r.GET("/version", func(c *gin.Context) {
		c.Header("Cache-Control", "no-store")
		c.JSON(http.StatusOK, v)
	})
	return r
}

func main() {
	for _, configured := range []string{"", "debug", "production"} {
		mode, err := ginMode(configured)
		fmt.Printf("config %q -> mode %q, err %v\n", configured, mode, err)
	}

	func() {
		defer func() { fmt.Println("gin.SetMode(\"production\") panics:", recover()) }()
		gin.SetMode("production")
	}()
	gin.SetMode(gin.ReleaseMode) // no route table or debug warnings on stdout
	fmt.Println("mode", gin.Mode(), "debugging", gin.IsDebugging())

	bi, err := debug.ParseBuildInfo(recorded)
	if err != nil {
		panic(err)
	}
	fmt.Printf("parsed GoVersion %q: ParseBuildInfo skips the go line\n", bi.GoVersion)
	bi.GoVersion = "go1.27.3" // ReadBuildInfo fills this from runtime.Version()

	for _, linked := range []string{version, "v1.4.0-rc.2"} {
		w := httptest.NewRecorder()
		newRouter(versionFrom(bi, linked)).ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/version", nil))
		fmt.Println(w.Code, w.Body.String())
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync"
	"sync/atomic"
	"time"

	"github.com/gin-gonic/gin"
)

// Clock is the drain sequence's only source of time.
type Clock interface {
	After(d time.Duration) <-chan time.Time
}

// Server is the part of *http.Server the sequence uses; *http.Server satisfies it.
type Server interface {
	SetKeepAlivesEnabled(bool)
	Shutdown(context.Context) error
	Close() error
}

// Lifecycle owns the readiness flag; handlers read it, Drain writes it.
type Lifecycle struct{ draining atomic.Bool }

func (l *Lifecycle) Readyz(c *gin.Context) {
	if l.draining.Load() {
		c.String(http.StatusServiceUnavailable, "draining")
		return
	}
	c.String(http.StatusOK, "ready")
}

// Drain runs once SIGTERM arrives: readiness, delay, graceful Shutdown, then Close.
func Drain(sigterm <-chan struct{}, lc *Lifecycle, srv Server, clock Clock, delay, budget time.Duration, step func(string)) error {
	<-sigterm
	lc.draining.Store(true)
	srv.SetKeepAlivesEnabled(false)
	wait := clock.After(delay)
	step("SIGTERM: readiness 503, keep-alives off, still serving for " + delay.String())
	<-wait

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	expired := clock.After(budget)
	go func() {
		select {
		case <-expired:
			cancel()
		case <-ctx.Done():
		}
	}()
	step("delay over: Shutdown closes the listener, budget " + budget.String())
	if err := srv.Shutdown(ctx); err != nil {
		srv.Close()
		return fmt.Errorf("drain budget exceeded, connections closed: %w", err)
	}
	return nil
}

// fakeClock fires timers only when Advance is called.
type fakeClock struct {
	mu     sync.Mutex
	now    time.Duration
	timers map[chan time.Time]time.Duration
}

func (c *fakeClock) After(d time.Duration) <-chan time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	ch := make(chan time.Time, 1)
	c.timers[ch] = c.now + d
	return ch
}

func (c *fakeClock) Elapsed() time.Duration {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now += d
	for ch, at := range c.timers {
		if at <= c.now {
			ch <- time.Time{}.Add(at)
			delete(c.timers, ch)
		}
	}
}

// fakeServer models what http.Server does with a handler, without sockets.
type fakeServer struct {
	h        http.Handler
	mu       sync.Mutex
	closed   bool
	noKeep   atomic.Bool
	inflight sync.WaitGroup
	shutdown chan struct{} // closed once the listener is gone
}

func (s *fakeServer) Do(path string) (*httptest.ResponseRecorder, error) {
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return nil, errors.New("connection refused")
	}
	s.inflight.Add(1)
	s.mu.Unlock()
	defer s.inflight.Done()
	w := httptest.NewRecorder()
	if s.noKeep.Load() {
		w.Header().Set("Connection", "close") // net/http adds this when keep-alives are off
	}
	s.h.ServeHTTP(w, httptest.NewRequest(http.MethodGet, path, nil))
	return w, nil
}

func (s *fakeServer) SetKeepAlivesEnabled(v bool) { s.noKeep.Store(!v) }

func (s *fakeServer) Shutdown(ctx context.Context) error {
	s.mu.Lock()
	s.closed = true
	s.mu.Unlock()
	close(s.shutdown)
	done := make(chan struct{})
	go func() { s.inflight.Wait(); close(done) }()
	select {
	case <-done:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (s *fakeServer) Close() error { return nil }

func newRouter(lc *Lifecycle, entered chan<- struct{}, release <-chan struct{}) *gin.Engine {
	r := gin.New()
	r.GET("/readyz", lc.Readyz)
	r.GET("/orders", func(c *gin.Context) { c.String(http.StatusOK, "orders") })
	r.GET("/export", func(c *gin.Context) {
		entered <- struct{}{}
		<-release // a slow request that is in flight when SIGTERM arrives
		c.String(http.StatusOK, "export done")
	})
	return r
}

func run(name string, exportFinishes bool) {
	fmt.Println("==", name)
	lc := &Lifecycle{}
	entered, release := make(chan struct{}), make(chan struct{})
	srv := &fakeServer{h: newRouter(lc, entered, release), shutdown: make(chan struct{})}
	clock := &fakeClock{timers: map[chan time.Time]time.Duration{}}
	sigterm, steps, result := make(chan struct{}), make(chan string), make(chan error)
	go func() {
		result <- Drain(sigterm, lc, srv, clock, 5*time.Second, 20*time.Second, func(s string) { steps <- s })
	}()
	at := func(format string, args ...any) {
		fmt.Printf("t+%-3s "+format+"\n", append([]any{clock.Elapsed().String()}, args...)...)
	}
	get := func(path string) {
		w, err := srv.Do(path)
		if err != nil {
			at("GET %-7s %v", path, err)
			return
		}
		conn := w.Header().Get("Connection")
		if conn == "" {
			conn = "keep-alive"
		}
		at("GET %-7s %d %s, connection %s", path, w.Code, w.Body.String(), conn)
	}

	get("/readyz")
	exported := make(chan *httptest.ResponseRecorder)
	go func() { w, _ := srv.Do("/export"); exported <- w }()
	<-entered

	close(sigterm)
	at("%s", <-steps)
	get("/readyz")
	get("/orders")

	clock.Advance(5 * time.Second)
	at("%s", <-steps)
	<-srv.shutdown
	get("/orders")

	if exportFinishes {
		close(release)
		w := <-exported
		at("in-flight /export finished: %d %s", w.Code, w.Body.String())
		at("Drain returned %v", <-result)
		return
	}
	clock.Advance(20 * time.Second)
	at("Drain returned %v", <-result)
	close(release)
	<-exported
}

func main() {
	gin.SetMode(gin.TestMode)
	run("export finishes inside the budget", true)
	run("export ignores the budget", false)
}

type realClock struct{}

func (realClock) After(d time.Duration) <-chan time.Time { return time.After(d) }

func serve(srv *http.Server, lc *Lifecycle, delay, budget time.Duration) error {
	sigterm := make(chan struct{})
	sigs := make(chan os.Signal, 1)
	signal.Notify(sigs, syscall.SIGTERM, os.Interrupt)
	go func() { <-sigs; signal.Stop(sigs); close(sigterm) }()

	drained := make(chan error, 1)
	go func() {
		drained <- Drain(sigterm, lc, srv, realClock{}, delay, budget, func(s string) { slog.Info(s) })
	}()
	if err := srv.ListenAndServe(); !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	// ListenAndServe returns as soon as Shutdown starts; requests are
	// still in flight, so wait for Drain before main may return.
	return <-drained
}
